// The artifact host does not serve .glb files: each model ships as base64 text and becomes a Blob here.
var glbCache = {};
function loadGlb(viewer, path) {
  if (!glbCache[path]) {
    glbCache[path] = fetch(path).then(function (r) {
      if (!r.ok) { throw new Error(path + ': HTTP ' + r.status); }
      return r.text();
    }).then(function (text) {
      var raw = atob(text.trim());
      var bytes = new Uint8Array(raw.length);
      for (var i = 0; i < raw.length; i++) { bytes[i] = raw.charCodeAt(i); }
      return URL.createObjectURL(new Blob([bytes], { type: 'model/gltf-binary' }));
    });
  }
  glbCache[path].then(function (url) { viewer.src = url; }, function (err) {
    viewer.insertAdjacentHTML('afterend', '<p class="code">Could not load the model: ' + err.message + '</p>');
  });
}
function loadModels() {
  Array.prototype.forEach.call(document.querySelectorAll('model-viewer[data-glb]'), function (viewer) {
    if (!viewer.src) { loadGlb(viewer, viewer.getAttribute('data-glb')); }
  });
}
document.getElementById('tab-models').addEventListener('click', loadModels);
if (location.hash === '#models') { loadModels(); }

