#include "Core/JamTypes.h"
#include "CoreMinimal.h"
#include "GameFramework/Actor.h"
#include "Sim/JamLayerRules.h"

#include "JamFighterView.generated.h"

class UPointLightComponent;
class USceneComponent;
class UStaticMeshComponent;

/**
 * A fighter as the player sees it. The same class draws the hero and the boss, only the size and the colour differ.
 *
 * Stand-ins until the art arrives: the full look is a ronin of basic shapes (body, head, hat, two arms, a blade) with a
 * glow and a walk; the last cosmetic layer leaves the bean with a visor. Which layers are left is FJamLayers: the hero
 * loses them to the Publisher's cuts, the boss keeps all of them.
 */
UCLASS()
class JAMGAME_API AJamFighterView : public AActor
{
	GENERATED_BODY()

public:
	AJamFighterView();

	/** Sizes the shapes around a simulation body of this radius. */
	void Init(float Radius, float MaxSpeed, const FLinearColor& Color);

	/** Switches the look to these layers; nothing happens when they did not change. */
	void SetLayers(const FJamLayers& InLayers);

	/** The fighter lost health at Time: the body goes white for a moment, Weight (0 to 1) of the way. */
	void Flash(float Time, float Weight);

	/** Places the view between the last two simulation steps and moves the body. */
	void Sync(const FJamFighter& Fighter, float Alpha, float Time);

	/** Turns the body along Dir now, between simulation steps: the hero follows the live cursor on every frame. */
	void Face(const FVector2D& Dir);

private:
	/** Paints every visible part in its colour, white while flashing, or the grid when the materials are gone. */
	void Repaint();

	/** The walk: bob, lean and arm swing by how fast the body moves. Without the animation layer, the T-pose. */
	void Animate(float Moving, float Time);

	UStaticMeshComponent* AddPart(USceneComponent* Parent, const TCHAR* Name, UStaticMesh* Mesh);

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Body;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Visor;

	/** The ronin hangs off this pivot at the feet, so a lean turns the whole figure. */
	UPROPERTY()
	TObjectPtr<USceneComponent> Ronin;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Torso;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Head;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Eyes;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Hat;

	UPROPERTY()
	TObjectPtr<USceneComponent> ShoulderL;

	UPROPERTY()
	TObjectPtr<USceneComponent> ShoulderR;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> ArmL;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> ArmR;

	UPROPERTY()
	TObjectPtr<UStaticMeshComponent> Blade;

	UPROPERTY()
	TObjectPtr<UPointLightComponent> Glow;

	FJamLayers Shown;
	FLinearColor BaseColor = FLinearColor::White;
	float BodyRadius = 0.f;
	float Speed = 1.f;
	float FlashUntil = 0.f;
	float FlashWeight = 1.f;
	bool bFlashing = false;
};
#pragma once

#include "Core/JamTypes.h"
#include "CoreMinimal.h"

#include "JamLayerRules.generated.h"

/**
 * After which of the Publisher's cuts each cosmetic layer of the hero and the world is gone: the number of the cut,
 * 1 for the first. The values live in the [JamLayers] section of Config/DefaultGame.ini.
 */
USTRUCT()
struct JAMGAME_API FJamLayerSettings
{
	GENERATED_BODY()

	/** The hero's glow, the sweep of his blade, the trail of his dash. */
	UPROPERTY()
	int32 EffectsLostAt = 0;

	/** Colours of the hero and the arena: the world turns into the engine's grey grid. */
	UPROPERTY()
	int32 MaterialsLostAt = 0;

	/** The hero stops moving his body and stands in a T-pose. */
	UPROPERTY()
	int32 AnimationLostAt = 0;

	/** The ronin turns into a bean. */
	UPROPERTY()
	int32 ModelLostAt = 0;

	/** The bars of the HUD go, plain text is left. */
	UPROPERTY()
	int32 HudLostAt = 0;

	/**
	 * How many music stems still play: before the first cut, then after each one. The stems go in the reverse order of
	 * their numbers (the lead first, the drums last); at 0 only the proof-of-concept metronome is left.
	 */
	UPROPERTY()
	TArray<int32> StemsLeft;
};

/** What the player still sees of the full game. The Publisher keeps all of it, always. */
struct FJamLayers
{
	static constexpr int32 Total = 5;

	bool bEffects = true;
	bool bMaterials = true;
	bool bAnimation = true;
	bool bModel = true;
	bool bHud = true;

	int32 Count() const { return (bEffects ? 1 : 0) + (bMaterials ? 1 : 0) + (bAnimation ? 1 : 0) + (bModel ? 1 : 0) + (bHud ? 1 : 0); }

	bool operator==(const FJamLayers& Other) const
	{
		return bEffects == Other.bEffects && bMaterials == Other.bMaterials && bAnimation == Other.bAnimation && bModel == Other.bModel &&
			bHud == Other.bHud;
	}
};

/**
 * The degradation of the game: each cut takes layers away, the stun gives everything back.
 * Tests: Jam.Layers.*
 */
namespace JamLayerRules
{
inline const TCHAR* const Section = TEXT("JamLayers");

/** Stems of the full music: drums, bass, pad, lead. */
inline constexpr int32 StemCount = 4;

/** The layers left after CutsDone cuts. While the boss is stunned and after the win everything is back. */
JAMGAME_API FJamLayers For(int32 CutsDone, EJamPhase Phase, const FJamLayerSettings& Settings);

/** Music stems that play after CutsDone cuts; the whole band while the boss is stunned and after the win. */
JAMGAME_API int32 StemsFor(int32 CutsDone, EJamPhase Phase, const FJamLayerSettings& Settings);
} // namespace JamLayerRules

