#include "View/JamPoseRules.h"

namespace
{
/** Seconds from the fight's step to a later one. */
float SecondsTo(const FJamFight& Fight, int32 Tick)
{
	return FMath::Max(0, Tick - Fight.Tick) * JamSim::StepDt;
}

/** Higher wins when one step starts several actions. */
int32 Rank(EJamClip Clip, bool bFullBody)
{
	switch (Clip)
	{
		case EJamClip::Hit:
			return bFullBody ? 7 : 1;
		case EJamClip::Slam:
			return 6;
		case EJamClip::StrikeA:
		case EJamClip::StrikeB:
			return 4;
		case EJamClip::Parry:
			return 3;
		case EJamClip::Heavy:
			return 2;
		default:
			return 0;
	}
}

void Offer(FJamCue& Best, EJamClip Clip, float Lead, bool bFullBody = false)
{
	if (Rank(Clip, bFullBody) > Rank(Best.Clip, Best.bFullBody))
	{
		Best.Clip = Clip;
		Best.Lead = Lead;
		Best.bFullBody = bFullBody;
	}
}

/** His throws: the memo fans and the shurikens he stole. */
bool IsThrownBy(const FJamFight& Fight, EJamSide Side, int32 ProjectileId)
{
	const FJamProjectile* Shot = Fight.Projectiles.FindByPredicate([ProjectileId](const FJamProjectile& P) { return P.Id == ProjectileId; });
	return Side == EJamSide::Boss && Shot && Shot->Kind != EJamProjectile::Ball;
}
} // namespace

FJamCue JamPoseRules::CueFor(const FJamFight& Fight, EJamSide Side, TConstArrayView<FJamEvent> Events, float HeavyHit)
{
	FJamCue Best;
	const FJamFighter& Me = Fight.Fighters[Side];
	for (const FJamEvent& Event : Events)
	{
		if (Event.Side != Side)
		{
			continue;
		}
		switch (Event.Type)
		{
			case EJamEvent::Swing:
				// The finisher is the first slash again: the second one swings back.
				Offer(Best, FMath::RoundToInt32(Event.Amount) == 2 ? EJamClip::StrikeB : EJamClip::StrikeA, SecondsTo(Fight, Me.Katana.HitTick));
				break;
			case EJamEvent::ParryStarted:
				Offer(Best, EJamClip::Parry, SecondsTo(Fight, Me.Parry.ActiveFromTick));
				break;
			case EJamEvent::UltimateStarted:
				// The Ultimate ranks with the slam: nothing of the same step cuts its wind-up.
				Offer(Best, Side == EJamSide::Boss ? EJamClip::Heavy : EJamClip::StrikeA, SecondsTo(Fight, Me.Ultimate.SlashTick));
				Best.Clip = Best.Clip == EJamClip::None ? EJamClip::Heavy : Best.Clip;
				break;
			case EJamEvent::ProjectileSpawned:
				if (IsThrownBy(Fight, Side, Event.ProjectileId))
				{
					Offer(Best, EJamClip::Heavy, 0.f);
				}
				break;
			case EJamEvent::Stunned:
				Offer(Best, EJamClip::Hit, 0.f, true);
				break;
			case EJamEvent::Hit:
				if (Side == EJamSide::Hero || Event.Amount >= HeavyHit)
				{
					Offer(Best, EJamClip::Hit, 0.f);
				}
				break;
			default:
				break;
		}
	}
	// His slam starts with its circles: the first of the new ones is where the blow lands.
	int32 FirstCircle = MAX_int32;
	for (const FJamHazard& Hazard : Fight.Hazards)
	{
		if (Hazard.Owner == Side && Side == EJamSide::Boss && Hazard.StartTick == Fight.Tick)
		{
			FirstCircle = FMath::Min(FirstCircle, Hazard.HitTick);
		}
	}
	if (FirstCircle != MAX_int32)
	{
		Offer(Best, EJamClip::Slam, SecondsTo(Fight, FirstCircle), true);
	}
	return Best;
}

bool JamPoseRules::IsDown(const FJamFight& Fight, EJamSide Side)
