	{
		const FBoneContainer& Bones = Output.Pose.GetBoneContainer();
		const FReferenceSkeleton& Skeleton = Bones.GetReferenceSkeleton();
		const float Legs = Frame.bFullBody ? 1.f : 1.f - Frame.MoveWeight;
		TArray<bool, TInlineAllocator<64>> Upper;
		Upper.SetNumZeroed(Output.Pose.GetNumBones());
		// Parents come before their children in a compact pose.
		for (const FCompactPoseBoneIndex Bone : Output.Pose.ForEachBoneIndex())
		{
			const FCompactPoseBoneIndex Parent = Output.Pose.GetParentBoneIndex(Bone);
			const FName Name = Skeleton.GetBoneName(Bones.MakeMeshPoseIndex(Bone).GetInt());
			Upper[Bone.GetInt()] = Name == UJamPoseInstance::UpperBodyBone || (Parent.IsValid() && Upper[Parent.GetInt()]);
			Output.Pose[Bone].BlendWith(Action.Pose[Bone], Frame.ActionWeight * (Upper[Bone.GetInt()] ? 1.f : Legs));
		}
	}
};
} // namespace

FAnimInstanceProxy* UJamPoseInstance::CreateAnimInstanceProxy()
{
	return new FJamPoseProxy(this);
}

