	{
		{},
		{ TEXT("/Game/Characters/Publisher/Anims/A_Publisher_Idle.A_Publisher_Idle") },
		{ TEXT("/Game/Characters/Publisher/Anims/A_Publisher_Slow_Orc_Walk.A_Publisher_Slow_Orc_Walk") },
