50	FJamCue JamPoseRules::CueFor(const FJamFight& Fight, EJamSide Side, TConstArrayView<FJamEvent> Events, float HeavyHit)
51	{
52		FBest Best;
53		const FJamFighter& Me = Fight.Fighters[Side];
54		for (const FJamEvent& Event : Events)
55		{
56			if (Event.Side != Side)
57			{
58				continue;
59			}
60			switch (Event.Type)
61			{
62				case EJamEvent::Swing:
63					// The finisher is the first slash again: the second one swings back.
64					Best.Offer(EWhy::Strike, FMath::RoundToInt32(Event.Amount) == 2 ? EJamClip::StrikeB : EJamClip::StrikeA,
65						SecondsTo(Fight, Me.Katana.HitTick));
66					break;
67				case EJamEvent::ParryStarted:
68					Best.Offer(EWhy::Parry, EJamClip::Parry, SecondsTo(Fight, Me.Parry.ActiveFromTick));
69					break;
70				case EJamEvent::UltimateStarted:
71					Best.Offer(EWhy::Ultimate, Side == EJamSide::Boss ? EJamClip::Heavy : EJamClip::StrikeA, SecondsTo(Fight, Me.Ultimate.SlashTick));
72					break;
73				case EJamEvent::ProjectileSpawned:
74					if (IsThrownBy(Fight, Side, Event.ProjectileId))
75					{
76						Best.Offer(EWhy::Throw, EJamClip::Heavy, 0.f);
77					}
78					break;
79				case EJamEvent::Stunned:
80					Best.Offer(EWhy::Stun, EJamClip::Hit, 0.f, true);
81					break;
82				case EJamEvent::Hit:
83					if (Side == EJamSide::Hero || Event.Amount >= HeavyHit)
84					{
85						Best.Offer(EWhy::Hit, EJamClip::Hit, 0.f);
86					}
87					break;
88				default:
89					break;
90			}
91		}
92		// His slam starts with its circles: the first of the new ones is where the blow lands.
93		int32 FirstCircle = MAX_int32;
94		for (const FJamHazard& Hazard : Fight.Hazards)
95		{
96			if (Hazard.Owner == Side && Side == EJamSide::Boss && Hazard.StartTick == Fight.Tick)
97			{
98				FirstCircle = FMath::Min(FirstCircle, Hazard.HitTick);
99			}
100		}
101		if (FirstCircle != MAX_int32)
102		{
103			Best.Offer(EWhy::Slam, EJamClip::Slam, SecondsTo(Fight, FirstCircle), true);
104		}
105		return Best.Cue;
106	}
