#include "View/JamProjectilesView.h"

#include "Components/StaticMeshComponent.h"
#include "View/JamShapes.h"

namespace
{
// The simulation is flat: this is the height the projectiles are drawn at, about the hero's chest.
constexpr float FlightHeight = 110.f;
const FLinearColor HeroShotColor(0.3f, 0.95f, 1.0f);
const FLinearColor BossShotColor(1.0f, 0.25f, 0.2f);
// Shots shine: in the dark arena they are the brightest things that move.
constexpr float ShotGlow = 2.5f;
// Greybox looks of the kinds, in projectile diameters: presentation only. The shapes are drawn larger than the bodies
// that hit, so they can be read from the top-down camera.
constexpr float ShurikenWidth = 2.2f;
constexpr float ShurikenThickness = 10.f;
// An explosive shuriken is yellow, not orange: orange is too close to the Publisher's red. It pulses as it flies.
const FLinearColor ExplosiveColor(1.0f, 0.9f, 0.05f);
constexpr float ExplosivePulse = 0.35f;
constexpr float ExplosivePulsesPerSecond = 6.f;
const FVector MemoSize(1.5, 1.1, 0.12);
// A memo is a sheet of paper flying edge first, tilted so that every camera sees its face.
constexpr float MemoRoll = 50.f;
const FLinearColor MemoColor(0.95f, 0.95f, 0.88f);

void SetShape(UStaticMeshComponent& Shape, UStaticMesh* Mesh)
{
	if (Shape.GetStaticMesh() != Mesh)
	{
		Shape.SetStaticMesh(Mesh);
	}
}

/** Gives a pooled shape the look of the projectile's kind. */
void Dress(UStaticMeshComponent& Shape, const FJamProjectile& Projectile, float Time)
{
	const float Pulse = Projectile.bExplosive ? 1.f + ExplosivePulse * FMath::Abs(FMath::Sin(PI * ExplosivePulsesPerSecond * Time)) : 1.f;
	const float Diameter = 2.f * Projectile.Radius * Pulse / JamShapes::UnitSize;
	const FLinearColor SideColor = Projectile.Owner == EJamSide::Hero ? HeroShotColor : BossShotColor;
	switch (Projectile.Kind)
	{
		case EJamProjectile::Shuriken:
			SetShape(Shape, JamShapes::Cylinder());
			Shape.SetWorldRotation(FRotator::ZeroRotator);
			Shape.SetWorldScale3D(FVector(Diameter * ShurikenWidth, Diameter * ShurikenWidth, ShurikenThickness / JamShapes::UnitSize));
			JamShapes::Glow(Shape, Projectile.bExplosive ? ExplosiveColor : SideColor, ShotGlow);
			break;
		case EJamProjectile::Memo:
			SetShape(Shape, JamShapes::Cube());
			Shape.SetWorldRotation(FRotator(0.0, FMath::RadiansToDegrees(FMath::Atan2(Projectile.Vel.Y, Projectile.Vel.X)), MemoRoll));
			Shape.SetWorldScale3D(MemoSize * Diameter);
			// Paper does not shine: a glow of 1 is its own colour, unlit, and keeps one material in the pool.
			JamShapes::Glow(Shape, MemoColor, 1.f);
			break;
		default:
			SetShape(Shape, JamShapes::Sphere());
			Shape.SetWorldRotation(FRotator::ZeroRotator);
			Shape.SetWorldScale3D(FVector(Diameter));
			JamShapes::Glow(Shape, SideColor, ShotGlow);
			break;
	}
}
} // namespace

AJamProjectilesView::AJamProjectilesView()
{
	PrimaryActorTick.bCanEverTick = false;
	SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));
	// The pool is filled at runtime: the shapes have to be found here, in a constructor.
	JamShapes::Sphere();
	JamShapes::Cylinder();
	JamShapes::Cube();
	JamShapes::Material();
	JamShapes::Neon();
}

void AJamProjectilesView::Sync(const TArray<FJamProjectile>& Projectiles, float Alpha, float Time)
{
	while (Pool.Num() < Projectiles.Num())
	{
		UStaticMeshComponent* Shape = NewObject<UStaticMeshComponent>(this);
		JamShapes::Setup(*Shape, JamShapes::Sphere());
		Shape->SetupAttachment(RootComponent);
		Shape->RegisterComponent();
		Pool.Add(Shape);
	}
	for (int32 Index = 0; Index < Pool.Num(); ++Index)
	{
		UStaticMeshComponent& Shape = *Pool[Index];
		const bool bUsed = Index < Projectiles.Num();
		Shape.SetVisibility(bUsed);
		if (!bUsed)
		{
			continue;
		}
		const FJamProjectile& Projectile = Projectiles[Index];
		const FVector2D Pos = FMath::Lerp(Projectile.PrevPos, Projectile.Pos, static_cast<double>(Alpha));
		Shape.SetWorldLocation(FVector(Pos.X, Pos.Y, FlightHeight));
		Dress(Shape, Projectile, Time);
	}
}
#include "View/JamMoneyView.h"

#include "Components/StaticMeshComponent.h"
#include "Sim/JamUltimateRules.h"
#include "View/JamShapes.h"

namespace
{
// Greybox look of a bill: presentation only, sizes in cm.
constexpr float BillLength = 34.f;
constexpr float BillWidth = 16.f;
constexpr float BillThickness = 1.f;
// Bills leave the body at chest height and lie a little above the floor, under the warning circles.
constexpr float ThrowHeight = 120.f;
constexpr float FloorHeight = 2.f;
// How far past his body a bill flies: a hit spills it close, the final blow throws it across the arena.
constexpr float SprayMin = 60.f;
constexpr float SprayMax = 170.f;
constexpr float BurstScale = 2.2f;
// The oldest bills go first beyond this many, so a long fight never fills the screen.
constexpr int32 MaxBills = 200;
constexpr int32 Seed = 4242;
const FLinearColor BillColor(0.15f, 1.0f, 0.3f);
} // namespace

AJamMoneyView::AJamMoneyView()
{
	PrimaryActorTick.bCanEverTick = false;
	SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));
	// The pool is filled at runtime: the shapes have to be found here, in a constructor.
	JamShapes::Cube();
	JamShapes::Neon();
	Random.Initialize(Seed);
}

void AJamMoneyView::Init(const FJamFeedbackSettings& InFeedback, float InGlow)
{
	Feedback = InFeedback;
	Glow = InGlow;
}

void AJamMoneyView::Throw(const FJamFighter& Boss, int32 Count, bool bBurst, float Time)
{
	for (int32 Index = 0; Index < Count; ++Index)
	{
		FBill Bill;
		const float Reach = Random.FRandRange(SprayMin, SprayMax) * (bBurst ? BurstScale : 1.f);
		const FJamSpill Spill = JamFeedbackRules::Spill(Boss.Pos, Boss.Radius, Random.FRandRange(0.f, 360.f), Reach);
		Bill.From = FVector(Spill.From.X, Spill.From.Y, ThrowHeight);
		Bill.Kick = Spill.Kick;
		Bill.Phase = Random.FRand();
		Bill.StartTime = Time;
		Alive.Add(Bill);
	}
	if (Alive.Num() > MaxBills)
	{
		Alive.RemoveAt(0, Alive.Num() - MaxBills);
	}
}

void AJamMoneyView::Sync(const FJamFight& Fight, const TArray<FJamEvent>& Events, float Time)
{
	for (const FJamEvent& Event : Events)
	{
		// The cut of the stunned Publisher that won the fight: the money he has left goes up at once.
		const bool bFinalBlow = Fight.Phase == EJamPhase::Won && Event.ProjectileId == JamUltimateRules::SlashId;
		const int32 Count = JamFeedbackRules::BillCount(Event, bFinalBlow, Feedback);
		if (Count > 0)
		{
			Throw(Fight.Fighters[EJamSide::Boss], Count, bFinalBlow, Time);
		}
	}

	const float Life = JamFeedbackRules::BillLife(Feedback);
	Alive.RemoveAll([Time, Life](const FBill& Bill) { return Time - Bill.StartTime >= Life; });
	while (Pool.Num() < Alive.Num())
	{
		UStaticMeshComponent* Card = NewObject<UStaticMeshComponent>(this);
		JamShapes::Setup(*Card, JamShapes::Cube());
		Card->SetupAttachment(RootComponent);
		Card->RegisterComponent();
		// All bills are one colour: the material is set once, when the card joins the pool.
		JamShapes::Glow(*Card, BillColor, Glow);
		Pool.Add(Card);
	}
	for (int32 Index = 0; Index < Pool.Num(); ++Index)
	{
		UStaticMeshComponent& Card = *Pool[Index];
		Card.SetVisibility(Index < Alive.Num());
		if (Index >= Alive.Num())
		{
			continue;
		}
		const FBill& Bill = Alive[Index];
		const FJamBillPose Pose =
			JamFeedbackRules::BillPose(Bill.From, Bill.Kick, FloorHeight, Bill.Phase, Time - Bill.StartTime, Feedback);
		const double Yaw = FMath::RadiansToDegrees(FMath::Atan2(Bill.Kick.Y, Bill.Kick.X));
		Card.SetWorldLocationAndRotation(Pose.Pos, FRotator(0.0, Yaw, Pose.Roll));
		Card.SetWorldScale3D(FVector(BillLength, BillWidth, BillThickness) * Pose.Scale / JamShapes::UnitSize);
	}
}

