python - < /dev/null; F=Source/JamGame/Private/View/JamProjectilesView.cpp; python -c "
import re
p='$F'; s=open(p,encoding='utf-8').read()
s=s.replace('''constexpr float ShurikenWidth = 2.2f;
constexpr float ShurikenThickness = 10.f;''','''constexpr float ShurikenWidth = 2.2f;
// SM_Shuriken (Hunyuan3D) stands in its XZ plane, 120 cm across, its centre 60 cm above its pivot: a roll lays it
// flat, and it spins about its centre as it flies.
constexpr float ShurikenModelSize = 120.f;
const FVector ShurikenModelCentre(0.0, 0.0, 60.0);
constexpr float ShurikenTurnsPerSecond = 3.f;''')
s=s.replace('''const FLinearColor MemoColor(0.95f, 0.95f, 0.88f);''','''// The memo card (r5_memo_card) is lit by itself, a little above its own colour so it reads on the dark floor.
constexpr float MemoGlow = 1.3f;''')
s=s.replace('''			SetShape(Shape, JamShapes::Cylinder());
			Shape.SetWorldRotation(FRotator::ZeroRotator);
			Shape.SetWorldScale3D(FVector(Diameter * ShurikenWidth, Diameter * ShurikenWidth, ShurikenThickness / JamShapes::UnitSize));
			JamShapes::Glow(Shape, Projectile.bExplosive ? ExplosiveColor : SideColor, ShotGlow);''','''		{
			SetShape(Shape, JamShapes::Shuriken());
			const float Scale = Diameter * ShurikenWidth * JamShapes::UnitSize / ShurikenModelSize;
			const FRotator Turn(0.0, 360.0 * ShurikenTurnsPerSecond * Time + 37.0 * Projectile.Id, 90.0);
			Shape.SetWorldRotation(Turn);
			Shape.SetWorldScale3D(FVector(Scale));
			// The pivot sits on the rim: move the model so its centre is on the flight line.
			Shape.AddWorldOffset(-Turn.RotateVector(ShurikenModelCentre * Scale));
			// The model's shape, the colour of its side: whose it is and whether it explodes must read at a glance.
			JamShapes::Glow(Shape, Projectile.bExplosive ? ExplosiveColor : SideColor, ShotGlow);
			break;
		}''')
s=s.replace('''			// Paper does not shine: a glow of 1 is its own colour, unlit, and keeps one material in the pool.
			JamShapes::Glow(Shape, MemoColor, 1.f);''','''			JamShapes::Card(Shape, JamShapes::MemoCard(), MemoGlow);''')
s=s.replace('''	JamShapes::Neon();
}''','''	JamShapes::Neon();
	JamShapes::Shuriken();
	JamShapes::MemoCard();
}''',1)
open(p,'w',encoding='utf-8',newline='\n').write(s)
"; rtk proxy grep -n "break;\|case\|Shuriken()\|MemoCard" $F

