#pragma once

#include "Animation/AnimInstance.h"
#include "CoreMinimal.h"

#include "JamPoseInstance.generated.h"

class UAnimSequence;

/** What a fighter's body shows on this frame: the view decides it, the pose instance only blends it. */
struct FJamPoseFrame
{
	/** The rest pose: for the hero the T-pose, what a character is before anybody animates it. */
	bool bRefPose = false;

	const UAnimSequence* Idle = nullptr;
	float IdleTime = 0.f;

	/** The walk or run, blended over the idle by MoveWeight. */
	const UAnimSequence* Move = nullptr;
	float MoveTime = 0.f;
	float MoveWeight = 0.f;

	/** A one-shot action over both, ActionWeight of the way. Only from the spine up while he walks, unless bFullBody. */
	const UAnimSequence* Action = nullptr;
	float ActionTime = 0.f;
	float ActionWeight = 0.f;
	bool bFullBody = false;
};

/**
 * The animation of the 3D fighters without an animation blueprint: the idle, the walk and one action blended by hand
 * in C++, on the animation thread (FJamPoseProxy). The sequences must outlive the frame: the view keeps them.
 */
UCLASS(Transient, NotBlueprintable)
class JAMGAME_API UJamPoseInstance : public UAnimInstance
{
	GENERATED_BODY()

public:
	/** The upper body is this bone and everything under it. */
	static inline const FName UpperBodyBone = TEXT("spine_01");

	FJamPoseFrame Frame;

protected:
	virtual FAnimInstanceProxy* CreateAnimInstanceProxy() override;
};

content.content:
	virtual void PreUpdate(UAnimInstance* Instance, float DeltaSeconds) override
	{
		FAnimInstanceProxy::PreUpdate(Instance, DeltaSeconds);
		Frame = CastChecked<UJamPoseInstance>(Instance)->Frame;
	}

	virtual bool Evaluate(FPoseContext& Output) override
	{
		if (Frame.bRefPose || !Frame.Idle)
		{
			Output.ResetToRefPose();
			return true;
		}
		Extract(*Frame.Idle, Frame.IdleTime, true, Output);
		if (Frame.Move && Frame.MoveWeight > 0.f)
		{
			FPoseContext Move(Output);
			Extract(*Frame.Move, Frame.MoveTime, true, Move);
			FAnimationPoseData Base(Output);
			FAnimationRuntime::BlendTwoPosesTogetherInPlace(Base, FAnimationPoseData(Move), 1.f - Frame.MoveWeight);
		}
		if (Frame.Action && Frame.ActionWeight > 0.f)
		{
			FPoseContext Action(Output);
			Extract(*Frame.Action, Frame.ActionTime, false, Action);
			BlendAction(Output, Action);
		}
		return true;
	}

	/** The action over the upper body, and over the legs as far as they are not walking. */
	void BlendAction(FPoseContext& Output, const FPoseContext& Action) const
	{
		const FBoneContainer& Bones = Output.Pose.GetBoneContainer();
		const FReferenceSkeleton& RefSkeleton = Bones.GetReferenceSkeleton();
		const float Legs = Frame.bFullBody ? 1.f : 1.f - Frame.MoveWeight;
		TArray<bool, TInlineAllocator<64>> Upper;
		Upper.SetNumZeroed(Output.Pose.GetNumBones());
		// Parents come before their children in a compact pose.
		for (const FCompactPoseBoneIndex Bone : Output.Pose.ForEachBoneIndex())
		{
			const FCompactPoseBoneIndex Parent = Output.Pose.GetParentBoneIndex(Bone);
			const FName Name = RefSkeleton.GetBoneName(Bones.MakeMeshPoseIndex(Bone).GetInt());
			Upper[Bone.GetInt()] = Name == UJamPoseInstance::UpperBodyBone || (Parent.IsValid() && Upper[Parent.GetInt()]);
			Output.Pose[Bone].BlendWith(Action.Pose[Bone], Frame.ActionWeight * (Upper[Bone.GetInt()] ? 1.f : Legs));
		}
	}
};
} // namespace

FAnimInstanceProxy* UJamPoseInstance::CreateAnimInstanceProxy()

