#include "Misc/AutomationTest.h"

#if WITH_DEV_AUTOMATION_TESTS

#include "Game/JamIntroRules.h"
#include "Tests/JamTestHelpers.h"

/**
 * T-030: the intro before the first fight. A bug here looks in game like "the intro never ends", "the click that
 * started the game skipped it at once" or "the camera jumps to the hero".
 *
 * Run: Automation RunTests Jam.Intro
 */
namespace
{
constexpr float Length = 7.3f;
constexpr float SkipAfter = 0.5f;
constexpr float Fade = 0.5f;
constexpr float Return = 0.8f;
} // namespace

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamIntroEndTest, "Jam.Intro.EndsAfterItsShowOrOnASkip", JamTest::Flags)

bool FJamIntroEndTest::RunTest(const FString& Parameters)
{
	TestFalse(TEXT("it runs at the start"), JamIntroRules::IsOver(0.f, Length, false, SkipAfter));
	TestFalse(TEXT("and through the show"), JamIntroRules::IsOver(Length - 0.01f, Length, false, SkipAfter));
	TestTrue(TEXT("it ends with the show"), JamIntroRules::IsOver(Length, Length, false, SkipAfter));
	TestFalse(TEXT("a click at once does not skip it"), JamIntroRules::IsOver(0.1f, Length, true, SkipAfter));
	TestTrue(TEXT("a click later does"), JamIntroRules::IsOver(SkipAfter, Length, true, SkipAfter));
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamIntroTitleTest, "Jam.Intro.TheTitleFadesInAndOut", JamTest::Flags)

bool FJamIntroTitleTest::RunTest(const FString& Parameters)
{
	TestEqual(TEXT("hidden at the start"), JamIntroRules::TitleAlpha(0.f, Length, Fade), 0.f);
	TestEqual(TEXT("half way in"), JamIntroRules::TitleAlpha(Fade / 2.f, Length, Fade), 0.5f, 1e-4f);
	TestEqual(TEXT("whole in the middle"), JamIntroRules::TitleAlpha(Length / 2.f, Length, Fade), 1.f);
	TestEqual(TEXT("half way out"), JamIntroRules::TitleAlpha(Length - Fade / 2.f, Length, Fade), 0.5f, 1e-4f);
