	struct FGalleryPose
	{
		EJamClip Clip;
		float ClipTime;
	};
	// Every pose the katana and the hands have to look right in: idle, run, both strikes, the guard, the throw, a hit.
	static const FGalleryPose Poses[] = {
		{ EJamClip::Idle, 0.5f }, { EJamClip::Idle, 2.5f }, { EJamClip::Move, 0.1f }, { EJamClip::Move, 0.4f },
		{ EJamClip::StrikeA, 0.35f }, { EJamClip::StrikeA, 0.5f }, { EJamClip::StrikeB, 0.73f }, { EJamClip::Parry, 0.3f },
		{ EJamClip::Throw, 0.4f }, { EJamClip::Throw, 0.57f }, { EJamClip::Hit, 0.33f }, { EJamClip::Death, 2.9f },
	};
	constexpr float PoseSeconds = 0.5f;
	const int32 Index = FMath::Min(FMath::FloorToInt32(Time / PoseSeconds), UE_ARRAY_COUNT(Poses) - 1);
	if (Index != GalleryPose)
	{
		GalleryPose = Index;
		HeroView->HoldPose(Poses[Index].Clip, Poses[Index].ClipTime, Time);
	}
	SyncViews(Host, Time);
	// The camera stands at the hero's right front, then at his left front for the second half of each pose.
