151	
152		Body = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Body"));
153		Body->SetupAttachment(RootComponent);
154		JamShapes::Setup(*Body, JamShapes::Sphere());
155		Visor = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Visor"));
156		Visor->SetupAttachment(RootComponent);
157		JamShapes::Setup(*Visor, JamShapes::Cube());
158	
159		Figure = CreateDefaultSubobject<USkeletalMeshComponent>(TEXT("Figure"));
160		Figure->SetupAttachment(RootComponent);
161		Figure->SetRelativeRotation(ModelYaw);
162		Figure->SetCollisionEnabled(ECollisionEnabled::NoCollision);
163		Figure->SetGenerateOverlapEvents(false);
164		Figure->VisibilityBasedAnimTickOption = EVisibilityBasedAnimTickOption::AlwaysTickPoseAndRefreshBones;
165	
166		Katana = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Katana"));
167		Katana->SetupAttachment(Figure, HandSocket);
168		Katana->SetCollisionEnabled(ECollisionEnabled::NoCollision);
169		Katana->SetGenerateOverlapEvents(false);
170		Katana->SetRelativeTransform(KatanaInHand);
171	
172		for (int32 Index = 0; Index < GhostCount; ++Index)
173		{
174			UPoseableMeshComponent* Ghost = CreateDefaultSubobject<UPoseableMeshComponent>(FName(TEXT("Ghost"), Index));
175			Ghost->SetupAttachment(RootComponent);
176			// A ghost stays where it was left while the hero moves on.
177			Ghost->SetUsingAbsoluteLocation(true);
178			Ghost->SetUsingAbsoluteRotation(true);
179			Ghost->SetUsingAbsoluteScale(true);
180			Ghost->SetCollisionEnabled(ECollisionEnabled::NoCollision);
181			Ghost->SetCastShadow(false);
182			Ghost->SetVisibility(false);
183			Ghosts.Add(Ghost);
184		}
