194	void AJamFighterView::Init(EJamSide InSide, float Radius, float MaxSpeed, const FLinearColor& Color)
195	{
196		Side = InSide;
197		const float Height = Radius * HeightInRadii;
198		BaseColor = Color;
199		Speed = FMath::Max(1.f, MaxSpeed);
200		const float R = Radius / JamShapes::UnitSize;
201		Body->SetRelativeScale3D(FVector(2.f * Radius, 2.f * Radius, Height) / JamShapes::UnitSize);
202		Body->SetRelativeLocation(FVector(0.0, 0.0, 0.5 * Height));
203		Visor->SetRelativeScale3D(VisorSizeInRadii * R);
204		Visor->SetRelativeLocation(FVector(Radius * VisorForwardInRadii, 0.0, Height * VisorHeightAt));
205	
206		const FFigureInfo& Info = FigureOf(Side);
207		Figure->SetSkeletalMesh(LoadObject<USkeletalMesh>(nullptr, Info.Mesh));
208		Figure->SetAnimInstanceClass(UJamPoseInstance::StaticClass());
209		Clips.SetNum(UE_ARRAY_COUNT(Info.Clips));
210		for (int32 Index = 0; Index < Clips.Num(); ++Index)
