#include "CoreMinimal.h"

/**
 * The crack between two looks of the game (T-068): when a cut changes the layers, the old picture is held as a frozen
 * frame and a jagged vertical crack opens from the middle of the screen to both edges, showing the new look through
 * it. The fight holds while it opens.
 * Tests: Jam.Crack.*
 */
namespace JamCrackRules
{
/** How far the crack has opened Age seconds in: half its width as a share of the screen, 0 to 0.5, fast then settling. */
JAMGAME_API float HalfOpen(float Age, float Duration);

/** Whether the crack has opened all the way and the new look is whole. */
JAMGAME_API bool IsOver(float Age, float Duration);

/**
 * How far the crack's edge strays sideways at a height, a share of the screen width within -Jag..Jag: the same for the
 * same strip and seed (a crack keeps its shape while it opens), different between strips.
 */
JAMGAME_API float EdgeJag(int32 Strip, int32 Seed, float Jag);
} // namespace JamCrackRules

