#include "UI/JamCrackRules.h"

float JamCrackRules::HalfOpen(float Age, float Duration)
{
	const float T = FMath::Clamp(Age / FMath::Max(Duration, UE_SMALL_NUMBER), 0.f, 1.f);
	// An ease-out: the crack bursts open and settles at the edges.
	return 0.5f * (1.f - FMath::Pow(1.f - T, 3.f));
}

bool JamCrackRules::IsOver(float Age, float Duration)
{
	return Age >= Duration;
}

float JamCrackRules::EdgeJag(int32 Strip, int32 Seed, float Jag)
{
	// A hash, not a random stream: the edge keeps its shape every frame and needs no state.
	const uint32 Hash = HashCombineFast(GetTypeHash(Strip), GetTypeHash(Seed * 7919 + 13));
	const float Unit = static_cast<float>(Hash % 10007u) / 10006.f;
	return (2.f * Unit - 1.f) * Jag;
}

