void AJamHUD::DrawCrack()
{
	if (CrackAge < 0.f || !CrackFrame)
	{
		return;
	}
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	const float Half = JamCrackRules::HalfOpen(CrackAge, JamCrackRules::Seconds) * W;
	const float StripH = H / CrackStrips;
	TArray<FVector2D> LeftEdge;
	TArray<FVector2D> RightEdge;
	for (int32 Strip = 0; Strip < CrackStrips; ++Strip)
	{
		const float Y = Strip * StripH;
		// The two edges are cut apart from one crack: the right one is the left one's shape, mirrored a little off.
		const float Left = FMath::Clamp(0.5f * W - Half + JamCrackRules::EdgeJag(Strip, CrackSeed, CrackJag) * W, 0.f, W);
		const float Right = FMath::Clamp(0.5f * W + Half + JamCrackRules::EdgeJag(Strip, CrackSeed + 31, CrackJag) * W, 0.f, W);
		// The old picture's two halves slide apart with the crack, torn at its edges: the left half moves left by
		// Half, so screen x shows the picture at x + Half; the right half the other way.
		if (Left > 0.f)
		{
			DrawTexture(CrackFrame, 0.f, Y, Left, StripH, Half / W, Y / H, Left / W, StripH / H);
		}
		if (Right < W)
		{
			DrawTexture(CrackFrame, Right, Y, W - Right, StripH, (Right - Half) / W, Y / H, (W - Right) / W, StripH / H);
		}
		LeftEdge.Add(FVector2D(Left, Y + 0.5f * StripH));
		RightEdge.Add(FVector2D(Right, Y + 0.5f * StripH));
	}
	// A white flash fills the gap as it bursts open.
	const float Burst = 1.f - FMath::Clamp(CrackAge / CrackFlashSeconds, 0.f, 1.f);
	if (Burst > 0.f)
	{
		DrawRect(FLinearColor(1.f, 1.f, 1.f, 0.85f * Burst), 0.5f * W - Half, 0.f, 2.f * Half, H);
	}
	// The edges glow: a wide neon line with a white core, fading as the crack reaches the screen's edges.
	const float Glow = 1.f - FMath::Clamp(Half / (0.5f * W), 0.f, 1.f) * 0.6f;
	for (const TArray<FVector2D>* Edge : { &LeftEdge, &RightEdge })
	{
		const FLinearColor Neon = Edge == &LeftEdge ? CrackCyan : CrackMagenta;
		for (int32 Index = 1; Index < Edge->Num(); ++Index)
		{
			const FVector2D A = (*Edge)[Index - 1];
			const FVector2D B = (*Edge)[Index];
			DrawLine(A.X, A.Y, B.X, B.Y, Neon * FLinearColor(1.f, 1.f, 1.f, 0.35f * Glow), 22.f);
			DrawLine(A.X, A.Y, B.X, B.Y, Neon * FLinearColor(1.f, 1.f, 1.f, 0.8f * Glow), 10.f);
			DrawLine(A.X, A.Y, B.X, B.Y, FLinearColor(1.f, 1.f, 1.f, Glow), 3.f);
		}
	}
}

