IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamCrackOpenTest, "Jam.Crack.OpensFromTheMiddleToTheEdges", JamTest::Flags)

bool FJamCrackOpenTest::RunTest(const FString& Parameters)
{
	TestEqual(TEXT("shut at the start"), JamCrackRules::HalfOpen(0.f, CrackSeconds), 0.f);
	const float Early = JamCrackRules::HalfOpen(0.1f * CrackSeconds, CrackSeconds);
	const float Mid = JamCrackRules::HalfOpen(0.5f * CrackSeconds, CrackSeconds);
	TestTrue(TEXT("opening"), Early > 0.f && Mid > Early);
	TestTrue(TEXT("fast at first: past a quarter of the screen by half time"), Mid > 0.25f);
	TestEqual(TEXT("at the edges at the end"), JamCrackRules::HalfOpen(CrackSeconds, CrackSeconds), 0.5f, 1e-4f);
	TestEqual(TEXT("and stays open"), JamCrackRules::HalfOpen(2.f * CrackSeconds, CrackSeconds), 0.5f, 1e-4f);
	TestFalse(TEXT("not over while opening"), JamCrackRules::IsOver(0.5f * CrackSeconds, CrackSeconds));
	TestTrue(TEXT("over when open"), JamCrackRules::IsOver(CrackSeconds, CrackSeconds));
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamCrackJagTest, "Jam.Crack.TheEdgeIsJaggedAndKeepsItsShape", JamTest::Flags)

bool FJamCrackJagTest::RunTest(const FString& Parameters)
{
	constexpr float Jag = 0.02f;
	bool bInside = true;
	bool bVaries = false;
	for (int32 Strip = 0; Strip < 40; ++Strip)
	{
		const float Here = JamCrackRules::EdgeJag(Strip, 7, Jag);
		bInside &= FMath::Abs(Here) <= Jag;
		bVaries |= !FMath::IsNearlyEqual(Here, JamCrackRules::EdgeJag(Strip + 1, 7, Jag));
	}
	TestTrue(TEXT("never strays further than the jag"), bInside);
	TestTrue(TEXT("strips differ"), bVaries);
	TestEqual(TEXT("the same strip keeps its place"), JamCrackRules::EdgeJag(5, 7, Jag), JamCrackRules::EdgeJag(5, 7, Jag));
	TestNotEqual(TEXT("another crack has another shape"), JamCrackRules::EdgeJag(5, 7, Jag), JamCrackRules::EdgeJag(5, 8, Jag));
	return true;
}

