#include "UI/JamCrackRules.h"

namespace
{
// The fault bends at this many knots, unevenly spaced down the screen, swinging to alternate sides of the middle.
constexpr int32 FaultKnots = 7;
constexpr float KnotSpacingJitter = 0.6f;
constexpr float KnotLeastSwing = 0.06f;
constexpr float KnotExtraSwing = 0.11f;
// Between the knots it zigzags finely: this many steps down the screen, this far each way.
constexpr int32 JagSteps = 40;
constexpr float JagSize = 0.012f;

/** A hash in 0..1, not a random stream: the fault keeps its shape every frame and needs no state. */
float CrackHash(int32 Index, int32 Seed)
{
	const uint32 Hash = HashCombineFast(GetTypeHash(Index), GetTypeHash(Seed * 7919 + 13));
	return static_cast<float>(Hash % 10007u) / 10006.f;
}

float KnotV(int32 Knot, int32 Seed)
{
	const int32 Last = FaultKnots - 1;
	if (Knot <= 0 || Knot >= Last)
	{
		return Knot <= 0 ? 0.f : 1.f;
	}
	return (Knot + (CrackHash(Knot + 50, Seed) - 0.5f) * KnotSpacingJitter) / Last;
}

float KnotX(int32 Knot, int32 Seed)
{
	// Alternate sides, so the path can never come out straight; which side first, and how far, is the seed's.
	const float First = CrackHash(0, Seed) < 0.5f ? -1.f : 1.f;
	const float Side = Knot % 2 == 0 ? First : -First;
	return 0.5f + Side * (KnotLeastSwing + KnotExtraSwing * CrackHash(Knot + 1, Seed));
}
} // namespace

float JamCrackRules::Reach(float Age)
{
	// An ease-out: the crack shoots off and slows as it reaches the bottom.
	const float T = FMath::Clamp(Age / RunSeconds, 0.f, 1.f);
	return T * (2.f - T);
}

float JamCrackRules::Shift(float Age)
{
	// Smoothstep: the halves come loose slowly, then slide away and off.
	const float T = FMath::Clamp((Age - RunSeconds - HoldSeconds) / PartSeconds, 0.f, 1.f);
	return (1.f - FaultMargin) * T * T * (3.f - 2.f * T);
}

bool JamCrackRules::IsOver(float Age, float Duration)
{
	return Age >= Duration;
}

float JamCrackRules::FaultX(float V, int32 Seed)
{
	const float Down = FMath::Clamp(V, 0.f, 1.f);
	int32 Knot = 1;
	while (Knot < FaultKnots - 1 && KnotV(Knot, Seed) < Down)
	{
		++Knot;
	}
	const float From = KnotV(Knot - 1, Seed);
	const float To = KnotV(Knot, Seed);
	const float Along = To > From ? (Down - From) / (To - From) : 0.f;
	const float Bend = FMath::Lerp(KnotX(Knot - 1, Seed), KnotX(Knot, Seed), Along);
	const int32 Step = FMath::Min(FMath::FloorToInt32(Down * JagSteps), JagSteps - 1);
	const float Jag = (2.f * CrackHash(Step + 1000, Seed) - 1.f) * JagSize;
	return FMath::Clamp(Bend + Jag, FaultMargin, 1.f - FaultMargin);
}

