}

float JamCrackRules::FaultX(float V, int32 Seed)
{
	const float Down = FMath::Clamp(V, 0.f, 1.f);
	int32 Knot = 1;
	while (Knot < FaultKnots - 1 && KnotV(Knot, Seed) < Down)
	{
		++Knot;
	}
	const float From = KnotV(Knot - 1, Seed);
	const float To = KnotV(Knot, Seed);
	const float Along = To > From ? (Down - From) / (To - From) : 0.f;
	const float Bend = FMath::Lerp(KnotX(Knot - 1, Seed), KnotX(Knot, Seed), Along);
	const int32 Step = FMath::Min(FMath::FloorToInt32(Down * JagSteps), JagSteps - 1);
	const float Jag = (2.f * CrackHash(Step + 1000, Seed) - 1.f) * JagSize;
	return FMath::Clamp(Bend + Jag, FaultMargin, 1.f - FaultMargin);
}

