			// Cut short with a quick fade, not a click.
			TWeakObjectPtr<UAudioComponent> Weak(Voice);
			FTimerHandle Cut;
			GetWorldTimerManager().SetTimer(
				Cut,
				[Weak]()
				{
					if (Weak.IsValid())
					{
						Weak->FadeOut(0.1f, 0.f);
