4	{
5	// The fault is cut by midpoint displacement: the line between its two ends is split in two again and again, each
6	// new point pushed sideways by less than the last, so it bends at every scale like a real crack.
7	constexpr int32 FaultLevels = 6;
8	constexpr int32 FaultPoints = 1 << FaultLevels;
9	// The first split always bends this far at least (a crack is never straight), up to the extra on top.
10	constexpr float FirstBendLeast = 0.07f;
11	constexpr float FirstBendExtra = 0.06f;
12	// The next split's push, and how much each further split keeps of it.
13	constexpr float NextBend = 0.17f;
14	constexpr float Roughness = 0.6f;
15	
16	/** A hash in 0..1, not a random stream: the fault keeps its shape every frame and needs no state. */
17	float CrackHash(int32 Index, int32 Seed)
18	{
19		const uint32 Hash = HashCombineFast(GetTypeHash(Index), GetTypeHash(Seed * 7919 + 13));
20		return static_cast<float>(Hash % 10007u) / 10006.f;
21	}
22	
23	void CutFault(int32 Seed, float (&Points)[FaultPoints + 1])
24	{
25		Points[0] = 0.4f + 0.2f * CrackHash(0, Seed);
26		Points[FaultPoints] = 0.4f + 0.2f * CrackHash(1, Seed);
27		float Bend = NextBend;
28		for (int32 Step = FaultPoints; Step > 1; Step /= 2)
29		{
30			for (int32 Index = Step / 2; Index < FaultPoints; Index += Step)
31			{
32				const float Hash = CrackHash(Index + Step * 100, Seed);
33				const float Side = Hash < 0.5f ? -1.f : 1.f;
34				const float Push =
35					Step == FaultPoints ? Side * (FirstBendLeast + FirstBendExtra * CrackHash(2, Seed)) : (2.f * Hash - 1.f) * 0.5f * Bend;
36				Points[Index] = 0.5f * (Points[Index - Step / 2] + Points[Index + Step / 2]) + Push;
37			}
38			if (Step < FaultPoints)
39			{
40				Bend *= Roughness;
41			}
42		}
43	}
