"""Headless Blender: the Publisher's head facing through Kung_Fu_Punch. The face axis is the head bone's axis that,
in the Idle's first frame, lies most level and nearest the model's forward (-Y after the FBX round trip). Degrees
counter-clockwise seen from above, off the Idle's."""
import math
import sys

import bpy
from mathutils import Vector

ROOT = "F:/Unreal_Engine/UnrealProjects/MegaJam2026/Art/Models/boss_fixed/"
OUT = sys.argv[sys.argv.index("--") + 1]
lines = []


def load(name):
    for ob in list(bpy.data.objects):
        bpy.data.objects.remove(ob)
    for a in list(bpy.data.actions):
        bpy.data.actions.remove(a)
    bpy.ops.import_scene.fbx(filepath=ROOT + name + ".fbx")
    return next(o for o in bpy.data.objects if o.type == "ARMATURE")


def axes(arm, bone):
    m = (arm.matrix_world @ arm.pose.bones[bone].matrix).to_3x3()
    return {"+X": m.col[0], "-X": -m.col[0], "+Z": m.col[2], "-Z": -m.col[2], "+Y": m.col[1], "-Y": -m.col[1]}


def yaw(v):
    return math.degrees(math.atan2(v.y, v.x))


arm = load("Idle")
bpy.context.scene.frame_set(int(arm.animation_data.action.frame_range[0]))
idle = {}
for bone in ("head", "neck_01", "spine_03", "pelvis"):
    ax = axes(arm, bone)
    best = max(ax, key=lambda k: Vector((ax[k].x, ax[k].y, 0)).length * -ax[k].y)
    idle[bone] = (best, yaw(ax[best]))
    lines.append("Idle %-8s face axis %s yaw %.1f (level %.2f)" % (bone, best, yaw(ax[best]), Vector((ax[best].x, ax[best].y, 0)).length))
arm = load("Kung_Fu_Punch")
first, last = (int(round(f)) for f in arm.animation_data.action.frame_range)
for frame in list(range(first, last + 1, 20)) + [last]:
    bpy.context.scene.frame_set(frame)
    row = []
    for bone, (axis, y0) in idle.items():
        row.append("%s %+6.1f" % (bone, (yaw(axes(arm, bone)[axis]) - y0 + 540) % 360 - 180))
    lines.append("%4d  " % frame + "  ".join(row))
with open(OUT, "w", encoding="utf-8") as h:
    h.write("\n".join(lines) + "\n")

