		const float Length = Runs[Run] ? Runs[Run]->GetPlayLength() : 0.f;
		if (Length > 0.f)
		{
			CyclesPerSecond += StrideWeights[Run] * JamPoseRules::StrideRate(GroundSpeed, RunSpeeds[Run], MaxRunRate) / Length;
