		Side == EJamSide::Hero ? TEXT("Hero") : TEXT("Publisher"), LastTime, MoveAngle, Out.Twist, StrideWeights[0], StrideWeights[1],
		StrideWeights[2], StrideWeights[3], StrideWeights[4], StrideWeights[5]);
