#pragma once

#include "CoreMinimal.h"
#include "GameFramework/Actor.h"
#include "View/JamNeonRules.h"

#include "JamLightView.generated.h"

class UDirectionalLightComponent;
class UPointLightComponent;

/**
 * The neon light of the full-art tier (T-077): cyan and magenta lights round the edge of the arena that throw their
 * colour onto the floor, the bodies and the effects. The lower tiers turn them off (JamNeonRules::LightFor); the
 * camera's post process carries the rest of the tier's look (AJamCameraRig::SetLight).
 */
UCLASS()
class JAMGAME_API AJamLightView : public AActor
{
	GENERATED_BODY()

public:
	AJamLightView();

	/**
	 * Places the lights round an arena of this radius, in step with its posts, and takes the sun of Stage (the actor
	 * that lights the arena) to dim it at night. Called once.
	 */
	void Init(float ArenaRadius, const AActor& Stage);

	/** The lights shine and the sun dims with the full art only. Cheap when nothing changes. */
	void SetLight(EJamLight InLight);

	/** Keeps the key light on the Publisher standing at BossAt (T-082). */
	void Follow(const FVector& BossAt);

private:
	UPROPERTY()
	TArray<TObjectPtr<UPointLightComponent>> Lamps;

	/** The stage's sun, not owned here: dimmed to a moon while the full art is on. */
	UPROPERTY()
	TObjectPtr<UDirectionalLightComponent> Sun;

	UPROPERTY()
	TObjectPtr<class USpotLightComponent> Key;

	float DaySun = 0.f;
	EJamLight Light = EJamLight::Neon;

	void DimSun();
};
#include "View/JamLightView.h"

#include "Components/DirectionalLightComponent.h"
#include "Components/PointLightComponent.h"
#include "Components/SpotLightComponent.h"

namespace
{
// Presentation only. One light per post of the arena, in the post's colour, a little inside the edge so it lights the
// floor of the fight and not the dark outside it.
constexpr int32 LampCount = 16;
constexpr float LampCandela = 55.f;
constexpr float LampReach = 1100.f;
constexpr float LampHeight = 300.f;
constexpr float LampInset = 90.f;
// A wide source: the neon spills over the floor as a pool, not a hard dot.
constexpr float LampSize = 40.f;
const FLinearColor LampCyan(0.0f, 0.8f, 1.0f);
const FLinearColor LampMagenta(1.0f, 0.1f, 0.6f);
// The full art is a night: the stage's sun keeps this share of its light, the neon does the rest.
constexpr float NightShare = 0.25f;
// T-082: a key light above and in front of the Publisher follows him, so his show-off reads in the dark.
constexpr float KeyCandela = 1100.f;
constexpr float KeyHeight = 700.f;
constexpr float KeyAhead = 350.f;
constexpr float KeyAimHeight = 120.f;
constexpr float KeyInnerCone = 8.f;
constexpr float KeyOuterCone = 18.f;
const FLinearColor KeyWarm(1.0f, 0.9f, 0.85f);
} // namespace

AJamLightView::AJamLightView()
{
	PrimaryActorTick.bCanEverTick = false;
	SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));
}

void AJamLightView::Init(float ArenaRadius, const AActor& Stage)
{
	Sun = Stage.FindComponentByClass<UDirectionalLightComponent>();
	if (Sun)
	{
		DaySun = Sun->Intensity;
		DimSun();
	}
	Key = NewObject<USpotLightComponent>(this);
	Key->SetupAttachment(RootComponent);
	Key->SetMobility(EComponentMobility::Movable);
	Key->SetCastShadows(false);
	Key->SetIntensityUnits(ELightUnits::Candelas);
	Key->SetIntensity(KeyCandela);
	Key->SetAttenuationRadius(2.f * KeyHeight);
	Key->SetInnerConeAngle(KeyInnerCone);
	Key->SetOuterConeAngle(KeyOuterCone);
	Key->SetLightColor(KeyWarm);
	Key->SetVisibility(Light == EJamLight::Neon);
	Key->RegisterComponent();
	const float Inner = ArenaRadius - LampInset;
	for (int32 Index = 0; Index < LampCount; ++Index)
	{
		const float Angle = UE_TWO_PI * Index / LampCount;
		UPointLightComponent* Lamp = NewObject<UPointLightComponent>(this);
		Lamp->SetupAttachment(RootComponent);
		Lamp->SetMobility(EComponentMobility::Movable);
		// Sixteen shadowed lights would cost more than the whole fight; the neon only has to colour the scene.
		Lamp->SetCastShadows(false);
		Lamp->SetIntensityUnits(ELightUnits::Candelas);
		Lamp->SetIntensity(LampCandela);
		Lamp->SetAttenuationRadius(LampReach);
		Lamp->SetSourceRadius(LampSize);
		Lamp->SetLightColor(Index % 2 == 0 ? LampCyan : LampMagenta);
		Lamp->SetVisibility(Light == EJamLight::Neon);
		Lamp->RegisterComponent();
		Lamp->SetRelativeLocation(FVector(Inner * FMath::Cos(Angle), Inner * FMath::Sin(Angle), LampHeight));
		Lamps.Add(Lamp);
	}
}

void AJamLightView::SetLight(EJamLight InLight)
{
	if (InLight == Light)
	{
		return;
	}
	Light = InLight;
	for (UPointLightComponent* Lamp : Lamps)
	{
		Lamp->SetVisibility(Light == EJamLight::Neon);
	}
	if (Key)
	{
		Key->SetVisibility(Light == EJamLight::Neon);
	}
	DimSun();
}

void AJamLightView::Follow(const FVector& BossAt)
{
	if (!Key)
	{
		return;
	}
	// From above and from the camera's side of him (the camera looks down from -X), aimed at his chest.
	const FVector From = BossAt + FVector(-KeyAhead, 0.0, KeyHeight);
	const FVector At = BossAt + FVector(0.0, 0.0, KeyAimHeight);
	Key->SetWorldLocationAndRotation(From, (At - From).Rotation());
}

void AJamLightView::DimSun()
{
	if (Sun)
	{
		Sun->SetIntensity(Light == EJamLight::Neon ? DaySun * NightShare : DaySun);
	}
}

