float JamIntroRules::TitleAlpha(float Age, float Length, float Fade)
{
	if (Fade <= 0.f)
	{
		return Age >= 0.f && Age < Length ? 1.f : 0.f;
	}
	return FMath::Clamp(FMath::Min(Age, Length - Age) / Fade, 0.f, 1.f);
}

