namespace
{
/** The lines one event starts, added to Lines. */
void AddLinesOf(const FJamEvent& Event, const FJamFight& Fight, TArray<EJamLine>& Lines)
{
	if (Event.Type == EJamEvent::StealOpened)
	{
		// The card of cut N opens with N - 1 cuts done: the count goes up when it is settled.
		const int32 Cut = FMath::Clamp(Fight.Steal.Done, 0, JamStealRules::ThresholdCount - 1);
		const int32 First = static_cast<int32>(EJamLine::Cut1Boss) + 2 * Cut;
		Lines.Add(static_cast<EJamLine>(First));
		Lines.Add(static_cast<EJamLine>(First + 1));
	}
	else if (Event.Type == EJamEvent::Stunned)
	{
		Lines.Add(EJamLine::StunBoss);
	}
	else if (Event.Type == EJamEvent::UltimateSlash && Fight.Phase == EJamPhase::Won)
	{
		Lines.Add(EJamLine::FinalHero);
		Lines.Add(EJamLine::FinalBoss);
	}
}
} // namespace

TArray<EJamLine> JamVoiceRules::LinesOf(const TArray<FJamEvent>& Events, const FJamFight& Fight)
{
	TArray<EJamLine> Lines;
	for (const FJamEvent& Event : Events)
	{
		AddLinesOf(Event, Fight, Lines);
	}
	return Lines;
}

bool JamVoiceRules::CutsIn(EJamLine Line)
{
	return Line == EJamLine::FinalHero;
}

float JamVoiceRules::NextBarkDelay(FRandomStream& Stream)
{
	return Stream.FRandRange(BarkMinSeconds, BarkMaxSeconds);
}

EJamLine JamVoiceRules::PickBark(FRandomStream& Stream, EJamLine Last)
{
	const int32 First = static_cast<int32>(EJamLine::Bark1);
	// One of the other three: a step of 1 to 3 round the four.
	const int32 From = IsBark(Last) ? static_cast<int32>(Last) - First : 0;
	const int32 Step = IsBark(Last) ? Stream.RandRange(1, BarkCount - 1) : Stream.RandRange(0, BarkCount - 1);
	return static_cast<EJamLine>(First + (From + Step) % BarkCount);
}

bool JamVoiceRules::MayBark(const FJamFight& Fight, bool bSpeaking)
{
	return Fight.Phase == EJamPhase::Fight && !bSpeaking;
}
#pragma once

#include "Audio/JamVoiceRules.h"
#include "CoreMinimal.h"
#include "GameFramework/Actor.h"

#include "JamVoice.generated.h"

class UAudioComponent;
class USoundWave;

/**
 * The voice-over: says the lines JamVoiceRules picks one after another, never two at once, and the Publisher's barks
 * now and then in the fight. Runs on real time, so a slowed world does not stretch a line. A line outlives the steal
 * card it started on.
 *
 * The sounds are /Game/Audio/Voice/<line name>; a missing one is skipped silently with its subtitle.
 */
UCLASS()
class JAMGAME_API AJamVoice : public AActor
{
	GENERATED_BODY()

public:
	AJamVoice();

	virtual void Tick(float DeltaSeconds) override;

	/** Queues Line, or says it at once over everything when it cuts in (JamVoiceRules::CutsIn) or bNow. */
	void Say(EJamLine Line, bool bNow = false);

	/** The lines of a frame's events, and the barks of the fight; Fight is the state after the events. */
	void Hear(const TArray<FJamEvent>& Events, const FJamFight& Fight);

	/** Stops the line being said and drops the queue. */
	void Hush();

	/** The line being said now, false when nobody talks. */
	bool Current(EJamLine& OutLine) const;

	/** Whether a line is playing now: the sound effects duck under it. */
	bool IsSpeaking() const { return bSpeaking; }

private:
	void StartNext(float Now);

	UPROPERTY()
	TArray<TObjectPtr<USoundWave>> Sounds;

	UPROPERTY()
	TObjectPtr<UAudioComponent> Playing;

	TArray<EJamLine> Queue;
	bool bSpeaking = false;
	EJamLine Line = EJamLine::IntroBoss;
	/** Real time the line being said ends, and the next bark is due (negative: not yet set). */
	float LineEnd = 0.f;
	float NextBark = -1.f;
	EJamLine LastBark = EJamLine::Bark4;
	FRandomStream Stream;
};
#include "Audio/JamVoice.h"

#include "Components/AudioComponent.h"
#include "Kismet/GameplayStatics.h"
#include "Sound/SoundWave.h"
#include "UObject/ConstructorHelpers.h"

AJamVoice::AJamVoice()
{
	PrimaryActorTick.bCanEverTick = true;
	SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));
	for (int32 Index = 0; Index < JamVoiceRules::LineCount; ++Index)
	{
		const TCHAR* Name = JamVoiceRules::NameOf(static_cast<EJamLine>(Index));
		ConstructorHelpers::FObjectFinder<USoundWave> Finder(*FString::Printf(TEXT("/Game/Audio/Voice/%s.%s"), Name, Name));
		Sounds.Add(Finder.Object);
	}
	Stream.Initialize(FPlatformTime::Cycles());
}

void AJamVoice::Say(EJamLine NewLine, bool bNow)
{
	if (bNow || JamVoiceRules::CutsIn(NewLine))
	{
		Hush();
	}
	Queue.Add(NewLine);
	if (!bSpeaking)
	{
		StartNext(GetWorld()->GetRealTimeSeconds());
	}
}

void AJamVoice::Hush()
{
	Queue.Reset();
	bSpeaking = false;
	if (Playing)
	{
		Playing->Stop();
		Playing = nullptr;
	}
}

bool AJamVoice::Current(EJamLine& OutLine) const
{
	OutLine = Line;
	return bSpeaking;
}

void AJamVoice::StartNext(float Now)
{
	bSpeaking = false;
	while (!Queue.IsEmpty() && !bSpeaking)
	{
		Line = Queue[0];
		Queue.RemoveAt(0);
		USoundWave* Sound = Sounds[static_cast<int32>(Line)];
		if (!Sound)
		{
			continue;
		}
		Playing = UGameplayStatics::SpawnSound2D(this, Sound);
		LineEnd = Now + Sound->GetDuration();
		bSpeaking = true;
	}
	if (!bSpeaking)
	{
		Playing = nullptr;
		NextBark = Now + JamVoiceRules::NextBarkDelay(Stream);
	}
}

void AJamVoice::Tick(float DeltaSeconds)
{
	Super::Tick(DeltaSeconds);
	const float Now = GetWorld()->GetRealTimeSeconds();
	if (bSpeaking && Now >= LineEnd)
	{
		StartNext(Now);
	}
}

void AJamVoice::Hear(const TArray<FJamEvent>& Events, const FJamFight& Fight)
{
	for (const EJamLine NewLine : JamVoiceRules::LinesOf(Events, Fight))
	{
		Say(NewLine);
	}
	const float Now = GetWorld()->GetRealTimeSeconds();
	if (NextBark < 0.f)
	{
		NextBark = Now + JamVoiceRules::NextBarkDelay(Stream);
	}
	if (JamVoiceRules::MayBark(Fight, bSpeaking) && Now >= NextBark)
	{
		LastBark = JamVoiceRules::PickBark(Stream, LastBark);
		Say(LastBark);
	}
}
def speak(key, jobs_path, only):
    """The voice-over: the cast is saved as permanent voices, then each line is spoken into Voice/Lines as an MP3 and a
    48 kHz mono WAV for the engine (ffmpeg)."""
    with open(jobs_path, encoding="utf-8") as handle:
        jobs = json.load(handle)
    voices_path = os.path.join(OUT, "Voice", "voices.json")
    voices = {}
    if os.path.exists(voices_path):
        with open(voices_path, encoding="utf-8") as handle:
            voices = json.load(handle)
    ids = {name: save_voice(key, cast, name, voices) for name, cast in jobs["cast"].items()}
    with open(voices_path, "w", encoding="utf-8") as handle:
        json.dump(voices, handle, indent=1)
    folder = os.path.join(OUT, "Voice", "Lines")
    os.makedirs(folder, exist_ok=True)
    for line in jobs["lines"]:
        if only and line["name"] not in only:
            continue
        body = {"text": line["text"], "model_id": jobs.get("model", "eleven_v3")}
        reply = requests.post(f"{API}/v1/text-to-speech/{ids[line['voice']]}", params={"output_format": "mp3_44100_192"},
                              headers={"xi-api-key": key}, json=body, timeout=180)
        status = "ok" if reply.ok else f"http {reply.status_code}"
        book({"kind": "tts", "name": line["name"], "status": status, "bytes": len(reply.content),
              "request_id": reply.headers.get("request-id", ""), "voice": line["voice"], "text": line["text"]})
        if not reply.ok:
            print(f"[eleven] {line['name']}: {status} {reply.text[:200]}")
            continue
        mp3 = os.path.join(folder, line["name"] + ".mp3")
        with open(mp3, "wb") as handle:
            handle.write(reply.content)
        subprocess.run(["ffmpeg", "-v", "error", "-y", "-i", mp3, "-ac", "1", "-ar", "48000", mp3[:-4] + ".wav"], check=True)
        print(f"[eleven] {line['name']}: ok")


