#include "UI/JamHUD.h"

#include "Engine/Canvas.h"
#include "Engine/Engine.h"
#include "UI/JamTexts.h"

namespace
{
// T-092: the main menu between the two fighters, as fractions of the screen.
constexpr float MenuTitleTop = 0.08f;
constexpr float MenuTitleScale = 4.f;
constexpr float MenuMainTop = 0.42f;
constexpr float MenuSettingsTop = 0.3f;
constexpr float MenuRowShare = 0.062f;
constexpr float MenuColumnShare = 0.3f;
constexpr float MenuTextScale = 1.8f;
constexpr float MenuHintTop = 0.93f;
constexpr float MenuHintScale = 1.2f;
constexpr float MenuEdge = 4.f;
constexpr float MenuPadding = 16.f;
// Pixels the title's shadow sits down and right.
constexpr float MenuShadow = 3.f;
const FLinearColor MenuCyan(0.2f, 0.9f, 1.0f);
const FLinearColor MenuPink(1.0f, 0.3f, 0.85f);
const FLinearColor MenuShadowColor(0.f, 0.f, 0.f, 0.8f);
const FLinearColor MenuBand(0.f, 0.f, 0.f, 0.35f);
const FLinearColor MenuBandSelected(0.f, 0.f, 0.f, 0.7f);
const FLinearColor MenuIdleText(0.72f, 0.74f, 0.8f);
const FLinearColor MenuHintColor(0.6f, 0.6f, 0.7f);
} // namespace

FString AJamHUD::MenuValue(EJamMenuItem Item) const
{
	const FJamMenuSettings& Settings = Menu.Settings;
	switch (Item)
	{
		case EJamMenuItem::Quality:
			return JamTexts::QualityNames[FMath::Clamp(Settings.Quality, 0, JamMenuRules::QualityCount - 1)];
		case EJamMenuItem::Window:
			return JamTexts::WindowNames[FMath::Clamp(Settings.Window, 0, JamMenuRules::WindowCount - 1)];
		case EJamMenuItem::Resolution:
			return Resolutions.IsValidIndex(Settings.Resolution)
				? FString::Printf(TEXT("%d x %d"), Resolutions[Settings.Resolution].X, Resolutions[Settings.Resolution].Y)
				: FString(TEXT("-"));
		case EJamMenuItem::Master:
			return FString::Printf(TEXT("%d%%"), FMath::RoundToInt32(100.f * JamMenuRules::Volume(Settings.Master)));
		case EJamMenuItem::Music:
			return FString::Printf(TEXT("%d%%"), FMath::RoundToInt32(100.f * JamMenuRules::Volume(Settings.Music)));
		case EJamMenuItem::Voice:
			return FString::Printf(TEXT("%d%%"), FMath::RoundToInt32(100.f * JamMenuRules::Volume(Settings.Voice)));
		default:
			return FString();
	}
}

void AJamHUD::DrawMenu()
{
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	UFont* Font = GEngine->GetMediumFont();

	// The title in the cover's colours: RONIN in cyan, FINAL CUT in pink.
	const FString Title = JamTexts::MenuTitle;
	FString Ronin;
	FString Cut;
	if (!Title.Split(TEXT(" "), &Ronin, &Cut))
	{
		Ronin = Title;
	}
	Ronin += TEXT(" ");
	float RoninWidth = 0.f;
	float CutWidth = 0.f;
	float TitleHeight = 0.f;
	GetTextSize(Ronin, RoninWidth, TitleHeight, Font, MenuTitleScale);
	GetTextSize(Cut, CutWidth, TitleHeight, Font, MenuTitleScale);
	const float TitleX = 0.5f * (W - RoninWidth - CutWidth);
	const float TitleY = MenuTitleTop * H;
	DrawText(Ronin, MenuShadowColor, TitleX + MenuShadow, TitleY + MenuShadow, Font, MenuTitleScale);
	DrawText(Cut, MenuShadowColor, TitleX + RoninWidth + MenuShadow, TitleY + MenuShadow, Font, MenuTitleScale);
	DrawText(Ronin, MenuCyan, TitleX, TitleY, Font, MenuTitleScale);
	DrawText(Cut, MenuPink, TitleX + RoninWidth, TitleY, Font, MenuTitleScale);

	const TArray<EJamMenuItem> Items = JamMenuRules::ItemsOf(Menu.Page);
	const bool bSettings = Menu.Page == EJamMenuPage::Settings;
	const float ColumnWidth = MenuColumnShare * W;
	const float Left = 0.5f * (W - ColumnWidth);
	MenuTop = (bSettings ? MenuSettingsTop : MenuMainTop) * H;
	MenuRow = MenuRowShare * H;
	MenuCentreX = 0.5f * W;
	for (int32 Index = 0; Index < Items.Num(); ++Index)
	{
		const bool bSelected = Index == Menu.Selected;
		const float Top = MenuTop + Index * MenuRow;
		DrawRect(bSelected ? MenuBandSelected : MenuBand, Left, Top + 0.5f * MenuEdge, ColumnWidth, MenuRow - MenuEdge);
		if (bSelected)
		{
			DrawRect(MenuCyan, Left, Top + 0.5f * MenuEdge, MenuEdge, MenuRow - MenuEdge);
		}
		const FLinearColor Color = bSelected ? FLinearColor::White : MenuIdleText;
		const FString Label = JamTexts::MenuItem(static_cast<int32>(Items[Index]));
		float Width = 0.f;
		float Height = 0.f;
		GetTextSize(Label, Width, Height, Font, MenuTextScale);
		const float TextY = Top + 0.5f * (MenuRow - Height);
		const FString Value = MenuValue(Items[Index]);
		if (Value.IsEmpty())
		{
			DrawText(Label, Color, 0.5f * (W - Width), TextY, Font, MenuTextScale);
			continue;
		}
		DrawText(Label, Color, Left + MenuPadding, TextY, Font, MenuTextScale);
		const FString Shown = bSelected ? FString::Printf(TEXT("<  %s  >"), *Value) : Value;
		GetTextSize(Shown, Width, Height, Font, MenuTextScale);
		DrawText(Shown, bSelected ? MenuCyan : Color, Left + ColumnWidth - MenuPadding - Width, TextY, Font, MenuTextScale);
	}
	if (bSettings)
	{
		DrawCentered(JamTexts::SettingsHint, MenuTop + Items.Num() * MenuRow + MenuPadding, MenuHintScale, MenuHintColor);
	}
	DrawCentered(JamTexts::MenuHint, MenuHintTop * H, MenuHintScale, MenuHintColor);
}

