#pragma once

#include "CoreMinimal.h"

enum class EJamMenuPage : uint8
{
	Main,
	Settings
};

/** Every row the menu has, on either page, in the order of their labels (JamTexts::MenuItems). */
enum class EJamMenuItem : uint8
{
	NewGame,
	Settings,
	Exit,
	Quality,
	Window,
	Resolution,
	Master,
	Music,
	Voice,
	Back
};

/** What the player pressed: the arrows (or WASD), Enter, Escape. */
enum class EJamMenuKey : uint8
{
	Up,
	Down,
	Left,
	Right,
	Confirm,
	Back
};

/** What the game has to do after a press. */
enum class EJamMenuAction : uint8
{
	None,
	NewGame,
	Exit,
	/** A volume changed: heard at once. */
	Volume,
	/** The settings page closed: the graphics settings are applied and saved. */
	Graphics
};

/** The settings as the menu shows them: indices and volume steps. */
struct FJamMenuSettings
{
	/** 0 LOW to 3 EPIC, the engine's scalability levels. */
	int32 Quality = 3;
	/** JamTexts::WindowNames: fullscreen, borderless, windowed. */
	int32 Window = 1;
	/** Into the screen's resolutions, ResolutionCount long. */
	int32 Resolution = 0;
	int32 ResolutionCount = 0;
	int32 Master = 10;
	int32 Music = 10;
	int32 Voice = 10;
};

struct FJamMenu
{
	EJamMenuPage Page = EJamMenuPage::Main;
	/** The row under the cursor or the arrows, into ItemsOf(Page). */
	int32 Selected = 0;
	FJamMenuSettings Settings;
};

/**
 * The main menu before the intro (T-092): which rows a page has and what a key or a click does to them. Graphics settings
 * apply when the settings page closes, so stepping through resolutions does not flash the screen; volumes at once.
 * Tests: Jam.Menu.*
 */
namespace JamMenuRules
{
inline constexpr int32 ItemCount = 10;
inline constexpr int32 QualityCount = 4;
inline constexpr int32 WindowCount = 3;
inline constexpr int32 VolumeSteps = 10;

JAMGAME_API TArray<EJamMenuItem> ItemsOf(EJamMenuPage Page);

/** One key on the menu: moves the selection, steps a value, changes the page or asks the game to act. */
JAMGAME_API EJamMenuAction Press(FJamMenu& Menu, EJamMenuKey Key);

/** The pointer is over Row of the page (INDEX_NONE: over none): that row becomes the selected one. */
JAMGAME_API void Point(FJamMenu& Menu, int32 Row);

/** The row of Count rows, the first at Top, each RowHeight tall, that Y falls in; INDEX_NONE outside them. */
JAMGAME_API int32 RowAt(float Y, float Top, float RowHeight, int32 Count);

/** The key a click on Item is: an action confirms, a value steps up on its right half and down on its left. */
JAMGAME_API EJamMenuKey ClickKey(EJamMenuItem Item, bool bRightHalf);

/** The volume multiplier of a number of steps. */
JAMGAME_API float Volume(int32 Steps);
} // namespace JamMenuRules
#include "UI/JamMenuRules.h"

namespace
{
bool IsValueRow(EJamMenuItem Item)
{
	return Item >= EJamMenuItem::Quality && Item <= EJamMenuItem::Voice;
}

/** Steps Value by Step round Count values. */
int32 Cycle(int32 Value, int32 Step, int32 Count)
{
	return Count > 0 ? ((Value + Step) % Count + Count) % Count : Value;
}

/** Steps a value row; Volume when a volume changed, None otherwise (the graphics wait for BACK). */
EJamMenuAction StepValue(FJamMenuSettings& Settings, EJamMenuItem Item, int32 Step)
{
	int32* Volume = nullptr;
	switch (Item)
	{
		case EJamMenuItem::Quality:
			Settings.Quality = Cycle(Settings.Quality, Step, JamMenuRules::QualityCount);
			return EJamMenuAction::None;
		case EJamMenuItem::Window:
			Settings.Window = Cycle(Settings.Window, Step, JamMenuRules::WindowCount);
			return EJamMenuAction::None;
		case EJamMenuItem::Resolution:
			Settings.Resolution = Cycle(Settings.Resolution, Step, Settings.ResolutionCount);
			return EJamMenuAction::None;
		case EJamMenuItem::Master:
			Volume = &Settings.Master;
			break;
		case EJamMenuItem::Music:
			Volume = &Settings.Music;
			break;
		default:
			Volume = &Settings.Voice;
			break;
	}
	const int32 Was = *Volume;
	*Volume = FMath::Clamp(Was + Step, 0, JamMenuRules::VolumeSteps);
	return *Volume == Was ? EJamMenuAction::None : EJamMenuAction::Volume;
}

EJamMenuAction CloseSettings(FJamMenu& Menu)
{
	Menu.Page = EJamMenuPage::Main;
	Menu.Selected = JamMenuRules::ItemsOf(EJamMenuPage::Main).IndexOfByKey(EJamMenuItem::Settings);
	return EJamMenuAction::Graphics;
}

EJamMenuAction Confirm(FJamMenu& Menu, EJamMenuItem Item)
{
	switch (Item)
	{
		case EJamMenuItem::NewGame:
			return EJamMenuAction::NewGame;
		case EJamMenuItem::Exit:
			return EJamMenuAction::Exit;
		case EJamMenuItem::Settings:
			Menu.Page = EJamMenuPage::Settings;
			Menu.Selected = 0;
			return EJamMenuAction::None;
		case EJamMenuItem::Back:
			return CloseSettings(Menu);
		default:
			return StepValue(Menu.Settings, Item, 1);
	}
}
} // namespace

TArray<EJamMenuItem> JamMenuRules::ItemsOf(EJamMenuPage Page)
{
	if (Page == EJamMenuPage::Main)
	{
		return { EJamMenuItem::NewGame, EJamMenuItem::Settings, EJamMenuItem::Exit };
	}
	return { EJamMenuItem::Quality, EJamMenuItem::Window, EJamMenuItem::Resolution, EJamMenuItem::Master, EJamMenuItem::Music,
		EJamMenuItem::Voice, EJamMenuItem::Back };
}

EJamMenuAction JamMenuRules::Press(FJamMenu& Menu, EJamMenuKey Key)
{
	const TArray<EJamMenuItem> Items = ItemsOf(Menu.Page);
	Menu.Selected = FMath::Clamp(Menu.Selected, 0, Items.Num() - 1);
	const EJamMenuItem Item = Items[Menu.Selected];
	switch (Key)
	{
		case EJamMenuKey::Up:
			Menu.Selected = Cycle(Menu.Selected, -1, Items.Num());
			return EJamMenuAction::None;
		case EJamMenuKey::Down:
			Menu.Selected = Cycle(Menu.Selected, 1, Items.Num());
			return EJamMenuAction::None;
		case EJamMenuKey::Left:
		case EJamMenuKey::Right:
			return IsValueRow(Item) ? StepValue(Menu.Settings, Item, Key == EJamMenuKey::Right ? 1 : -1) : EJamMenuAction::None;
		case EJamMenuKey::Confirm:
			return Confirm(Menu, Item);
		default:
			return Menu.Page == EJamMenuPage::Settings ? CloseSettings(Menu) : EJamMenuAction::None;
	}
}

void JamMenuRules::Point(FJamMenu& Menu, int32 Row)
{
	if (Row >= 0 && Row < ItemsOf(Menu.Page).Num())
	{
		Menu.Selected = Row;
	}
}

int32 JamMenuRules::RowAt(float Y, float Top, float RowHeight, int32 Count)
{
	if (RowHeight <= 0.f || Y < Top)
	{
		return INDEX_NONE;
	}
	const int32 Row = FMath::FloorToInt32((Y - Top) / RowHeight);
	return Row < Count ? Row : INDEX_NONE;
}

EJamMenuKey JamMenuRules::ClickKey(EJamMenuItem Item, bool bRightHalf)
{
	if (!IsValueRow(Item))
	{
		return EJamMenuKey::Confirm;
	}
	return bRightHalf ? EJamMenuKey::Right : EJamMenuKey::Left;
}

float JamMenuRules::Volume(int32 Steps)
{
	return static_cast<float>(FMath::Clamp(Steps, 0, VolumeSteps)) / VolumeSteps;
}
