#include "CoreMinimal.h"
#include "GameFramework/Actor.h"
#include "JamVoice.generated.h"
class UAudioComponent;
class USoundWave;
/**
 * The voice-over: says the lines JamVoiceRules picks one after another, never two at once, and the Publisher's barks
 * now and then in the fight. Runs on real time, so a slowed world does not stretch a line. A line outlives the steal
 * card it started on. His comment on a stolen move waits for the crack between two looks and the card's lines.
 *
 * The sounds are /Game/Audio/Voice/<line name>; a missing one is skipped silently with its subtitle.
 */
UCLASS()
class JAMGAME_API AJamVoice : public AActor
{
	GENERATED_BODY()
public:
	AJamVoice();
	virtual void Tick(float DeltaSeconds) override;
	/** Queues Line, or says it at once over everything when it cuts in (JamVoiceRules::CutsIn) or bNow. */
	void Say(EJamLine Line, bool bNow = false);
	/**
	 * The lines of a frame's events, and the barks of the fight; Fight is the state after the events, bCracking whether the
	 * crack between two looks is still open.
	 */
	void Hear(const TArray<FJamEvent>& Events, const FJamFight& Fight, bool bCracking);
	/** Stops the line being said and drops the queue. */
	void Hush();
	/** The line being said now, false when nobody talks. */
	bool Current(EJamLine& OutLine) const;
	/** Whether a line is playing now: the sound effects duck under it. */
	bool IsSpeaking() const { return bSpeaking; }
	/** The player's voice volume from the menu (T-092), 0 to 1. */
	void SetGain(float InGain);
private:
	void StartNext(float Now);
	UPROPERTY()
	TArray<TObjectPtr<USoundWave>> Sounds;
	UPROPERTY()
	TObjectPtr<UAudioComponent> Playing;
	TArray<EJamLine> Queue;
	/** Comments on a stolen move, waiting for the crack to close. */
	TArray<EJamLine> Held;
	bool bSpeaking = false;
	EJamLine Line = EJamLine::IntroBoss;
	/** Real time the line being said ends, and the next bark is due (negative: not yet set). */
	float LineEnd = 0.f;
	float NextBark = -1.f;
	EJamLine LastBark = EJamLine::Bark4;
	FRandomStream Stream;
	float Gain = 1.f;
};
#include "Audio/JamVoice.h"
#include "Components/AudioComponent.h"
#include "Kismet/GameplayStatics.h"
#include "Sound/SoundWave.h"
#include "UObject/ConstructorHelpers.h"
AJamVoice::AJamVoice()
{
	PrimaryActorTick.bCanEverTick = true;
	SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));
	for (int32 Index = 0; Index < JamVoiceRules::LineCount; ++Index)
	{
		const TCHAR* Name = JamVoiceRules::NameOf(static_cast<EJamLine>(Index));
		ConstructorHelpers::FObjectFinder<USoundWave> Finder(*FString::Printf(TEXT("/Game/Audio/Voice/%s.%s"), Name, Name));
		Sounds.Add(Finder.Object);
	}
	Stream.Initialize(FPlatformTime::Cycles());
}
void AJamVoice::Say(EJamLine NewLine, bool bNow)
{
	if (bNow || JamVoiceRules::CutsIn(NewLine))
	{
		Hush();
	}
	Queue.Add(NewLine);
	if (!bSpeaking)
	{
		StartNext(GetWorld()->GetRealTimeSeconds());
	}
}
void AJamVoice::Hush()
{
	Queue.Reset();
	Held.Reset();
	bSpeaking = false;
	if (Playing)
	{
		Playing->Stop();
		Playing = nullptr;
	}
}
void AJamVoice::SetGain(float InGain)
{
	Gain = InGain;
	if (Playing)
	{
		Playing->SetVolumeMultiplier(Gain);
	}
}
bool AJamVoice::Current(EJamLine& OutLine) const
{
	OutLine = Line;
	return bSpeaking;
}
void AJamVoice::StartNext(float Now)
{
	bSpeaking = false;
	while (!Queue.IsEmpty() && !bSpeaking)
	{
		Line = Queue[0];
		Queue.RemoveAt(0);
		USoundWave* Sound = Sounds[static_cast<int32>(Line)];
		if (!Sound)
		{
			continue;
		}
		Playing = UGameplayStatics::SpawnSound2D(this, Sound, Gain);
		LineEnd = Now + Sound->GetDuration();
		bSpeaking = true;
	}
	if (!bSpeaking)
	{
		Playing = nullptr;
		NextBark = Now + JamVoiceRules::NextBarkDelay(Stream);
	}
}
void AJamVoice::Tick(float DeltaSeconds)
{
	Super::Tick(DeltaSeconds);
	const float Now = GetWorld()->GetRealTimeSeconds();
	if (bSpeaking && Now >= LineEnd)
	{
		StartNext(Now);
	}
}
void AJamVoice::Hear(const TArray<FJamEvent>& Events, const FJamFight& Fight, bool bCracking)
{
	for (const EJamLine NewLine : JamVoiceRules::LinesOf(Events, Fight))
	{
		Say(NewLine);
	}
	const float Now = GetWorld()->GetRealTimeSeconds();
	Held.Append(JamVoiceRules::CommentsOf(Events));
	const int32 Queued = Queue.Num();
	JamVoiceRules::Release(Held, Queue, bCracking);
	if (Queue.Num() > Queued && !bSpeaking)
	{
		StartNext(Now);
	}
	if (NextBark < 0.f)
	{
		NextBark = Now + JamVoiceRules::NextBarkDelay(Stream);
	}
	if (JamVoiceRules::MayBark(Fight, bSpeaking, !Held.IsEmpty()) && Now >= NextBark)
	{
		LastBark = JamVoiceRules::PickBark(Stream, LastBark);
		Say(LastBark);
	}
}
#pragma once

#include "CoreMinimal.h"

/**
 * The intro before the first fight (T-030): the Publisher shows off (his Kung_Fu_Punch clip) under a title card while
 * the fight waits, then the camera goes over to the hero. Skippable; once per launch, not on a retry.
 * Tests: Jam.Intro.*
 */
namespace JamIntroRules
{
/**
 * Whether the intro is over Age seconds in: it ran its Length, or a skip came after SkipAfter (a click still held
 * from starting the game does not skip it).
 */
JAMGAME_API bool IsOver(float Age, float Length, bool bSkip, float SkipAfter);

/** How visible the title card is: it fades in over Fade, stays, and fades out over the last Fade of Length. */
JAMGAME_API float TitleAlpha(float Age, float Length, float Fade);

/** How far the camera has gone from the Publisher to the hero: 0 until the last Return seconds, then eased to 1. */
JAMGAME_API float CameraToHero(float Age, float Length, float Return);

/** T-083: how much of the Publisher's health bar shows SinceFight seconds after the intro ended (negative: still in
 * the intro): none through the show, fading in over Fade once the fight starts. */
JAMGAME_API float BossBarAlpha(float SinceFight, float Fade);

/** T-089: when the hero starts his draw, Age seconds in: as the camera starts over to him, Return before the show ends. */
JAMGAME_API float HeroDrawStart(float Length, float Return);

/** T-089: how long the whole intro lasts: the Publisher's show, or until the hero's Draw seconds end if that is later. */
JAMGAME_API float FullLength(float Length, float Return, float Draw);
} // namespace JamIntroRules

