#pragma once
#include "Core/JamTypes.h"
#include "CoreMinimal.h"
#include "GameFramework/PlayerController.h"
#include "JamPlayerController.generated.h"
class AJamCameraRig;
/**
 * The player's hands: turns the keyboard and the mouse into the hero's intent. The camera is the top-down one only (T-018):
 * the cursor aims, the keys move in screen axes. The player has no pawn, the hero is a body of the simulation.
 *
 * Keys are polled on purpose. The prototype has a dozen fixed keys and no rebinding, so input assets would only be one
 * more thing to cook.
 */
UCLASS()
class JAMGAME_API AJamPlayerController : public APlayerController
{
	GENERATED_BODY()
public:
	AJamPlayerController();
	/** Reads this frame's input and returns what the hero wants to do. */
	FJamIntent ReadIntent(const AJamCameraRig& Rig, const FJamFighter& Hero);
	/** The mouse behaviour of the top-down camera: a visible cursor locked to the window. */
	void UseCursor();
	/** The floor point under the cursor as seen through the camera at CameraNow, after the camera moved this frame. */
	FVector2D LiveAimPoint(const FVector& CameraNow) const;
private:
	/** The last known aim: kept while the cursor ray misses the arena. */
	FJamAim Aim;
	/** Where the camera stood when the cursor was last read: the view of the last rendered frame. */
	FVector AimCamera = FVector::ZeroVector;
};
#include "Game/JamPlayerController.h"
#include "Sim/JamAimRules.h"
#include "Sim/JamMoveRules.h"
#include "View/JamCameraRig.h"
AJamPlayerController::AJamPlayerController()
{
	bAutoManageActiveCameraTarget = false;
}
void AJamPlayerController::UseCursor()
{
	FInputModeGameAndUI InputMode;
	InputMode.SetLockMouseToViewportBehavior(EMouseLockMode::LockAlways);
	InputMode.SetHideCursorDuringCapture(false);
	SetInputMode(InputMode);
	SetShowMouseCursor(true);
}
FVector2D AJamPlayerController::LiveAimPoint(const FVector& CameraNow) const
{
	return JamAimRules::FollowCamera(Aim.Point, AimCamera, CameraNow);
}
FJamIntent AJamPlayerController::ReadIntent(const AJamCameraRig& Rig, const FJamFighter& Hero)
{
	FVector Origin;
	FVector Direction;
	if (DeprojectMousePositionToWorld(Origin, Direction) && JamAimRules::FromRay(Origin, Direction, 0.f, Hero.Pos, Aim))
	{
		AimCamera = PlayerCameraManager ? PlayerCameraManager->GetCameraLocation() : Rig.GetActorLocation();
	}
	FJamIntent Intent;
	const FVector2D Keys((IsInputKeyDown(EKeys::D) ? 1.0 : 0.0) - (IsInputKeyDown(EKeys::A) ? 1.0 : 0.0),
		(IsInputKeyDown(EKeys::W) ? 1.0 : 0.0) - (IsInputKeyDown(EKeys::S) ? 1.0 : 0.0));
	Intent.Move = JamMoveRules::WorldMove(Keys, Rig.GetMoveBasisYaw());
	Intent.Aim = Aim;
	Intent.bPrimary = IsInputKeyDown(EKeys::LeftMouseButton);
	Intent.bSecondary = IsInputKeyDown(EKeys::RightMouseButton);
	Intent.bDash = IsInputKeyDown(EKeys::SpaceBar);
	// No parry key (T-044): the strike parries a shot about to land (JamParryRules::ShotInReach).
	Intent.bUltimate = IsInputKeyDown(EKeys::E);
	// The steal card is answered with the keys under the left hand: a press, not a hold, so walking left is no answer.
	if (WasInputKeyJustPressed(EKeys::A) || WasInputKeyJustPressed(EKeys::Left))
	{
		Intent.Choice = 0;
	}
	else if (WasInputKeyJustPressed(EKeys::D) || WasInputKeyJustPressed(EKeys::Right))
	{
		Intent.Choice = 1;
	}
	return Intent;
}
