#pragma once

#include "CoreMinimal.h"
#include "Sim/JamLayerRules.h"

#include "JamNeonRules.generated.h"

/**
 * Numbers of the neon look of the stand-ins. The values live in the [JamNeon] section of Config/DefaultGame.ini, one
 * line per field. Glow is the multiplier of the neon material: above 1 it blooms.
 */
USTRUCT()
struct JAMGAME_API FJamNeonSettings
{
	GENERATED_BODY()

	/** The tempo of the music the floor lines pulse to. */
	UPROPERTY()
	float Bpm = 0.f;

	/** The glow of the floor lines between beats, the extra glow on a beat, and how fast the extra dies (seconds). */
	UPROPERTY()
	float LineGlow = 0.f;

	UPROPERTY()
	float BeatPulse = 0.f;

	UPROPERTY()
	float BeatDecay = 0.f;

	/** The steady glow of the posts and of the ring at the edge of the arena. */
	UPROPERTY()
	float PostGlow = 0.f;

	UPROPERTY()
	float EdgeGlow = 0.f;

	/** The glow of the effects: blades, flashes, warnings. */
	UPROPERTY()
	float EffectGlow = 0.f;

	/** Bloom of the camera with the full art, with the shape ronin's plain effects (T-077), and once the Publisher took
	 * the effects too. */
	UPROPERTY()
	float Bloom = 0.f;

	UPROPERTY()
	float BloomFlat = 0.f;

	UPROPERTY()
	float BloomCut = 0.f;
};

/**
 * The light and the post process of a tier (T-077): the full art gets Lumen, neon lights round the arena, bloom, a
 * vignette and a grade; the shape ronin a flat light with a hint of bloom; greybox the bare engine look.
 */
#pragma once

#include "CoreMinimal.h"

/**
 * Loads a struct of numbers from a section of Config/DefaultGame.ini: one line per UPROPERTY, named as the field.
 * Tests: Jam.Balance.IniIsCompleteAndValid, Jam.Camera.IniIsComplete
 */
namespace JamConfig
{
/** Section with the balance numbers (FJamBalanceData). */
inline const TCHAR* const BalanceSection = TEXT("JamBalance");

/** Fills Data, a struct of type Struct. Fields without a readable line keep their value and are named in OutMissing. */
JAMGAME_API void LoadStruct(const UScriptStruct& Struct, void* Data, const TCHAR* Section, TArray<FString>* OutMissing);

template <typename T>
T Load(const TCHAR* Section, TArray<FString>* OutMissing = nullptr)
{
	T Value;
	LoadStruct(*T::StaticStruct(), &Value, Section, OutMissing);
	return Value;
}
} // namespace JamConfig
