"""Appends the T-094 tests before the closing #endif of each test file."""
import os

ROOT = "F:/Unreal_Engine/UnrealProjects/MegaJam2026/Source/JamGame/Private/Tests/"

TESTS = {
    "JamPoseTest.cpp": r'''
IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamPoseLoopTest, "Jam.Pose.TheIdleLoopsForever", JamTest::Flags)

bool FJamPoseLoopTest::RunTest(const FString& Parameters)
{
	// T-094: on the menu both fighters froze on the idle's last frame after its first loop.
	TestEqual(TEXT("inside the first loop"), JamPoseRules::LoopTime(1.5f, 4.f), 1.5f);
	TestTrue(TEXT("the second loop starts again"), FMath::IsNearlyEqual(JamPoseRules::LoopTime(5.f, 4.f), 1.f, 1e-4f));
	TestTrue(TEXT("an hour in it still moves"), JamPoseRules::LoopTime(3601.f, 4.f) < 4.f);
	TestTrue(TEXT("and differs a moment later"),
		!FMath::IsNearlyEqual(JamPoseRules::LoopTime(3601.f, 4.f), JamPoseRules::LoopTime(3601.5f, 4.f), 1e-3f));
	TestEqual(TEXT("a clip without length stays at its start"), JamPoseRules::LoopTime(7.f, 0.f), 0.f);
	TestTrue(TEXT("never negative"), JamPoseRules::LoopTime(-1.f, 4.f) >= 0.f);
	return true;
}
''',
    "JamArenaTest.cpp": r'''
IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamArenaBackdropTest, "Jam.Arena.TheSkylineCoversAnyScreen", JamTest::Flags)

bool FJamArenaBackdropTest::RunTest(const FString& Parameters)
{
	// T-094: on an ultrawide screen the skyline left strips at both sides and cut off the tower's dollar sign.
	const FVector Eye(0.0, 1200.0, 170.0);
	const FVector LookAt(0.0, 0.0, 125.0);
	constexpr float Fov = 50.f;
	constexpr double Distance = 10200.0;
	constexpr float Picture = 3.f;
	const double HalfTanY = FMath::Tan(FMath::DegreesToRadians(0.5 * Fov)) / (16.0 / 9.0);
	const double CentreZ = Eye.Z + Distance * (LookAt.Z - Eye.Z) / (Eye.Y - LookAt.Y);
	for (const float Aspect : { 4.f / 3.f, 16.f / 9.f, 21.f / 9.f, 32.f / 9.f, 5.f })
	{
		const FJamBackdropPlace Place = JamArenaRules::PlaceBackdrop(Eye, LookAt, Fov, Aspect, Picture, Distance);
		const double HalfH = Distance * HalfTanY;
		const double HalfW = HalfH * Aspect;
		const FString At = FString::Printf(TEXT(" at %.2f:1"), Aspect);
		TestTrue(TEXT("the picture keeps its shape") + At, FMath::IsNearlyEqual(Place.Width / Place.Height, static_cast<double>(Picture), 1e-6));
		TestTrue(TEXT("no strip at the sides") + At, 0.5 * Place.Width >= HalfW);
		TestTrue(TEXT("none at the top") + At, Place.CentreZ + 0.5 * Place.Height >= CentreZ + HalfH);
		TestTrue(TEXT("none at the bottom") + At, Place.CentreZ - 0.5 * Place.Height <= CentreZ - HalfH);
		// The tower's crown is in the top tenth of the picture: it has to be on the screen.
		TestTrue(TEXT("the picture's top tenth shows") + At, Place.CentreZ + 0.4 * Place.Height <= CentreZ + HalfH);
	}
	const FJamBackdropPlace Wide = JamArenaRules::PlaceBackdrop(Eye, LookAt, Fov, 16.f / 9.f, Picture, Distance);
	TestTrue(TEXT("on a usual screen the whole height shows"), Wide.Height <= 2.0 * Distance * HalfTanY * 1.05);
	return true;
}
''',
    "JamComicTest.cpp": r'''
IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamComicFrameTest, "Jam.Comic.TheComicKeepsItsShapeOnAnyScreen", JamTest::Flags)

bool FJamComicFrameTest::RunTest(const FString& Parameters)
{
	// T-094: on an ultrawide screen the comic stretched across all of it and the eye had to hunt for the balloons.
	const FBox2D Usual = JamComicRules::Frame(FVector2D(1920.0, 1080.0));
	TestTrue(TEXT("a 16:9 screen is all comic"), Usual.Min.Equals(FVector2D(0.0, 0.0), 0.5) && Usual.Max.Equals(FVector2D(1920.0, 1080.0), 0.5));
	const FBox2D Ultra = JamComicRules::Frame(FVector2D(3440.0, 1440.0));
	TestTrue(TEXT("an ultrawide one gets the comic's own shape"),
		FMath::IsNearlyEqual(Ultra.GetSize().X / Ultra.GetSize().Y, static_cast<double>(JamComicRules::FrameAspect), 1e-3));
	TestTrue(TEXT("the full height"), FMath::IsNearlyEqual(Ultra.GetSize().Y, 1440.0, 0.5));
	TestTrue(TEXT("centred, bars at both sides"), FMath::IsNearlyEqual(Ultra.Min.X, 3440.0 - Ultra.Max.X, 0.5) && Ultra.Min.X > 0.0);
	const FBox2D Square = JamComicRules::Frame(FVector2D(1024.0, 768.0));
	TestTrue(TEXT("a narrower screen is all comic"), Square.Min.Equals(FVector2D(0.0, 0.0), 0.5) && Square.Max.Equals(FVector2D(1024.0, 768.0), 0.5));
	return true;
}
''',
    "JamIntroTest.cpp": r'''
IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamIntroThemeTest, "Jam.Intro.TheAmbientGivesWayToTheTheme", JamTest::Flags)

bool FJamIntroThemeTest::RunTest(const FString& Parameters)
{
	// T-094: the comic played under the full fight music; it gets a soft ambient until the Publisher's intro line ends.
	TestTrue(TEXT("the menu has the theme"), JamIntroRules::IsThemeUp(true, false, false, false));
	TestFalse(TEXT("the comic the ambient"), JamIntroRules::IsThemeUp(false, true, false, false));
	TestFalse(TEXT("so does the intro while he talks"), JamIntroRules::IsThemeUp(false, false, false, false));
	TestTrue(TEXT("the theme comes once his line is over"), JamIntroRules::IsThemeUp(false, false, false, true));
	TestTrue(TEXT("or at once on a skip"), JamIntroRules::IsThemeUp(false, false, true, false));
	float Theme = 0.f;
	Theme = JamIntroRules::Crossfade(Theme, true, 1.f, 2.f);
	TestTrue(TEXT("halfway after half the crossfade"), FMath::IsNearlyEqual(Theme, 0.5f, 1e-4f));
	Theme = JamIntroRules::Crossfade(Theme, true, 5.f, 2.f);
	TestEqual(TEXT("then all theme"), Theme, 1.f);
	TestEqual(TEXT("down to the ambient"), JamIntroRules::Crossfade(1.f, false, 5.f, 2.f), 0.f);
	TestEqual(TEXT("no crossfade time switches at once"), JamIntroRules::Crossfade(0.f, true, 0.01f, 0.f), 1.f);
	return true;
}
''',
    "JamVoiceTest.cpp": r'''
IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamVoiceLoudTest, "Jam.Voice.LinesPlayLouderThanRecorded", JamTest::Flags)

bool FJamVoiceLoudTest::RunTest(const FString& Parameters)
{
	// T-094: the author heard the voices too quiet, in the comic and in the fight: 25 to 30% louder.
	TestTrue(TEXT("full voice volume is 25 to 30% louder"), JamVoiceRules::Loudness(1.f) >= 1.25f && JamVoiceRules::Loudness(1.f) <= 1.3f);
	TestEqual(TEXT("silence stays silent"), JamVoiceRules::Loudness(0.f), 0.f);
	TestTrue(TEXT("half the menu's volume is half as loud"),
		FMath::IsNearlyEqual(JamVoiceRules::Loudness(0.5f), 0.5f * JamVoiceRules::Loudness(1.f), 1e-5f));
	return true;
}
''',
    "JamNeonTest.cpp": r'''
IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamNeonFilmTest, "Jam.Neon.TheFilmLookIsTheFullArtsOnly", JamTest::Flags)

bool FJamNeonFilmTest::RunTest(const FString& Parameters)
{
	// T-094: grain, fringes, rain haze and a soft distance over the full art, so the generated textures read as atmosphere.
	const FJamNeonSettings S = JamConfig::Load<FJamNeonSettings>(JamNeonRules::Section);
	const FJamFilmLook Full = JamNeonRules::FilmLookFor(EJamLight::Neon, S);
	TestTrue(TEXT("the full art has grain"), Full.Grain > 0.f);
	TestTrue(TEXT("fringes"), Full.Fringe > 0.f);
	TestTrue(TEXT("only at the edges"), Full.FringeStart > 0.f);
	TestTrue(TEXT("haze"), Full.FogDensity > 0.f && Full.FogOpacity > 0.f && Full.FogOpacity < 1.f);
	TestTrue(TEXT("a soft distance"), Full.FarBlurKm > 0.f && Full.FarBlurRadius > 0.f);
	TestTrue(TEXT("a light touch: the grain is fine"), Full.Grain <= 0.4f);
	TestTrue(TEXT("the fighters stay clear: the haze starts past them"), Full.FogStart >= 1500.f);
	for (const EJamLight Lower : { EJamLight::Flat, EJamLight::Bare })
	{
		const FJamFilmLook None = JamNeonRules::FilmLookFor(Lower, S);
		TestTrue(TEXT("a lower tier stays clean"), None.Grain == 0.f && None.Fringe == 0.f && None.FogDensity == 0.f && None.FarBlurRadius == 0.f);
	}
	return true;
}
''',
}

for name, body in TESTS.items():
    path = os.path.join(ROOT, name)
    text = open(path, encoding="utf-8").read()
    cut = text.rstrip().rfind("#endif")
    assert cut > 0, name
    text = text[:cut].rstrip("\n") + "\n" + body + "\n" + text[cut:]
    open(path, "w", encoding="utf-8", newline="\n").write(text)
    print("ok", name)

