	Layout = JamMenuRules::Layout(Menu, FullHd);
	TestTrue(TEXT("a click on NEW GAME starts"),
		JamMenuRules::Click(Menu, Layout, Layout.Rows[RowOf(EJamMenuPage::Main, EJamMenuItem::NewGame)].GetCenter()) == EJamMenuAction::NewGame);
