9	
10	namespace
11	{
12	void Extract(const UAnimSequence& Sequence, float Time, bool bLoop, FPoseContext& Into)
13	{
14		FAnimationPoseData Data(Into);
15		Sequence.GetAnimationPose(Data, FAnimExtractContext(static_cast<double>(Time), false, FDeltaTimeRecord(), bLoop));
16	}
17	
18	const FName PoseHipsBone = TEXT("pelvis");
19	const FName PoseChestBone = TEXT("spine_03");
20	
21	struct FJamPoseProxy : public FAnimInstanceProxy
22	{
23		explicit FJamPoseProxy(UAnimInstance* Instance)
24			: FAnimInstanceProxy(Instance)
25		{
26		}
27	
28		FJamPoseFrame Frame;
29	
30		virtual void PreUpdate(UAnimInstance* Instance, float DeltaSeconds) override
31		{
32			FAnimInstanceProxy::PreUpdate(Instance, DeltaSeconds);
33			Frame = CastChecked<UJamPoseInstance>(Instance)->Frame;
34		}
35	
36		virtual bool Evaluate(FPoseContext& Output) override
37		{
38			if (Frame.bRefPose || !Frame.Idle)
39			{
40				Output.ResetToRefPose();
41				return true;
42			}
43			Extract(*Frame.Idle, Frame.IdleTime, true, Output);
44			if (Frame.MoveWeight > 0.f)
45			{
46				BlendRuns(Output);
47			}
48			if (Frame.Fading && Frame.FadingWeight > 0.f)
49			{
50				FPoseContext Fading(Output);
51				Extract(*Frame.Fading, Frame.FadingTime, false, Fading);
52				BlendAction(Output, Fading, Frame.FadingWeight, Frame.bFadingFullBody);
53			}
54			if (Frame.Action && Frame.ActionWeight > 0.f)
55			{
56				FPoseContext Action(Output);
57				Extract(*Frame.Action, Frame.ActionTime, false, Action);
58				BlendAction(Output, Action, Frame.ActionWeight, Frame.bFullBody);
59			}
60			if (Frame.Lean && Frame.LeanWeight > 0.f)
61			{
62				AddLean(Output);
63			}
64			if (Frame.MoveWeight > 0.f || !FMath::IsNearlyZero(Frame.TurnLean))
65			{
66				TwistAndLean(Output);
67			}
68			return true;
69		}
70	
71		/**
72		 * Degrees (about Z, in component space) the walk's hips and chest are turned off the plain forward run's: a
73		 * diagonal run turns the whole body its way, and the chest has to come back to the aim (TwistAndLean).
74		 */
75		float HipsOffRun = 0.f;
76		float ChestOffRun = 0.f;
77	
78		/** The yaw that brings Bone of Pose to where it is in Reference, in degrees. */
79		static float YawTo(const FCompactPose& Reference, const FCompactPose& Pose, FCompactPoseBoneIndex Bone)
80		{
81			if (!Bone.IsValid())
82			{
83				return 0.f;
84			}
85			const FQuat Delta = ComponentRotation(Reference, Bone) * ComponentRotation(Pose, Bone).Inverse();
86			return FMath::RadiansToDegrees(FMath::UnwindRadians(static_cast<float>(Delta.GetTwistAngle(FVector::UpVector))));
87		}
88	
89		/** The directional runs, each by its weight, into one walk over the idle by MoveWeight (T-078). */
90		void BlendRuns(FPoseContext& Output)
91		{
92			HipsOffRun = 0.f;
93			ChestOffRun = 0.f;
94			FPoseContext Walk(Output);
95			float Taken = 0.f;
96			for (int32 Run = 0; Run < FJamPoseFrame::RunCount; ++Run)
97			{
98				const float Weight = Frame.RunWeights[Run];
99				if (!Frame.Runs[Run] || Weight <= 0.f)
100				{
101					continue;
102				}
103				if (Taken <= 0.f)
104				{
105					Extract(*Frame.Runs[Run], Frame.RunTimes[Run], true, Walk);
106				}
107				else
108				{
109					FPoseContext Next(Output);
110					Extract(*Frame.Runs[Run], Frame.RunTimes[Run], true, Next);
111					FAnimationPoseData Into(Walk);
112					FAnimationRuntime::BlendTwoPosesTogetherInPlace(Into, FAnimationPoseData(Next), Taken / (Taken + Weight));
113				}
114				Taken += Weight;
115			}
116			if (Taken > 0.f && Frame.Runs[0] && Frame.RunWeights[0] < 1.f)
117			{
118				FPoseContext Forward(Output);
119				Extract(*Frame.Runs[0], Frame.RunTimes[0], true, Forward);
120				HipsOffRun = YawTo(Forward.Pose, Walk.Pose, BoneNamed(Output, PoseHipsBone));
121				ChestOffRun = YawTo(Forward.Pose, Walk.Pose, BoneNamed(Output, PoseChestBone));
122			}
123			if (Taken > 0.f)
124			{
125				const TArray<bool, TInlineAllocator<64>> Upper = UpperBody(Output);
126				for (const FCompactPoseBoneIndex Bone : Output.Pose.ForEachBoneIndex())
127				{
128					Output.Pose[Bone].BlendWith(Walk.Pose[Bone], Frame.MoveWeight * (Upper[Bone.GetInt()] ? Frame.UpperWalk : 1.f));
129				}
130			}
131		}
132	
133		static FCompactPoseBoneIndex BoneNamed(const FPoseContext& Output, FName Name)
134		{
135			const FBoneContainer& Bones = Output.Pose.GetBoneContainer();
136			const int32 MeshIndex = Bones.GetPoseBoneIndexForBoneName(Name);
137			return MeshIndex == INDEX_NONE ? FCompactPoseBoneIndex(INDEX_NONE) : Bones.MakeCompactPoseIndex(FMeshPoseBoneIndex(MeshIndex));
138		}
139	
140		/** The bone's rotation in component space, from the local rotations of its chain. */
141		static FQuat ComponentRotation(const FCompactPose& Pose, FCompactPoseBoneIndex Bone)
142		{
143			FQuat Rotation = FQuat::Identity;
144			for (FCompactPoseBoneIndex At = Bone; At.IsValid(); At = Pose.GetParentBoneIndex(At))
145			{
146				Rotation = Pose[At].GetRotation() * Rotation;
147			}
148			return Rotation;
149		}
150	
151		/** Turns Bone, and everything under it, by Turn in component space about the bone's own joint. */
152		static void TurnInComponent(FCompactPose& Pose, FCompactPoseBoneIndex Bone, const FQuat& Turn)
153		{
154			const FCompactPoseBoneIndex Parent = Pose.GetParentBoneIndex(Bone);
155			const FQuat ParentRotation = Parent.IsValid() ? ComponentRotation(Pose, Parent) : FQuat::Identity;
156			const FQuat Local = ParentRotation.Inverse() * Turn * ParentRotation * Pose[Bone].GetRotation();
157			Pose[Bone].SetRotation(Local.GetNormalized());
158		}
159	
160		/**
161		 * T-078: the hips and the legs turn toward the move, the spine turns back over its bones so the chest keeps
162		 * facing the aim; then the upper body leans into the turn. The model faces +Y in component space, Z up.
163		 */
164		void TwistAndLean(FPoseContext& Output) const
165		{
166			static const FName Spine[] = { TEXT("spine_01"), TEXT("spine_02"), PoseChestBone };
167			FCompactPose& Pose = Output.Pose;
168			TArray<FCompactPoseBoneIndex, TInlineAllocator<3>> SpineBones;
169			for (const FName& Name : Spine)
170			{
171				const FCompactPoseBoneIndex Bone = BoneNamed(Output, Name);
172				if (Bone.IsValid())
173				{
174					SpineBones.Add(Bone);
175				}
176			}
177			const FCompactPoseBoneIndex Pelvis = BoneNamed(Output, PoseHipsBone);
178			if (!Pelvis.IsValid() || SpineBones.IsEmpty())
179			{
180				return;
181			}
182			// T-084: an action owns the chest (a throw while backpedalling twisted it away): the warp fades as it comes in.
183			const float Warp = JamPoseRules::WarpWeight(Frame.ActionWeight, Frame.bFullBody);
184			const float TwistRadians = FMath::DegreesToRadians(Frame.Twist) * Warp;
185			TurnInComponent(Pose, Pelvis, FQuat(FVector::UpVector, TwistRadians));
186			// The chest comes back from the twist and from the diagonal run's own turn.
187			const float OffRun = Frame.MoveWeight * ChestOffRun * Warp;
188			const FQuat Back(FVector::UpVector, (FMath::DegreesToRadians(OffRun) - TwistRadians) / SpineBones.Num());
189			for (const FCompactPoseBoneIndex Bone : SpineBones)
190			{
191				TurnInComponent(Pose, Bone, Back);
192			}
193			// A lean to the right brings the head toward component -X (the model's right) about its forward +Y axis.
194			TurnInComponent(Pose, SpineBones[0], FQuat(FVector::RightVector, -FMath::DegreesToRadians(Frame.TurnLean)));
195		}
196	
197		/** Which bones are the upper body: UpperBodyBone and everything under it. Parents come first in a compact pose. */
198		static TArray<bool, TInlineAllocator<64>> UpperBody(const FPoseContext& Output)
199		{
200			const FBoneContainer& Bones = Output.Pose.GetBoneContainer();
201			const FReferenceSkeleton& RefSkeleton = Bones.GetReferenceSkeleton();
202			TArray<bool, TInlineAllocator<64>> Upper;
203			Upper.SetNumZeroed(Output.Pose.GetNumBones());
204			for (const FCompactPoseBoneIndex Bone : Output.Pose.ForEachBoneIndex())
205			{
206				const FCompactPoseBoneIndex Parent = Output.Pose.GetParentBoneIndex(Bone);
207				const FName Name = RefSkeleton.GetBoneName(Bones.MakeMeshPoseIndex(Bone).GetInt());
208				Upper[Bone.GetInt()] = Name == UJamPoseInstance::UpperBodyBone || (Parent.IsValid() && Upper[Parent.GetInt()]);
209			}
210			return Upper;
211		}
212	
213		/** The hit lean: the upper body turns by the clip's peak against its first frame, an additive rotation only. */
214		void AddLean(FPoseContext& Output) const
215		{
216			FPoseContext Peak(Output);
217			Extract(*Frame.Lean, Frame.LeanTime, false, Peak);
218			FPoseContext Rest(Output);
219			Extract(*Frame.Lean, 0.f, false, Rest);
220			const TArray<bool, TInlineAllocator<64>> Upper = UpperBody(Output);
221			for (const FCompactPoseBoneIndex Bone : Output.Pose.ForEachBoneIndex())
222			{
223				if (!Upper[Bone.GetInt()])
224				{
225					continue;
226				}
227				const FQuat Delta = Peak.Pose[Bone].GetRotation() * Rest.Pose[Bone].GetRotation().Inverse();
228				const FQuat Turn = FQuat::Slerp(FQuat::Identity, Delta, Frame.LeanWeight);
229				Output.Pose[Bone].SetRotation((Turn * Output.Pose[Bone].GetRotation()).GetNormalized());
230			}
231		}
232	
233		/** The action over the upper body, and over the legs as far as they are not walking. */
234		void BlendAction(FPoseContext& Output, const FPoseContext& Action, float Weight, bool bFullBody) const
235		{
236			const float Legs = bFullBody ? 1.f : 1.f - Frame.MoveWeight;
237			const TArray<bool, TInlineAllocator<64>> Upper = UpperBody(Output);
238			for (const FCompactPoseBoneIndex Bone : Output.Pose.ForEachBoneIndex())
239			{
240				Output.Pose[Bone].BlendWith(Action.Pose[Bone], Weight * (Upper[Bone.GetInt()] ? 1.f : Legs));
241			}
242		}
243	};
244	} // namespace
245	
246	FAnimInstanceProxy* UJamPoseInstance::CreateAnimInstanceProxy()
247	{
248		return new FJamPoseProxy(this);
249	}
