25	FJamBackdropPlace JamArenaRules::PlaceBackdrop(
26		const FVector& Eye, const FVector& LookAt, float Fov, float Aspect, float PictureAspect, double Distance)
27	{
28		// The engine keeps the vertical field of view; Fov is the horizontal one on a 16:9 screen.
29		constexpr double ReferenceAspect = 16.0 / 9.0;
30		const double HalfTanY = FMath::Tan(FMath::DegreesToRadians(0.5 * Fov)) / ReferenceAspect;
31		const double HalfHeight = Distance * HalfTanY;
32		const double HalfWidth = HalfHeight * FMath::Max(Aspect, 0.01f);
33		const double Ground = FVector2D(LookAt - Eye).Size();
34		const double ViewCentreZ = Eye.Z + (Ground > 0.0 ? Distance * (LookAt.Z - Eye.Z) / Ground : 0.0);
35		// Cover: the full height, and wider still when the screen is wider than the picture; the overflow goes below. A
36		// sliver of overscan, so no hairline of the sky behind shows at an edge.
37		constexpr double Overscan = 1.01;
38		const double Picture = FMath::Max(PictureAspect, 0.01f);
39		FJamBackdropPlace Place;
40		Place.Height = Overscan * FMath::Max(2.0 * HalfHeight, 2.0 * HalfWidth / Picture);
41		Place.Width = Place.Height * Picture;
42		Place.CentreZ = ViewCentreZ + HalfHeight + 0.5 * (Overscan - 1.0) * Place.Height - 0.5 * Place.Height;
43		return Place;
44	}
