65		float Width = 0.f;
66		float RowHeight = 0.f;
67		for (const FString& Row : Rows)
68		{
69			float RowWidth = 0.f;
70			GetTextSize(Row, RowWidth, RowHeight, Font, BalloonScale);
71			Width = FMath::Max(Width, RowWidth);
72		}
73		const float BoxW = Width + 2.f * BalloonPadding;
74		const float BoxH = Rows.Num() * RowHeight + 2.f * BalloonPadding;
75		const float X = At.X * Canvas->ClipX - 0.5f * BoxW;
76		const float Y = At.Y * Canvas->ClipY - 0.5f * BoxH;
77		// The tail first, so the box's border closes over its root.
78		const FVector2D Root(X + 0.5f * BoxW, Y + BoxH);
79		FCanvasTriangleItem Tail(Root + FVector2D(-0.5f * BalloonTail - BalloonBorder, -BalloonBorder),
80			Root + FVector2D(0.5f * BalloonTail + BalloonBorder, -BalloonBorder), Root + FVector2D(0.f, BalloonTail + BalloonBorder),
81			GWhiteTexture);
82		Tail.SetColor(Ink);
83		Canvas->DrawItem(Tail);
84		FCanvasTriangleItem Fill(Root + FVector2D(-0.5f * BalloonTail, -BalloonBorder), Root + FVector2D(0.5f * BalloonTail, -BalloonBorder),
85			Root + FVector2D(0.f, BalloonTail), GWhiteTexture);
86		Fill.SetColor(Paper);
87		DrawRect(Ink, X - BalloonBorder, Y - BalloonBorder, BoxW + 2.f * BalloonBorder, BoxH + 2.f * BalloonBorder);
88		DrawRect(Paper, X, Y, BoxW, BoxH);
89		Canvas->DrawItem(Fill);
90		for (int32 Index = 0; Index < Rows.Num(); ++Index)
91		{
92			float RowWidth = 0.f;
93			float Unused = 0.f;
94			GetTextSize(Rows[Index], RowWidth, Unused, Font, BalloonScale);
95			DrawText(Rows[Index], Ink, X + 0.5f * (BoxW - RowWidth), Y + BalloonPadding + Index * RowHeight, Font, BalloonScale);
96		}
97	}
