99	void AJamHUD::DrawComicWords(int32 Index)
100	{
101		UFont* Font = GEngine->GetMediumFont();
102		const float W = Canvas->ClipX;
103		const float H = Canvas->ClipY;
104		const FString Caption = JamTexts::ComicCaptions[Index];
105		if (!Caption.IsEmpty())
106		{
107			float Width = 0.f;
108			float Height = 0.f;
109			GetTextSize(Caption, Width, Height, Font, CaptionScale);
110			const float X = CaptionLeft * W;
111			const float Y = CaptionTop * H;
112			DrawRect(Ink, X - BalloonBorder, Y - BalloonBorder, Width + 2.f * (CaptionPadding + BalloonBorder),
113				Height + 2.f * (CaptionPadding + BalloonBorder));
114			DrawRect(CaptionYellow, X, Y, Width + 2.f * CaptionPadding, Height + 2.f * CaptionPadding);
115			DrawText(Caption, Ink, X + CaptionPadding, Y + CaptionPadding, Font, CaptionScale);
116		}
117		const FString Sound = JamTexts::ComicSounds[Index];
118		if (!Sound.IsEmpty())
119		{
120			const float X = SoundAt[Index].X * W;
121			const float Y = SoundAt[Index].Y * H;
122			for (const FVector2D Offset : { FVector2D(-1, -1), FVector2D(1, -1), FVector2D(-1, 1), FVector2D(1, 1) })
123			{
124				DrawText(Sound, Ink, X + SoundOutline * Offset.X, Y + SoundOutline * Offset.Y, Font, SoundScale);
125			}
126			DrawText(Sound, SoundGold, X, Y, Font, SoundScale);
127		}
128	}
