130	void AJamHUD::DrawComic()
131	{
132		const float W = Canvas->ClipX;
133		const float H = Canvas->ClipY;
134		DrawRect(Ink, 0.f, 0.f, W, H);
135		if (ComicPictures.Num() != JamComicRules::PanelCount)
136		{
137			LoadComic();
138		}
139		const float Slide = JamComicRules::SlideIn(ComicPanelAge);
140		if (Slide < 1.f && ComicPanel > 0)
141		{
142			// The last panel stays where its move ended while the new one slides over it.
143			DrawComicPanel(ComicPanel - 1, JamComicRules::PanelOf(ComicPanel - 1).Seconds, 0.f);
144		}
145		DrawComicPanel(ComicPanel, ComicPanelAge, (1.f - Slide) * W);
146		if (Slide < 1.f)
147		{
148			return;
149		}
150		DrawComicWords(ComicPanel);
151		if (bComicBalloon)
152		{
153			DrawBalloon(JamTexts::VoiceLine(static_cast<int32>(ComicLine)), JamComicRules::BalloonAt(ComicLine));
154		}
155		float Width = 0.f;
156		float Height = 0.f;
157		UFont* Font = GEngine->GetMediumFont();
158		GetTextSize(JamTexts::ComicSkip, Width, Height, Font, SkipScale);
159		DrawText(JamTexts::ComicSkip, SkipColor, W - Width - CaptionPadding, H - Height - CaptionPadding, Font, SkipScale);
160	}
