77	const FLinearColor BossNameColor(1.0f, 0.78f, 0.25f);
78	const FLinearColor BossBarColor(0.9f, 0.15f, 0.15f);
79	const FLinearColor HeroBarColor(0.2f, 0.9f, 1.0f);
80	// T-053: health just lost stays white for a moment; health just gained shows light green before the bar fills to it.
81	const FLinearColor ChunkColor(1.f, 1.f, 1.f, 0.9f);
82	const FLinearColor PreviewColor(0.55f, 1.f, 0.6f, 0.85f);
83	const FLinearColor StolenColor(1.0f, 0.35f, 0.3f);
84	const FLinearColor EndingBandColor(0.f, 0.f, 0.f, 0.75f);
85	const FLinearColor WinColor(1.0f, 0.3f, 0.85f);
86	const FLinearColor LockedColor(0.45f, 0.45f, 0.45f);
87	
88	/** A button of the hero, the mechanic that lives on it and the name of the key. */
89	struct FLoadoutRow
90	{
91		EJamButton Button;
92		EJamMechanic Mechanic;
93		const TCHAR* Key;
94	};
95	
96	const FLoadoutRow LoadoutRows[] = {
97		{ EJamButton::Primary, EJamMechanic::Katana, TEXT("LMB") },
98		{ EJamButton::Secondary, EJamMechanic::Shuriken, TEXT("RMB") },
