141	void AJamHUD::DrawHealthBar(float X, float Y, float Width, float Height, const FJamBarState& Bar, const FLinearColor& Color, float Alpha)
142	{
143		if (!bBars || Alpha <= 0.f)
144		{
145			return;
146		}
147		const FLinearColor Fade(1.f, 1.f, 1.f, Alpha);
148		DrawRect(BarBackColor * Fade, X, Y, Width, Height);
