154	void AJamHUD::DrawLoadout(const FJamLedger& Ledger, float Meter, float X, float Bottom)
155	{
156		UFont* Font = GEngine->GetMediumFont();
157		const int32 RowCount = UE_ARRAY_COUNT(LoadoutRows);
158		for (int32 Index = 0; Index < RowCount; ++Index)
159		{
160			const FLoadoutRow& Row = LoadoutRows[Index];
161			const float Y = Bottom - (RowCount - Index) * LoadoutRowHeight;
162			const TCHAR* Name = JamLoadoutRules::Name(Row.Mechanic);
163			if (Ledger.Has(EJamSide::Hero, Row.Mechanic))
164			{
165				DrawText(Row.Key, HeroBarColor, X, Y, Font, LoadoutScale);
166				const FString Label = Row.Mechanic == EJamMechanic::Ultimate ? JamTexts::UltimateMeter(Name, Meter) : FString(Name);
167				DrawText(Label, HeroBarColor, X + LoadoutNameOffset, Y, Font, LoadoutScale);
168				continue;
169			}
170			const bool bBall = JamLoadoutRules::ActionFor(Row.Button, EJamSide::Hero, Ledger) == EJamAction::Ball;
171			DrawText(Row.Key, StolenColor, X, Y, Font, LoadoutScale);
172			DrawText(JamTexts::LoadoutStolen(bBall, Name), StolenColor, X + LoadoutNameOffset, Y, Font, LoadoutScale);
173		}
174	}
