195	void AJamHUD::DrawStealCard(const FJamFight& Fight)
196	{
197		const FJamStealState& Steal = Fight.Steal;
198		const float W = Canvas->ClipX;
199		const float H = Canvas->ClipY;
200		const float Top = CardTop * H;
201		UFont* Font = GEngine->GetMediumFont();
202		DrawRect(EndingBandColor, 0.f, Top, W, CardHeight * H);
203		DrawCentered(Steal.bTakesAll ? JamTexts::StealAllTitle : JamTexts::StealTitle, Top + 0.02f * H, CardTitleScale, StolenColor);
204		DrawCentered(Steal.bTakesAll ? JamTexts::StealAllAsk : JamTexts::StealAsk, Top + CardAskRow * H, HudTextScale, FLinearColor::White);
205	
206		// The options stay dim until the card takes an answer: a key held from the fight must not look like a choice.
207		const FLinearColor Color = Fight.Tick >= Steal.OpenTick ? HeroBarColor : LockedColor;
208		const float OptionWidth = CardOptionWidth * W;
209		const float Gap = CardOptionGap * W;
210		const int32 Count = Steal.Offer.Num();
211		const float Left = 0.5f * (W - Count * OptionWidth - (Count - 1) * Gap);
212		const float OptionTop = Top + CardOptionRow * H;
213		for (int32 Index = 0; Index < Count; ++Index)
214		{
215			const float X = Left + Index * (OptionWidth + Gap);
216			DrawRect(BarBackColor, X, OptionTop, OptionWidth, CardOptionHeight * H);
217			DrawRect(Color, X, OptionTop, OptionWidth, CardOptionEdge);
218			DrawText(OptionKey(Steal, Index), Color, X + CardPadding, OptionTop + CardPadding, Font, HudTextScale);
219			DrawText(JamLoadoutRules::Name(Steal.Offer[Index]), Color, X + CardPadding, OptionTop + CardNameRow * H, Font, CardNameScale);
220		}
221	
222		const float TimerWidth = 2.f * OptionWidth + Gap;
223		const float TimeLeft = JamStealRules::TimeLeft(Steal, static_cast<float>(Fight.Tick));
224		DrawBar(0.5f * (W - TimerWidth), Top + CardTimerRow * H, TimerWidth, CardTimerHeight * H, TimeLeft, StolenColor);
225		DrawCentered(
226			Steal.bTakesAll ? JamTexts::StealAllKey : JamTexts::StealDefault, Top + CardHintRow * H, HudTextScale, FLinearColor::White);
227	}
