234		DrawCentered(JamTexts::StunTitle, (StunBandTop + 0.015f) * H, CardTitleScale, WinColor);
235		DrawCentered(JamTexts::StunAsk, (StunBandTop + 0.085f) * H, HudTextScale, FLinearColor::White);
