254		DrawCentered(JamTexts::IntroTitle, (IntroBandTop + 0.06f) * H, EndingTitleScale, WinColor * FLinearColor(1.f, 1.f, 1.f, A));
255		DrawCentered(JamTexts::IntroLine, (IntroBandTop + 0.17f) * H, HudTextScale, FLinearColor(1.f, 1.f, 1.f, A));
