259	void AJamHUD::DrawPhase(const FJamFight& Fight)
260	{
261		switch (Fight.Phase)
262		{
263			case EJamPhase::Steal:
264				DrawStealCard(Fight);
265				break;
266			case EJamPhase::Stunned:
267				DrawStun();
268				break;
269			case EJamPhase::HeroDead:
270			case EJamPhase::Won:
271				DrawEnding(Fight.Phase == EJamPhase::Won);
272				break;
273			default:
274				break;
275		}
276	}
