278	void AJamHUD::BeginPlay()
279	{
280		Super::BeginPlay();
281		BarSettings = JamConfig::Load<FJamBarSettings>(JamBarRules::Section);
282	}
283	
284	void AJamHUD::DrawHUD()
285	{
286		Super::DrawHUD();
287		if ((bMenu || bComic) && Canvas)
288		{
289			bComic ? DrawComic() : DrawMenu();
290			return;
291		}
292		const UJamFightSubsystem* Host = GetWorld()->GetSubsystem<UJamFightSubsystem>();
293		if (!Canvas || !Host)
294		{
295			return;
296		}
297		const float W = Canvas->ClipX;
298		const float H = Canvas->ClipY;
299		UFont* Font = GEngine->GetMediumFont();
300		const FJamFight& Fight = Host->GetFight();
301		const FJamFighter& Hero = Fight.Fighters[EJamSide::Hero];
302		const FJamFighter& Boss = Fight.Fighters[EJamSide::Boss];
303		// The crack's old picture goes under the HUD: the bars and the texts stay readable over it.
304		DrawCrack();
305		const float Delta = GetWorld()->GetDeltaSeconds();
306		JamBarRules::Track(BossBar, Boss.Health / FMath::Max(1.f, Boss.MaxHealth), Delta, BarSettings);
307		JamBarRules::Track(HeroBar, Hero.Health / FMath::Max(1.f, Hero.MaxHealth), Delta, BarSettings);
308	
309		DrawBossBar(Boss);
310	
311		DrawHealthBar(HudMargin * W, HeroBarBottom * H, HeroBarWidth * W, BarHeight * H, HeroBar, HeroBarColor);
312		const float HeroTextY = HeroBarBottom * H - 28.f;
313		DrawText(JamTexts::HeroHealth(FMath::CeilToInt32(Hero.Health)), FLinearColor::White, HudMargin * W, HeroTextY, Font, HudTextScale);
314		DrawLoadout(Fight.Ledger, Hero.Ultimate.Meter, HudMargin * W, HeroTextY - 6.f);
315	
316	#if !UE_BUILD_SHIPPING
317		DrawHint(JamTexts::DebugHint, 0);
318	#endif
319		DrawUltimate(Fight, HudMargin * W, HeroBarWidth * W);
320		// One call over the head at a time: the shot about to land comes first.
321		if (bParryPrompt)
322		{
323			DrawOverHero(Hero, JamTexts::ParryPrompt, HeroBarColor);
324		}
325		else if (UltimateCall == EJamUltimateCall::BannerAndPrompt)
326		{
327			DrawOverHero(Hero, JamTexts::UltimatePrompt, WinColor);
328		}
329		if (Fight.Phase == EJamPhase::Fight || Fight.Phase == EJamPhase::Stunned)
330		{
331			DrawBossMarker(Boss);
332		}
333		DrawPhase(Fight);
334		if (IntroAlpha > 0.f)
335		{
336			DrawIntro();
337		}
338		if (bSubtitle)
339		{
340			DrawSubtitle();
341		}
342	}
