344	void AJamHUD::DrawSubtitle()
345	{
346		UFont* Font = GEngine->GetMediumFont();
347		const FString Name = FString(SubtitleSpeaker == EJamSide::Hero ? JamTexts::SpeakerHero : JamTexts::SpeakerBoss) + TEXT("  ");
348		const FString Words = JamTexts::VoiceLine(SubtitleLine);
349		float NameWidth = 0.f;
350		float WordsWidth = 0.f;
351		float Height = 0.f;
352		GetTextSize(Name, NameWidth, Height, Font, SubtitleScale);
353		GetTextSize(Words, WordsWidth, Height, Font, SubtitleScale);
354		// Over the intro's band during the show, under the steal card in the fight.
355		const float Y = (IntroAlpha > 0.f ? SubtitleIntroTop : SubtitleTop) * Canvas->ClipY;
356		const float X = 0.5f * (Canvas->ClipX - NameWidth - WordsWidth);
357		DrawRect(BarBackColor, X - SubtitlePadding, Y - 0.5f * SubtitlePadding, NameWidth + WordsWidth + 2.f * SubtitlePadding,
358			Height + SubtitlePadding);
359		DrawText(Name, SubtitleSpeaker == EJamSide::Hero ? HeroBarColor : BossNameColor, X, Y, Font, SubtitleScale);
360		DrawText(Words, FLinearColor::White, X + NameWidth, Y, Font, SubtitleScale);
361	}
362	
363	void AJamHUD::DrawBossMarker(const FJamFighter& Boss)
364	{
365		const FVector Screen = Project(FVector(Boss.Pos.X, Boss.Pos.Y, BossMarkerHeight));
366		// At the top the arrow stays under his health bar and its numbers, with a clear gap (T-047).
367		float TextWidth = 0.f;
368		float TextHeight = 0.f;
369		GetTextSize(TEXT("0"), TextWidth, TextHeight, GEngine->GetMediumFont(), HudTextScale);
370		const float BarTextBottom = (BossBarTop + BarHeight) * Canvas->ClipY + BossTextGap + TextHeight;
371		const float TopInset = BarTextBottom + BossMarkerBarGap + 0.5f * BossMarkerSize;
372		const FJamEdgeMarker Marker =
373			JamMarkerRules::EdgeMarker(FVector2D(Screen.X, Screen.Y), FVector2D(Canvas->ClipX, Canvas->ClipY), BossMarkerMargin, TopInset);
374		if (!Marker.bShow)
375		{
376			return;
377		}
378		// A wedge pointing at him, its tip on the marker: the colour of his health bar, so it reads as "the boss".
379		const FVector2D Ahead = FVector2D(1.0, 0.0).GetRotated(Marker.Angle);
380		const FVector2D Across(-Ahead.Y, Ahead.X);
381		const FVector2D Tip = Marker.Pos + Ahead * (0.5 * BossMarkerSize);
382		const FVector2D Back = Marker.Pos - Ahead * (0.5 * BossMarkerSize);
383		FCanvasTriangleItem Wedge(Tip, Back + Across * (0.5 * BossMarkerSize), Back - Across * (0.5 * BossMarkerSize), GWhiteTexture);
384		Wedge.SetColor(BossBarColor);
385		Canvas->DrawItem(Wedge);
386	}
387	
388	void AJamHUD::DrawUltimate(const FJamFight& Fight, float X, float Width)
389	{
390		const float H = Canvas->ClipY;
391		const FJamFighter& Hero = Fight.Fighters[EJamSide::Hero];
392		if (Fight.Ledger.Has(EJamSide::Hero, EJamMechanic::Ultimate))
393		{
394			const float Top = (HeroBarBottom + BarHeight) * H + UltimateBarGap;
395			DrawBar(X, Top, Width, UltimateBarHeight * H, Hero.Ultimate.Meter, WinColor);
396			if (bBars)
397			{
398				DrawText(JamTexts::UltimateBarLabel, WinColor, X + Width + UltimateBarGap, Top - 0.25f * UltimateBarHeight * H,
399					GEngine->GetMediumFont(), 1.f);
400			}
401		}
402		if (UltimateCall == EJamUltimateCall::None)
403		{
404			return;
405		}
406		// The banner breathes, so the eye catches it at the edge of the fight.
407		const float Pulse = 0.5f + 0.5f * FMath::Sin(UE_TWO_PI * UltimatePulseHz * GetWorld()->GetRealTimeSeconds());
408		const FLinearColor Color = FMath::Lerp(WinColor, FLinearColor::White, Pulse * UltimatePulseWhite);
409		UFont* Font = GEngine->GetMediumFont();
410		float TextWidth = 0.f;
411		float TextHeight = 0.f;
412		GetTextSize(JamTexts::UltimateBanner, TextWidth, TextHeight, Font, UltimateBannerScale);
413		const float Y = UltimateBannerTop * H;
414		DrawRect(BarBackColor, 0.5f * (Canvas->ClipX - TextWidth) - CardPadding, Y, TextWidth + 2.f * CardPadding, TextHeight);
415		DrawRect(Color, 0.5f * (Canvas->ClipX - TextWidth) - CardPadding, Y + TextHeight, TextWidth + 2.f * CardPadding, CardOptionEdge);
416		DrawCentered(JamTexts::UltimateBanner, Y, UltimateBannerScale, Color);
417	}
418	
419	void AJamHUD::DrawOverHero(const FJamFighter& Hero, const FString& Text, const FLinearColor& Color)
420	{
421		// Above the ronin's head, so the call is read where the eyes already are.
422		const FVector Screen = Project(FVector(Hero.Pos.X, Hero.Pos.Y, OverHeroHeight));
423		UFont* Font = GEngine->GetMediumFont();
424		float Width = 0.f;
425		float Height = 0.f;
426		GetTextSize(Text, Width, Height, Font, OverHeroScale);
427		DrawRect(BarBackColor, Screen.X - 0.5f * Width - CardPadding * 0.5f, Screen.Y - Height, Width + CardPadding, Height);
428		DrawText(Text, Color, Screen.X - 0.5f * Width, Screen.Y - Height, Font, OverHeroScale);
429	}
