Source/JamGame/Private/Game/JamGameMode.cpp:105:#if !UE_BUILD_SHIPPING
8:/**
9: * The demo run: the bot plays the hero on the top-down camera. It exists so that a clip can be recorded and the game
10: * looked at with nobody at the PC. Switched on from the command line:
11: *
12: *   -JamDemo               the bot plays
13: *   -JamCapture=<folder>   every frame is saved there as a PNG, at a fixed 30 frames per second
14: *   -JamDemoSeconds=<n>    the game quits after n seconds
15: *   -JamDemoSteal=<names>  the bot gives these away on the cards, the first one on offer (PARRY,ULTIMATE)
16: */
19:	/** Reads the command line. */
22:	bool IsOn() const { return bOn; }
24:	/** The run starts in the fight, without the intro (-JamDemoNoIntro). */
25:	bool SkipsIntro() const { return bOn && (bNoIntro || bGallery || bStrides); }
27:	/** The pose gallery (-JamPoseGallery): the fight stands, the hero holds one pose after another for a close camera. */
28:	bool IsGallery() const { return bOn && bGallery; }
30:	/** The stride gallery (-JamStrideGallery): the hero faces east and runs each way in turn, the fight stands (T-078). */
31:	bool IsStrideGallery() const { return bOn && bStrides; }
33:	/** -JamDemoClose: the camera follows the hero close and low, so his feet show (T-078). */
34:	bool IsClose() const { return bOn && bClose; }
