#include "Audio/JamSoundRules.h"
#include "CoreMinimal.h"
#include "GameFramework/Actor.h"

#include "JamSounds.generated.h"

class USoundWave;

/**
 * The sound effects: plays the cues JamSoundRules picks from a frame's events. Every sound is heard at the same
 * loudness wherever it happens: the camera is above the hero and the arena is small.
 *
 * The sounds are /Game/Audio/Sfx/<cue name>: stubs from Tools/Audio/make_stub_sfx.py until Kirill's files replace
 * them under the same names.
 */
UCLASS()
class JAMGAME_API AJamSounds : public AActor
{
	GENERATED_BODY()

public:
	AJamSounds();

	/** Plays the cues of a frame's events, Fight being the state after them, ducked under a voice line (T-085). */
	void Play(const TArray<FJamEvent>& Events, const FJamFight& Fight, bool bVoiceSpeaking);

private:
	/** Fades Playing out After seconds in (T-085). */
	void CutShort(class UAudioComponent& Playing, float After);

public:
private:
	/** One sound per cue, in the order of EJamCue; empty where an asset is missing. */
	UPROPERTY()
	TArray<TObjectPtr<USoundWave>> Sounds;
};
#include "Audio/JamSounds.h"

#include "Components/AudioComponent.h"
#include "Kismet/GameplayStatics.h"
#include "TimerManager.h"
#include "Sound/SoundWave.h"
#include "UObject/ConstructorHelpers.h"

AJamSounds::AJamSounds()
{
	PrimaryActorTick.bCanEverTick = false;
	SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));
	for (int32 Index = 0; Index < JamSoundRules::CueCount; ++Index)
	{
		const TCHAR* Name = JamSoundRules::NameOf(static_cast<EJamCue>(Index));
		ConstructorHelpers::FObjectFinder<USoundWave> Finder(*FString::Printf(TEXT("/Game/Audio/Sfx/%s.%s"), Name, Name));
		Sounds.Add(Finder.Object);
	}
}

void AJamSounds::Play(const TArray<FJamEvent>& Events, const FJamFight& Fight, bool bVoiceSpeaking)
{
	for (const EJamCue Cue : JamSoundRules::CuesOf(Events, Fight))
	{
		USoundWave* Sound = Sounds[static_cast<int32>(Cue)];
		if (!Sound)
		{
			continue;
		}
		const FJamMix Mix = JamSoundRules::MixOf(Cue, bVoiceSpeaking);
		UAudioComponent* Playing = UGameplayStatics::SpawnSound2D(this, Sound, Mix.Volume);
		if (Playing && Mix.CutAfter > 0.f)
		{
			CutShort(*Playing, Mix.CutAfter);
		}
	}
}

void AJamSounds::CutShort(UAudioComponent& Playing, float After)
{
	// A quick fade, not a click.
	TWeakObjectPtr<UAudioComponent> Weak(&Playing);
	FTimerHandle Cut;
	GetWorldTimerManager().SetTimer(
		Cut,
		[Weak]()
		{
			if (Weak.IsValid())
			{
				Weak->FadeOut(0.1f, 0.f);
			}
		},
		After, false);
}
