{
	IntroBoss,
	IntroHero,
	Cut1Boss,
	Cut1Hero,
	Cut2Boss,
	Cut2Hero,
	Cut3Boss,
	Cut3Hero,
	Cut4Boss,
	Cut4Hero,
	StunBoss,
	FinalHero,
	FinalBoss,
	Bark1,
	Bark2,
	Bark3,
	Bark4,
	StealShuriken,
	StealParry,
	StealDashBoss,
	StealDashHero,
	StealUltimate,
	ComicBoss1,
	ComicHero1,
	ComicBoss2,
	ComicHero2
