void AJamFighterView::SetLayers(const FJamLayers& InLayers)
{
	if (InLayers == Shown)
	{
		return;
	}
	Shown = InLayers;
	// Three looks of the hero (T-067): the 3D art, the shape ronin of before the models, the bean.
	Figure->SetVisibility(Shown.bModel && Shown.bArt, true);
	Ronin->SetVisibility(Shown.bModel && !Shown.bArt, true);
	Body->SetVisibility(!Shown.bModel);
	Visor->SetVisibility(!Shown.bModel);
	if (Skin)
	{
		Skin->SetScalarParameterValue(TEXT("NeonGlow"), Shown.bEffects ? NeonGlow : 0.f);
	}
	Repaint();
}

void AJamFighterView::Repaint()
{
	const bool bGrid = !Shown.bMaterials && !bFlashing;
	const FLinearColor Flashed = bFlashing ? FMath::Lerp(BaseColor, FLinearColor::White, FlashWeight) : BaseColor;
	if (!Shown.bModel)
	{
		JamShapes::Look(*Body, Flashed, bGrid);
		JamShapes::Look(*Visor, VisorColor, bGrid);
		return;
	}
	if (!Shown.bArt)
	{
		PaintRonin(bGrid);
		return;
	}
	UMaterialInterface* Grid = JamShapes::Grid();
	Figure->SetMaterial(0, bGrid ? Grid : Skin.Get());
	if (Katana->GetStaticMesh())
	{
	}
}

void AJamFighterView::UpdateGhosts(float Time)
{
	if (GhostSkins.IsEmpty())
	{
		return;
	}
	// The afterimages are an effect of a moving body: gone with the effects, the animation or the model.
	const bool bShow = Shown.bArt && Shown.bEffects && Shown.bAnimation && Shown.bModel;
	const int32 Due = bShow && GhostAt >= 0.f ? JamPoseRules::GhostsBy(Time - GhostAt, Ghosts.Num(), GhostGap) : 0;
	for (; GhostsLeft < Due; ++GhostsLeft)
	{
		UPoseableMeshComponent& Ghost = *Ghosts[GhostsLeft];
		Ghost.SetWorldTransform(Figure->GetComponentTransform());
		Ghost.CopyPoseFromSkeletalComponent(Figure);
		GhostBornAt[GhostsLeft] = Time;
	}
	for (int32 Index = 0; Index < Ghosts.Num(); ++Index)
	{
	if (StepSpeed > StrideAngleFromSpeed)
	{
		StrideAngle = JamPoseRules::MoveAngle(
			Step, FVector2D(FMath::Cos(FMath::DegreesToRadians(ShownYaw)), FMath::Sin(FMath::DegreesToRadians(ShownYaw))));
	}
	const float YawRate = Dt > 0.f ? static_cast<float>(FMath::FindDeltaAngleDegrees(LastYaw, ShownYaw)) / Dt : 0.f;
	Animate(Moving, StrideAngle, YawRate, Time);
	if (Shown.bModel && !Shown.bArt)
	{
		AnimateRonin(Moving, Time);
	}
	UpdateGhosts(Time);
	const bool bFlashNow = Time < FlashUntil;
	if (bFlashNow != bFlashing)
	{
		bFlashing = bFlashNow;
	}
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamLayersArtTest, "Jam.Layers.TheArtGoesWithTheFirstCut", JamTest::Flags)

bool FJamLayersArtTest::RunTest(const FString& Parameters)
{
	// T-067: three tiers. The full art (the 3D hero, the rich effects) goes first; the plain effects stay one cut longer.
	FJamLayerSettings S = OneLayerPerCut();
	S.ArtLostAt = 1;
	S.EffectsLostAt = 2;
	TestTrue(TEXT("the art is there before the first cut"), JamLayerRules::For(0, EJamPhase::Fight, S).bArt);
	const FJamLayers First = JamLayerRules::For(1, EJamPhase::Fight, S);
	TestFalse(TEXT("the first cut takes the art"), First.bArt);
	TestTrue(TEXT("the plain effects stay"), First.bEffects);
	TestTrue(TEXT("the model stays: the shape ronin"), First.bModel);
	TestFalse(TEXT("the second cut takes the plain effects"), JamLayerRules::For(2, EJamPhase::Fight, S).bEffects);
	TestTrue(TEXT("the stun gives the art back"), JamLayerRules::For(3, EJamPhase::Stunned, S).bArt);
	TestFalse(TEXT("a change of the art alone is a change"), First == JamLayerRules::For(0, EJamPhase::Fight, S));
	return true;
}

