#include "CoreMinimal.h"
#include "Misc/AutomationTest.h"

#if WITH_DEV_AUTOMATION_TESTS

#include "Tests/JamTestHelpers.h"
#include "UI/JamComicRules.h"
#include "UI/JamTexts.h"

/**
 * T-093: the opening comic after NEW GAME: five panels, the camera moving over each, the voiced lines in balloons.
 * A bug looks in game like "a panel cuts the line short", "the screen shows past the picture's edge", "the picture is
 * squashed", "a balloon runs off the screen" or "the skip key of the menu skips the comic too".
 *
 * Run: Automation RunTests Jam.Comic
 */
namespace
{
constexpr float WideScreen = 16.f / 9.f;
} // namespace

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamComicStoryTest, "Jam.Comic.FivePanelsTellTheCallInOrder", JamTest::Flags)
}

FJamIntent AJamPlayerController::ReadIntent(const AJamCameraRig& Rig, const FJamFighter& Hero, int32 CardOptions)
{
	FVector Origin;
	FVector Direction;
	if (DeprojectMousePositionToWorld(Origin, Direction) && JamAimRules::FromRay(Origin, Direction, 0.f, Hero.Pos, Aim))
	{
		AimCamera = PlayerCameraManager ? PlayerCameraManager->GetCameraLocation() : Rig.GetActorLocation();
	}

	FJamIntent Intent;
	const FVector2D Keys((IsInputKeyDown(EKeys::D) ? 1.0 : 0.0) - (IsInputKeyDown(EKeys::A) ? 1.0 : 0.0),
		(IsInputKeyDown(EKeys::W) ? 1.0 : 0.0) - (IsInputKeyDown(EKeys::S) ? 1.0 : 0.0));
	Intent.Move = JamMoveRules::WorldMove(Keys, Rig.GetMoveBasisYaw());
	Intent.Aim = Aim;
	Intent.bPrimary = IsInputKeyDown(EKeys::LeftMouseButton);
	Intent.bSecondary = IsInputKeyDown(EKeys::RightMouseButton);
	Intent.bDash = IsInputKeyDown(EKeys::SpaceBar);
	// No parry key (T-044): the strike parries a shot about to land (JamParryRules::ShotInReach).
	Intent.bUltimate = IsInputKeyDown(EKeys::E);
	// The steal card is answered with the keys under the left hand: a press, not a hold, so walking left is no answer.
	if (WasInputKeyJustPressed(EKeys::A) || WasInputKeyJustPressed(EKeys::Left))
	{
		Intent.Choice = 0;
	}
	else if (WasInputKeyJustPressed(EKeys::D) || WasInputKeyJustPressed(EKeys::Right))
	{
		Intent.Choice = 1;
	}
	float X = 0.f;
	float Y = 0.f;
	int32 Width = 0;
	int32 Height = 0;
	GetViewportSize(Width, Height);
	if (CardOptions > 0 && WasInputKeyJustPressed(EKeys::LeftMouseButton) && GetMousePosition(X, Y))
	{
		const int32 Clicked = JamCardRules::OptionAt(FVector2D(X, Y), CardOptions, FVector2D(Width, Height));
		if (Clicked != INDEX_NONE)
		{
			Intent.Choice = Clicked;
		}
	}
	return Intent;
}
