bool FJamHowToLayoutTest::RunTest(const FString& Parameters)
{
	const TArray<FJamHowToCallout> Callouts = JamHowToRules::Callouts(4);
	const TArray<FVector2D> Sizes = SizesOf(Callouts);
	for (const FVector2D Screen : { FVector2D(1920.0, 1080.0), FVector2D(1280.0, 720.0), FVector2D(2560.0, 1080.0) })
	{
		const FJamHowToLayout L = JamHowToRules::Layout(Screen, Callouts, Sizes);
		const FBox2D Frame(FVector2D::ZeroVector, Screen);
		if (!TestEqual(TEXT("a box per label"), L.Labels.Num(), Callouts.Num()) ||
			!TestEqual(TEXT("lines per label"), L.Lines.Num(), Callouts.Num()))
		{
			return false;
		}
		TestTrue(TEXT("the keyboard is on the screen"), Frame.IsInside(L.Board));
		TestTrue(
			TEXT("the whole board, not only our keys"), L.Keys.FilterByPredicate([](const FJamHowToKey& K) { return !K.bLit; }).Num() > 20);
		for (int32 Index = 0; Index < Callouts.Num(); ++Index)
		{
			const FBox2D& Box = L.Labels[Index];
			TestTrue(*FString::Printf(TEXT("'%s' on the screen"), *Callouts[Index].Caps), Frame.IsInside(Box));
			TestFalse(TEXT("off the keyboard"), Box.Intersect(L.Board));
			TestFalse(TEXT("off the mouse"), Box.Intersect(L.Mouse));
			for (int32 Other = Index + 1; Other < Callouts.Num(); ++Other)
			{
				TestFalse(*FString::Printf(TEXT("'%s' clear of '%s'"), *Callouts[Index].Caps, *Callouts[Other].Caps),
					Box.Intersect(L.Labels[Other]));
			}
			TestEqual(TEXT("a line from each of its keys"), L.Lines[Index].Num(), Callouts[Index].Keys.Num());
			for (int32 KeyIndex = 0; KeyIndex < Callouts[Index].Keys.Num() && KeyIndex < L.Lines[Index].Num(); ++KeyIndex)
			{
				const FJamHowToKey* Drawn =
					L.Keys.FindByPredicate([&](const FJamHowToKey& K) { return K.Key == Callouts[Index].Keys[KeyIndex]; });
				if (TestNotNull(TEXT("its key is drawn"), Drawn))
				{
					TestTrue(TEXT("and lit"), Drawn->bLit);
					TestTrue(TEXT("the line starts at the key"), Drawn->Box.ExpandBy(1.0).IsInside(L.Lines[Index][KeyIndex].Key));
					TestTrue(TEXT("and ends at the label"), Box.ExpandBy(1.0).IsInside(L.Lines[Index][KeyIndex].Value));
				}
			}
		}
	}
	return true;
}

#endif // WITH_DEV_AUTOMATION_TESTS

