IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamIntroThemeTest, "Jam.Intro.TheAmbientGivesWayToTheTheme", JamTest::Flags)

bool FJamIntroThemeTest::RunTest(const FString& Parameters)
{
	// T-094: the comic played under the full fight music; it gets a soft ambient until the Publisher's intro line ends.
	TestTrue(TEXT("the menu has the theme"), JamIntroRules::IsThemeUp(true, false, false, false));
	TestFalse(TEXT("the comic the ambient"), JamIntroRules::IsThemeUp(false, true, false, false));
	TestFalse(TEXT("so does the intro while he talks"), JamIntroRules::IsThemeUp(false, false, false, false));
	TestTrue(TEXT("the theme comes once his line is over"), JamIntroRules::IsThemeUp(false, false, false, true));
	TestTrue(TEXT("or at once on a skip"), JamIntroRules::IsThemeUp(false, false, true, false));
	float Theme = 0.f;
	Theme = JamIntroRules::Crossfade(Theme, true, 1.f, 2.f);
