	if (Scale >= 1.0 && Size.X < Desktop.X && Size.Y < Desktop.Y)
	{
		return Size;
	}
	return FIntPoint(FMath::FloorToInt32(Size.X * Scale), FMath::FloorToInt32(Size.Y * Scale));
}
