#pragma once

#include "CoreMinimal.h"

/**
 * Health arithmetic of a fighter.
 * Tests: Jam.Health.*
 */
namespace JamHealthRules
{
/** Health after a hit: never below zero, untouched while invulnerable, and damage never heals. */
JAMGAME_API float Apply(float Health, float Damage, bool bInvulnerable);
} // namespace JamHealthRules

/** The whole state of a fight. Copying it is a snapshot. */
struct FJamFight
{
	int32 Tick = 0;
	TJamPerSide<FJamFighter> Fighters;
	TArray<FJamProjectile> Projectiles;
	TArray<FJamHazard> Hazards;
	TArray<FJamPickup> Pickups;
	/** From this step on, the next hit on the Publisher knocks a heal out of his pocket. */
	int32 NextHealTick = 0;
	FJamLedger Ledger;
	FJamBossState Boss;
	FJamStealState Steal;
	EJamPhase Phase = EJamPhase::Fight;
	int32 NextId = 1;
	/** Events of the last step only. */
	TArray<FJamEvent> Events;
281-	/** A stolen mechanic in the Publisher's hands: scales of the hero's numbers. */
282-	UPROPERTY()
283:	float BossStolenDamage = 0.f;
284-
285-	UPROPERTY()
286-	float BossStolenCooldown = 0.f;
288-	/**
289-	 * The base numbers of his stolen shuriken (T-074): the hero's own were retuned, his copy keeps what it had. Scaled
290:	 * by BossStolenCooldown, BossShurikenCooldownScale and BossStolenDamage like before.
291-	 */
; The ball alone takes the last 120 health: about 8 s of steady fire.
StealThreshold4=0.03
StealChoiceSeconds=7
StealChoiceLock=0.6
BossStolenDamage=0.9
BossStolenCooldown=1
; T-074: his stolen shuriken keeps the numbers it had before the hero's were retuned.

