	const FJamBalanceData B = JamTest::Balance();
	TestTrue(TEXT("about a fifth harder"), FMath::IsNearlyEqual(B.HeroCutDamageScale, 1.2f, 0.05f));
	TestEqual(TEXT("before the first cut: as listed"), JamHealthRules::HeroDamageScale(0, 1.2f), 1.f);
	TestEqual(TEXT("from the first cut on"), JamHealthRules::HeroDamageScale(1, 1.2f), 1.2f);
	TestEqual(TEXT("and after the others"), JamHealthRules::HeroDamageScale(3, 1.2f), 1.2f);

