	B.HealMaxOnFloor = 1.f;
	B.HealToss = 200.f;
	B.HealTossSeconds = 0.5f;
	B.HealPickupRadius = 40.f;
}

/** The two mechanics of block D, for JamTest::Balance. */
inline void SetParryAndUltimate(FJamBalanceData& B)
{
	B.ParryWindow = 0.2f;
