import os
import re

os.chdir(r"F:\Unreal_Engine\UnrealProjects\MegaJam2026\Source\JamGame")


def read(path):
    return open(path, encoding="utf-8").read()


def write(path, s):
    open(path, "w", encoding="utf-8", newline="\n").write(s)


def edit(path, a, b, count=1):
    s = read(path)
    assert s.count(a) == count, (path, a[:70], s.count(a))
    write(path, s.replace(a, b))


def pixels(path, names):
    s = read(path)
    for name in names:
        pat = re.compile(r"constexpr float " + name + r" = ([0-9.]+f);")
        assert len(pat.findall(s)) == 1, (path, name)
        s = pat.sub(r"constexpr JamHudPixels::FPixels " + name + r"{\1};", s)
    write(path, s)


def include(path, after, lines):
    edit(path, after, after + "".join("\n#include " + l for l in lines))


