constexpr JamHudPixels::FPixels HeroTextLift{28.f};
constexpr JamHudPixels::FPixels LoadoutLift{6.f};''', 1)
write(H, s)
edit(H, "const float HeroTextY = HeroBarBottom * H - 28.f;", "const float HeroTextY = HeroBarBottom * H - HeroTextLift;")
