#pragma once

#include "CoreMinimal.h"

/** Where the key light's spot is on the floor and how fast it is moving there, in cm and cm/s. */
struct FJamSpot
{
	FVector2D At = FVector2D::ZeroVector;
	FVector2D Velocity = FVector2D::ZeroVector;
};

/**
 * The key light on the Publisher (T-087) is worked by a hand, not glued to him: the spot trails him on a critically
 * damped spring, so it eases after him and never swings past, and it sways a little as an operator's would.
 * Tests: Jam.Spot.*
 */
namespace JamSpotRules
{
/** The spot Dt seconds on, chasing Target; once it has his pace it trails him by Lag seconds. Stable at any Dt. */
JAMGAME_API FJamSpot Follow(const FJamSpot& Spot, const FVector2D& Target, float Dt, float Lag);

/** The hand's sway at Time: a slow wander of at most Reach cm, smooth from frame to frame. */
JAMGAME_API FVector2D Sway(float Time, float Reach);
} // namespace JamSpotRules
#include "View/JamSpotRules.h"

FJamSpot JamSpotRules::Follow(const FJamSpot& Spot, const FVector2D& Target, float Dt, float Lag)
{
	if (Dt <= 0.f)
	{
		return Spot;
	}
	// A critically damped spring stepped exactly (Game Programming Gems 4, 1.10): its stiffness 2 / Lag makes it trail a
	// steady walk by Lag seconds, and the exponential's series keeps it stable at any Dt.
	const float Omega = 2.f / FMath::Max(Lag, UE_KINDA_SMALL_NUMBER);
	const float X = Omega * Dt;
	const float Decay = 1.f / (1.f + X + 0.48f * X * X + 0.235f * X * X * X);
	const FVector2D Off = Spot.At - Target;
	const FVector2D Pull = (Spot.Velocity + Omega * Off) * Dt;
	FJamSpot Next;
	Next.Velocity = (Spot.Velocity - Omega * Pull) * Decay;
	Next.At = Target + (Off + Pull) * Decay;
	return Next;
}

FVector2D JamSpotRules::Sway(float Time, float Reach)
{
	// Two slow waves on each axis at periods that never line up: a hand wanders, it does not loop. Each axis keeps
	// within 0.7 of Reach, so the two together stay inside it.
	const float X = 0.42f * FMath::Sin(0.9f * Time) + 0.28f * FMath::Sin(1.7f * Time + 1.3f);
	const float Y = 0.42f * FMath::Sin(0.7f * Time + 2.1f) + 0.28f * FMath::Sin(1.9f * Time + 0.4f);
	return FVector2D(X, Y) * Reach;
}
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/Actor.h"
#include "View/JamNeonRules.h"
#include "View/JamSpotRules.h"

#include "JamLightView.generated.h"

class UDirectionalLightComponent;
class UPointLightComponent;

/**
 * The neon light of the full-art tier (T-077): cyan and magenta lights round the edge of the arena that throw their
 * colour onto the floor, the bodies and the effects. The lower tiers turn them off (JamNeonRules::LightFor); the
 * camera's post process carries the rest of the tier's look (AJamCameraRig::SetLight).
 */
UCLASS()
class JAMGAME_API AJamLightView : public AActor
{
	GENERATED_BODY()

public:
	AJamLightView();

	/**
	 * Places the lights round an arena of this radius, in step with its posts, and takes the sun of Stage (the actor
	 * that lights the arena) to dim it at night. Called once.
	 */
	void Init(float ArenaRadius, const AActor& Stage);

	/** The lights shine and the sun dims with the full art only. Cheap when nothing changes. */
	void SetLight(EJamLight InLight);

	/** The full art's rain haze and depth fog (T-094); a zero density hides the fog. */
	void SetHaze(const FJamFilmLook& Look);

	/** Keeps the key light on the Publisher standing at BossAt (T-082), trailing him like a hand would (T-087). */
	void Follow(const FVector& BossAt, float Time);

private:
	UPROPERTY()
	TArray<TObjectPtr<UPointLightComponent>> Lamps;

	/** The stage's sun, not owned here: dimmed to a moon while the full art is on. */
	UPROPERTY()
	TObjectPtr<UDirectionalLightComponent> Sun;

	UPROPERTY()
	TObjectPtr<class USpotLightComponent> Key;

	UPROPERTY()
	TObjectPtr<class UExponentialHeightFogComponent> Haze;

	/** Where the key light's spot is on the floor, and when it last moved (negative: not placed yet). */
	FJamSpot Spot;
	float SpotTime = -1.f;

	float DaySun = 0.f;
	EJamLight Light = EJamLight::Neon;

	void DimSun();
};

