	/** The hero's own key light (T-100). */
	UPROPERTY()
	TObjectPtr<class USpotLightComponent> HeroKey;
''')
edit(H, '''	FJamSpot Spot;
	float SpotTime = -1.f;''', '''	FJamSpot Spot;
	FJamSpot HeroSpot;
	float SpotTime = -1.f;''')
edit(H, '''	void DimSun();''', '''	void DimSun();

	/** A warm key light with these cones, shown with the full art only. */
	class USpotLightComponent* MakeKey(float Candela, float InnerCone, float OuterCone);

	/** Points Light from above and the camera's side down at the spot At, at AimHeight over the floor. */
	static void Aim(class USpotLightComponent& Light, const FVector2D& At, float AimHeight);''')

C = "Private/View/JamLightView.cpp"
edit(C, '''constexpr float KeyLag = 0.5f;
constexpr float KeySway = 25.f;''', '''constexpr float KeyLag = 0.5f;
constexpr float KeySway = 25.f;
// T-100: the hero's own key light, smaller and dimmer than the Publisher's: it lifts him out of the dark without
// flattening the night. Its hand sways out of step with the other one.
constexpr float HeroKeyCandela = 450.f;
constexpr float HeroKeyAimHeight = 90.f;
constexpr float HeroKeyInnerCone = 6.f;
constexpr float HeroKeyOuterCone = 14.f;
constexpr float HeroSwayPhase = 11.3f;''')
edit(C, '''	Key = NewObject<USpotLightComponent>(this);
	Key->SetupAttachment(RootComponent);
	Key->SetMobility(EComponentMobility::Movable);
	Key->SetCastShadows(false);
	Key->SetIntensityUnits(ELightUnits::Candelas);
	Key->SetIntensity(KeyCandela);
	Key->SetAttenuationRadius(2.f * KeyHeight);
	Key->SetInnerConeAngle(KeyInnerCone);
	Key->SetOuterConeAngle(KeyOuterCone);
	Key->SetLightColor(KeyWarm);
	Key->SetVisibility(Light == EJamLight::Neon);
	Key->RegisterComponent();
''', '''	Key = MakeKey(KeyCandela, KeyInnerCone, KeyOuterCone);
	HeroKey = MakeKey(HeroKeyCandela, HeroKeyInnerCone, HeroKeyOuterCone);
''')
edit(C, '''	if (Key)
	{
		Key->SetVisibility(Light == EJamLight::Neon);
	}
	DimSun();''', '''	for (USpotLightComponent* Each : { Key.Get(), HeroKey.Get() })
	{
		if (Each)
		{
			Each->SetVisibility(Light == EJamLight::Neon);
		}
	}
	DimSun();''')
edit(C, '''void AJamLightView::Follow(const FVector& BossAt, float Time)
{
	if (!Key)
	{
		return;
	}
	const FVector2D Boss(BossAt);
	if (SpotTime < 0.f)
	{
		// The first frame finds him already lit.
		Spot.At = Boss;
	}
	Spot = JamSpotRules::Follow(Spot, Boss, FMath::Clamp(Time - FMath::Max(SpotTime, 0.f), 0.f, 0.1f), KeyLag);
	SpotTime = Time;
	const FVector2D Aim = Spot.At + JamSpotRules::Sway(Time, KeySway);
	// From above and from the camera's side of him (the camera looks down from -X), aimed at his chest.
	const FVector From(Aim.X - KeyAhead, Aim.Y, KeyHeight);
	const FVector At(Aim.X, Aim.Y, KeyAimHeight);
	Key->SetWorldLocationAndRotation(From, (At - From).Rotation());
}''', '''void AJamLightView::Follow(const FVector& BossAt, const FVector& HeroAt, float Time, float ToHero)
{
	if (!Key || !HeroKey)
	{
		return;
	}
	const FVector2D Boss(BossAt);
	const FVector2D Hero(HeroAt);
	if (SpotTime < 0.f)
	{
		// The first frame finds them already lit.
		Spot.At = Boss;
		HeroSpot.At = Hero;
	}
	const float Dt = FMath::Clamp(Time - FMath::Max(SpotTime, 0.f), 0.f, 0.1f);
	SpotTime = Time;
	Spot = JamSpotRules::Follow(Spot, Boss, Dt, KeyLag);
	if (ToHero < 1.f)
	{
		// T-100: the intro's camera is on its way to the hero: his spot rides with it out of the Publisher's beam.
		HeroSpot.At = JamSpotRules::SplitOff(Spot.At, Hero, ToHero);
		HeroSpot.Velocity = FVector2D::ZeroVector;
	}
	else
	{
		HeroSpot = JamSpotRules::Follow(HeroSpot, Hero, Dt, KeyLag);
	}
	HeroKey->SetIntensity(HeroKeyCandela * JamSpotRules::SplitShare(ToHero));
	Aim(*Key, Spot.At + JamSpotRules::Sway(Time, KeySway), KeyAimHeight);
	Aim(*HeroKey, HeroSpot.At + JamSpotRules::Sway(Time + HeroSwayPhase, KeySway), HeroKeyAimHeight);
}

USpotLightComponent* AJamLightView::MakeKey(float Candela, float InnerCone, float OuterCone)
{
	USpotLightComponent* Spot = NewObject<USpotLightComponent>(this);
	Spot->SetupAttachment(RootComponent);
	Spot->SetMobility(EComponentMobility::Movable);
	Spot->SetCastShadows(false);
	Spot->SetIntensityUnits(ELightUnits::Candelas);
	Spot->SetIntensity(Candela);
	Spot->SetAttenuationRadius(2.f * KeyHeight);
	Spot->SetInnerConeAngle(InnerCone);
	Spot->SetOuterConeAngle(OuterCone);
	Spot->SetLightColor(KeyWarm);
	Spot->SetVisibility(Light == EJamLight::Neon);
	Spot->RegisterComponent();
	return Spot;
}

void AJamLightView::Aim(USpotLightComponent& Light, const FVector2D& At, float AimHeight)
{
	// From above and from the camera's side (the camera looks down from -X), aimed at the chest.
	const FVector From(At.X - KeyAhead, At.Y, KeyHeight);
	const FVector Target(At.X, At.Y, AimHeight);
	Light.SetWorldLocationAndRotation(From, (Target - From).Rotation());
}''')

