#include "Audio/JamSounds.h"

#include "Components/AudioComponent.h"
#include "Kismet/GameplayStatics.h"
#include "TimerManager.h"
#include "Sound/SoundWave.h"
#include "UObject/ConstructorHelpers.h"

AJamSounds::AJamSounds()
{
	PrimaryActorTick.bCanEverTick = false;
	SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));
	for (int32 Index = 0; Index < JamSoundRules::CueCount; ++Index)
	{
		const TCHAR* Name = JamSoundRules::NameOf(static_cast<EJamCue>(Index));
		ConstructorHelpers::FObjectFinder<USoundWave> Finder(*FString::Printf(TEXT("/Game/Audio/Sfx/%s.%s"), Name, Name));
		Sounds.Add(Finder.Object);
	}
	// In EJamComicSound's order after None.
	for (const TCHAR* Name : { TEXT("sfx_comic_typing_01"), TEXT("sfx_comic_ring_01"), TEXT("sfx_comic_shatter_01") })
	{
		ConstructorHelpers::FObjectFinder<USoundWave> Finder(*FString::Printf(TEXT("/Game/Audio/Sfx/%s.%s"), Name, Name));
		ComicSounds.Add(Finder.Object);
	}
}

void AJamSounds::PlayComic(int32 Index)
{
	if (ComicPlaying)
	{
		ComicPlaying->Stop();
		ComicPlaying = nullptr;
	}
	if (ComicSounds.IsValidIndex(Index) && ComicSounds[Index])
	{
		ComicPlaying = UGameplayStatics::SpawnSound2D(this, ComicSounds[Index]);
	}
}

void AJamSounds::Play(const TArray<FJamEvent>& Events, const FJamFight& Fight, bool bVoiceSpeaking)
{
	for (const EJamCue Cue : JamSoundRules::CuesOf(Events, Fight))
	{
		USoundWave* Sound = Sounds[static_cast<int32>(Cue)];
		if (!Sound)
		{
			continue;
		}
		const FJamMix Mix = JamSoundRules::MixOf(Cue, bVoiceSpeaking);
		UAudioComponent* Playing = UGameplayStatics::SpawnSound2D(this, Sound, Mix.Volume);
	if (!bSkip && JamComicRules::IsPanelDone(ComicPanel, Time - ComicPanelStart, Voice->IsSpeaking()))
	{
		++ComicPanel;
		if (ComicPanel < JamComicRules::PanelCount)
		{
			StartComicPanel(ComicPanel, Time);
		}
	}
	AJamHUD* Hud = Cast<AJamHUD>(Player.GetHUD());
	if (bSkip || ComicPanel >= JamComicRules::PanelCount)
	{
		bComic = false;
		Voice->Hush();
		Sounds->PlayComic(INDEX_NONE);
		// T-096: the controls before the fight, once, after the comic.
		OpenHowTo(true, Time);
		if (Hud)
		{
			Hud->bComic = false;
		}
		return false;
	}
	if (Hud)
	{
		Hud->bComic = true;
		Hud->ComicPanel = ComicPanel;
		Hud->ComicPanelAge = Time - ComicPanelStart;
		Hud->bComicBalloon = Voice->Current(Hud->ComicLine);
	}
	return true;
}

void AJamGameMode::StartComicPanel(int32 Index, float Time)
{
	ComicPanelStart = Time;
	// The session-5s playtest: the keyboard under the first panel, the phone's ring under the second.
	Sounds->PlayComic(static_cast<int32>(JamComicRules::PanelOf(Index).Sound) - 1);
	for (const EJamLine Line : JamComicRules::PanelOf(Index).Lines)
	{
		Voice->Say(Line);
	}
}

void AJamGameMode::OpenHowTo(bool bCountdown, float Time)
{
	bHowTo = true;
