154	/** The open list's options under the control at Control, kept on a screen Height tall. */
155	TArray<FBox2D> ListUnder(const FBox2D& Control, int32 Count, double RowHeight, double Height)
156	{
157		TArray<FBox2D> Options;
158		if (Count <= 0)
159		{
160			return Options;
161		}
162		const double OptionHeight = FMath::Min(OptionShare * RowHeight, (1.0 - 2.0 * ListMargin) * Height / Count);
163		const double Top = FMath::Max(FMath::Min(Control.Max.Y, (1.0 - ListMargin) * Height - Count * OptionHeight), ListMargin * Height);
164		for (int32 Index = 0; Index < Count; ++Index)
165		{
166			const double Y = Top + Index * OptionHeight;
167			Options.Add(FBox2D(FVector2D(Control.Min.X, Y), FVector2D(Control.Max.X, Y + OptionHeight)));
