190			return PressInList(Menu, Item, Key);
191		}
192		switch (Key)
193		{
194			case EJamMenuKey::Up:
195				Menu.Selected = Cycle(Menu.Selected, -1, Items.Num());
196				return EJamMenuAction::None;
197			case EJamMenuKey::Down:
198				Menu.Selected = Cycle(Menu.Selected, 1, Items.Num());
199				return EJamMenuAction::None;
200			case EJamMenuKey::Left:
201			case EJamMenuKey::Right:
202				return IsValueRow(Item) ? StepValue(Menu.Settings, Item, Key == EJamMenuKey::Right ? 1 : -1) : EJamMenuAction::None;
203			case EJamMenuKey::Confirm:
204				return Confirm(Menu, Item);
205			default:
206				return Menu.Page == EJamMenuPage::Settings ? CloseSettings(Menu) : EJamMenuAction::None;
207		}
