243	int32 JamMenuRules::OptionCount(const FJamMenuSettings& Settings, EJamMenuItem Item)
244	{
245		switch (Item)
246		{
247			case EJamMenuItem::Quality:
248				return QualityCount;
249			case EJamMenuItem::Window:
250				return WindowCount;
251			case EJamMenuItem::Resolution:
252				return Settings.ResolutionCount;
253			default:
254				return 0;
255		}
256	}
257	
258	FJamMenuLayout JamMenuRules::Layout(const FJamMenu& Menu, const FVector2D& Screen)
259	{
260		const TArray<EJamMenuItem> Items = ItemsOf(Menu.Page);
261		const bool bSettings = Menu.Page == EJamMenuPage::Settings;
262		const double Column = (bSettings ? SettingsColumn : MainColumn) * Screen.X;
263		const double Left = 0.5 * (Screen.X - Column);
264		const double Top = (bSettings ? SettingsTop : MainTop) * Screen.Y;
265		const double Row = RowShare * Screen.Y;
266		FJamMenuLayout Out;
267		for (int32 Index = 0; Index < Items.Num(); ++Index)
268		{
269			const double RowTop = Top + Index * Row;
270			Out.Rows.Add(FBox2D(FVector2D(Left, RowTop), FVector2D(Left + Column, RowTop + Row)));
271			const bool bControl = IsList(Items[Index]) || IsSlider(Items[Index]);
272			Out.Controls.Add(bControl ? FBox2D(FVector2D(Left + ControlFrom * Column, RowTop + ControlInset * Row),
273											FVector2D(Left + (1.0 - ControlPadding) * Column, RowTop + (1.0 - ControlInset) * Row))
274									  : FBox2D(ForceInit));
275		}
276		if (bSettings)
277		{
278			const double Pad = PanelPadding * Screen.Y;
279			Out.Panel =
280				FBox2D(FVector2D(Left - Pad, Top - Pad), FVector2D(Left + Column + Pad, Top + Items.Num() * Row + PanelHint * Screen.Y));
281		}
282		if (Menu.bListOpen && Out.Controls.IsValidIndex(Menu.Selected))
283		{
284			Out.Options = ListUnder(Out.Controls[Menu.Selected], OptionCount(Menu.Settings, Items[Menu.Selected]), Row, Screen.Y);
285		}
286		return Out;
287	}
288	
289	void JamMenuRules::Hover(FJamMenu& Menu, const FJamMenuLayout& Layout, const FVector2D& At)
290	{
291		if (Menu.bDragging)
292		{
293			return;
294		}
295		if (Menu.bListOpen)
296		{
297			const int32 Option = Layout.Options.IndexOfByPredicate([&At](const FBox2D& Box) { return Box.IsInsideOrOn(At); });
298			Menu.ListSelected = Option != INDEX_NONE ? Option : Menu.ListSelected;
299			return;
300		}
301		Point(Menu, RowUnder(Layout, At));
302	}
303	
304	EJamMenuAction JamMenuRules::Click(FJamMenu& Menu, const FJamMenuLayout& Layout, const FVector2D& At)
305	{
306		if (Menu.bListOpen)
307		{
308			const int32 Option = Layout.Options.IndexOfByPredicate([&At](const FBox2D& Box) { return Box.IsInsideOrOn(At); });
309			if (Option != INDEX_NONE)
310			{
311				return Pick(Menu, Option);
312			}
313			Menu.bListOpen = false;
314			return EJamMenuAction::None;
315		}
316		const TArray<EJamMenuItem> Items = ItemsOf(Menu.Page);
317		const int32 Row = RowUnder(Layout, At);
318		if (!Items.IsValidIndex(Row))
319		{
320			return EJamMenuAction::None;
321		}
322		Menu.Selected = Row;
323		const EJamMenuItem Item = Items[Row];
324		if (IsSlider(Item))
325		{
326			if (!Layout.Controls.IsValidIndex(Row) || !Layout.Controls[Row].IsInsideOrOn(At))
327			{
328				return EJamMenuAction::None;
329			}
330			Menu.bDragging = true;
331			return Slide(Menu.Settings, Item, Layout.Controls[Row], At.X);
332		}
333		return Confirm(Menu, Item);
334	}
335	
336	EJamMenuAction JamMenuRules::Drag(FJamMenu& Menu, const FJamMenuLayout& Layout, const FVector2D& At)
337	{
338		const TArray<EJamMenuItem> Items = ItemsOf(Menu.Page);
339		if (!Menu.bDragging || !Items.IsValidIndex(Menu.Selected) || !IsSlider(Items[Menu.Selected]) ||
340			!Layout.Controls.IsValidIndex(Menu.Selected))
341		{
342			return EJamMenuAction::None;
343		}
344		return Slide(Menu.Settings, Items[Menu.Selected], Layout.Controls[Menu.Selected], At.X);
345	}
346	
347	void JamMenuRules::Release(FJamMenu& Menu)
348	{
349		Menu.bDragging = false;
350	}
351	
352	FIntPoint JamMenuRules::FitWindow(const FIntPoint& Size, const FIntPoint& Desktop)
353	{
354		// A window takes at most this share of the desktop each way, so its title bar and the taskbar stay on the screen.
355		constexpr double FitWindowShare = 0.9;
356		if (Desktop.X <= 0 || Desktop.Y <= 0 || Size.X <= 0 || Size.Y <= 0)
357		{
358			return Size;
359		}
360		const double Scale = FMath::Min3(1.0, FitWindowShare * Desktop.X / Size.X, FitWindowShare * Desktop.Y / Size.Y);
361		if (Scale >= 1.0 && Size.X < Desktop.X && Size.Y < Desktop.Y)
362		{
363			return Size;
364		}
365		return FIntPoint(FMath::FloorToInt32(Size.X * Scale), FMath::FloorToInt32(Size.Y * Scale));
366	}
