"""Read-only: lists the itch uploads of ronin-final-cut (filename, display name, channel, platform). Key from .env."""
import json
import urllib.request

ROOT = r"F:\Unreal_Engine\UnrealProjects\MegaJam2026"
key = ""
for line in open(ROOT + r"\.env", encoding="utf-8"):
    if line.startswith("BUTLER_API_KEY="):
        key = line.split("=", 1)[1].strip().strip('"')


def get(path):
    req = urllib.request.Request("https://itch.io/api/1/key/" + path, headers={"Authorization": "Bearer " + key})
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.load(r)


games = get("my-games").get("games", [])
for g in games:
    print("GAME", g.get("id"), g.get("title"), g.get("url"), "published" if g.get("published") else "draft")
    if "ronin" not in (g.get("url") or "").lower():
        continue
    ups = get("game/%s/uploads" % g["id"]).get("uploads", [])
    for u in ups:
        keys = ["id", "filename", "display_name", "channel_name", "storage", "p_windows", "size", "build_id", "created_at", "updated_at"]
        print("  UPLOAD", {k: u.get(k) for k in keys})

