	{
		const int32 Index = Steal.Offer.IndexOfByPredicate([&Wanted](EJamMechanic M) { return Wanted == JamLoadoutRules::Name(M); });
		if (Index != INDEX_NONE)
		{
			Intent.Choice = Index;
			break;
		}
	}
