edit(D, '''	void EndFrame(float Time);''', '''	void EndFrame(float Time);

	/**
	 * T-102: with -JamFrameLog=<file>, counts the frame and every 5 s writes the average frame rate since the first 5 s
	 * to the file, so a Development and a Shipping build can be compared. Works without -JamDemo.
	 */
	void CountFrame(double FrameSeconds, double RealTime);''')
edit(D, '''	FString CaptureDir;''', '''	FString CaptureDir;
	FString FrameLog;
	int32 CountedFrames = 0;
	double CountedSeconds = 0.0;
	double NextFrameWrite = 10.0;''')
J = SRC + "Private/Game/JamDemo.cpp"
edit(J, '''	if (FParse::Value(CommandLine, TEXT("JamCapture="), CaptureDir))''', '''	FParse::Value(CommandLine, TEXT("JamFrameLog="), FrameLog);
	if (FParse::Value(CommandLine, TEXT("JamCapture="), CaptureDir))''')
edit(J, '''#include "Misc/App.h"''', '''#include "Misc/App.h"
#include "Misc/FileHelper.h"''')
edit(J, '''void FJamDemo::EndFrame(float Time)''', '''void FJamDemo::CountFrame(double FrameSeconds, double RealTime)
{
	// The first seconds load and compile: they are not the game's frame rate.
	constexpr double WarmUpSeconds = 5.0;
	constexpr double WriteEvery = 5.0;
	if (FrameLog.IsEmpty() || RealTime < WarmUpSeconds)
	{
		return;
	}
	++CountedFrames;
	CountedSeconds += FrameSeconds;
	if (RealTime >= NextFrameWrite && CountedSeconds > 0.0)
	{
		NextFrameWrite = RealTime + WriteEvery;
		FFileHelper::SaveStringToFile(FString::Printf(TEXT("frames %d seconds %.1f fps %.1f\\n"), CountedFrames, CountedSeconds,
										  CountedFrames / CountedSeconds),
			*FrameLog);
	}
}

void FJamDemo::EndFrame(float Time)''')
