// T-104: the full art's neon bars (Submission/hud_mock_neon.png, drawn by Submission/hud_mock_bars.py): parallelograms
// on a dark plate with scanlines, the fill in segments with a bright top edge, a neon frame with a soft glow. Drawn on the
// canvas, so they stay sharp at any resolution. From the first cut on the plain bars of JamHUD.cpp come back.
#include "CanvasItem.h"
#include "Engine/Canvas.h"
#include "Engine/Engine.h"
#include "Engine/Font.h"
#include "GlobalRenderResources.h"
#include "Sim/JamFightSubsystem.h"
#include "UI/JamHUD.h"
#include "UI/JamHUDPixels.h"
#include "UI/JamNeonBarRules.h"
#include "UI/JamTexts.h"

namespace
{
// The mock's layout, as shares of the screen it was drawn on (a 2000x836 preview of a 3440x1440 frame).
constexpr float BossFrom = 0.26f;
constexpr float BossTo = 0.625f;
constexpr float BossTop = 0.048f;
constexpr float BossBottom = 0.067f;
constexpr float HeroFrom = 0.035f;
constexpr float HeroTo = 0.25f;
constexpr float HeroTop = 0.9354f;
constexpr float HeroBottom = 0.9522f;
constexpr float UltimateTo = 0.22f;
constexpr float UltimateTop = 0.9641f;
constexpr float UltimateBottom = 0.9713f;
constexpr int32 BossSegments = 40;
constexpr int32 HeroSegments = 20;
constexpr int32 UltimateSegments = 24;
// Sizes in pixels of the 1080-line screen (the mock's pixels times 1.29).
constexpr JamHudPixels::FPixels BossSlant{ 13.f };
constexpr JamHudPixels::FPixels HeroSlant{ 10.f };
constexpr JamHudPixels::FPixels UltimateSlant{ 5.f };
constexpr JamHudPixels::FPixels PlatePad{ 5.f };
constexpr JamHudPixels::FPixels SegmentGap{ 4.f };
constexpr JamHudPixels::FPixels ScanlineStep{ 3.f };
constexpr JamHudPixels::FPixels FrameWidth{ 2.f };
constexpr JamHudPixels::FPixels TopEdgeWidth{ 1.5f };
constexpr JamHudPixels::FPixels GlowWidth{ 7.f };
constexpr JamHudPixels::FPixels CutReach{ 11.f };
constexpr JamHudPixels::FPixels CutWidth{ 2.5f };
constexpr JamHudPixels::FPixels CutLabelGap{ 3.f };
constexpr JamHudPixels::FPixels TabWidth{ 250.f };
constexpr JamHudPixels::FPixels TabHeight{ 28.f };
constexpr JamHudPixels::FPixels TabLift{ 10.f };
constexpr JamHudPixels::FPixels TabTextInset{ 18.f };
constexpr JamHudPixels::FPixels NumberGap{ 22.f };
constexpr JamHudPixels::FPixels HeroTextGap{ 6.f };
constexpr JamHudPixels::FPixels LabelGap{ 14.f };
constexpr float NameScale = 1.3f;
constexpr float NumberScale = 1.3f;
constexpr float SmallScale = 0.9f;
constexpr float UltimatePulseHz = 1.5f;
const FLinearColor Pink(FColor(255, 70, 110));
const FLinearColor Cyan(FColor(40, 230, 255));
const FLinearColor Magenta(FColor(255, 60, 220));
const FLinearColor PlateColor(FColor(6, 8, 16, 215));
const FLinearColor NameColor(FColor(255, 225, 230));
const FLinearColor HeroNameColor(FColor(220, 250, 255));
const FLinearColor ChunkWhite(1.f, 1.f, 1.f, 0.6f);
const FLinearColor HealPreview(0.55f, 1.f, 0.6f, 0.7f);

/** The four corners of a bar's parallelogram: its top edge shifted right by Slant. */
struct FPara
{
	FVector2D Corners[4];

	FPara(float X0, float Y0, float X1, float Y1, float Slant)
		: Corners{ FVector2D(X0 + Slant, Y0), FVector2D(X1 + Slant, Y0), FVector2D(X1, Y1), FVector2D(X0, Y1) }
	{
	}
};

FLinearColor WithAlpha(const FLinearColor& Color, float Alpha)
{
	return FLinearColor(Color.R, Color.G, Color.B, Color.A * Alpha);
}

void Fill(FCanvas& Canvas, const FPara& P, const FLinearColor& Color, ESimpleElementBlendMode Blend = SE_BLEND_Translucent)
{
	for (const FVector2D& Third : { P.Corners[2], P.Corners[3] })
	{
		const FVector2D& Second = &Third == &P.Corners[2] ? P.Corners[1] : P.Corners[2];
		FCanvasTriangleItem Triangle(P.Corners[0], Second, Third, GWhiteTexture);
		Triangle.SetColor(Color);
		Triangle.BlendMode = Blend;
		Canvas.DrawItem(Triangle);
	}
}

void Line(FCanvas& Canvas, const FVector2D& A, const FVector2D& B, const FLinearColor& Color, float Width,
	ESimpleElementBlendMode Blend = SE_BLEND_Translucent)
{
	FCanvasLineItem Item(A, B);
	Item.SetColor(Color);
	Item.LineThickness = Width;
	Item.BlendMode = Blend;
	Canvas.DrawItem(Item);
}

void Outline(FCanvas& Canvas, const FPara& P, const FLinearColor& Color, float Width, ESimpleElementBlendMode Blend = SE_BLEND_Translucent)
{
	for (int32 Index = 0; Index < 4; ++Index)
	{
		Line(Canvas, P.Corners[Index], P.Corners[(Index + 1) % 4], Color, Width, Blend);
	}
}

/** The neon frame: a soft glow of wide faint passes under a thin bright line. */
void NeonFrame(FCanvas& Canvas, const FPara& P, const FLinearColor& Color, float Alpha, float Glow)
{
	const float Passes[][2] = { { 3.f, 0.06f }, { 2.f, 0.1f }, { 1.f, 0.18f } };
	for (const auto& Pass : Passes)
	{
		Outline(Canvas, P, WithAlpha(Color, Alpha * Glow * Pass[1]), GlowWidth * Pass[0], SE_BLEND_Additive);
	}
	Outline(Canvas, P, WithAlpha(Color, Alpha), FrameWidth);
}
} // namespace

void AJamHUD::DrawNeonBar(const FJamNeonBar& Bar)
{
	FCanvas& C = *Canvas->Canvas;
	const float X0 = Bar.Box.Min.X;
	const float Y0 = Bar.Box.Min.Y;
	const float X1 = Bar.Box.Max.X;
	const float Y1 = Bar.Box.Max.Y;
	const float Length = X1 - X0;
	const FPara Plate(X0 - PlatePad, Y0 - PlatePad, X1 + PlatePad, Y1 + PlatePad, Bar.Slant);
	Fill(C, Plate, WithAlpha(PlateColor, Bar.Alpha));
	for (float Y = Y0; Y < Y1; Y += ScanlineStep)
	{
		const float Shift = Bar.Slant * (Y1 - Y) / FMath::Max(1.f, Y1 - Y0);
		Line(C, FVector2D(X0 + Shift, Y), FVector2D(X1 + Shift, Y), FLinearColor(1.f, 1.f, 1.f, 0.04f * Bar.Alpha), 1.f);
	}
	// The lit part's own glow under the segments.
	Fill(C, FPara(X0 - 0.5f * PlatePad, Y0 - 0.5f * PlatePad, X0 + Length * Bar.Fill, Y1 + 0.5f * PlatePad, Bar.Slant),
		WithAlpha(Bar.Color, 0.18f * Bar.Alpha * Bar.Glow), SE_BLEND_Additive);
	const FLinearColor Lit = FMath::Lerp(Bar.Color, FLinearColor::White, Bar.Whiten);
	for (const FJamBarSegment& Segment : JamNeonBarRules::Segments(Bar.Segments, SegmentGap / FMath::Max(1.f, Length), Bar.Fill))
	{
		const float From = X0 + Length * Segment.From;
		if (!Segment.IsLit())
		{
			Outline(C, FPara(From, Y0, X0 + Length * Segment.To, Y1, Bar.Slant), WithAlpha(Bar.Color, 0.25f * Bar.Alpha), 1.f);
			continue;
		}
		const float To = X0 + Length * Segment.FillTo;
		Fill(C, FPara(From, Y0, To, Y1, Bar.Slant), WithAlpha(Lit, 0.92f * Bar.Alpha));
		Line(C, FVector2D(From + Bar.Slant, Y0), FVector2D(To + Bar.Slant, Y0), FLinearColor(1.f, 1.f, 1.f, 0.67f * Bar.Alpha), TopEdgeWidth);
	}
	// T-053's white chunk of health just lost, and a heal's light preview, over the empty segments.
	if (Bar.Chunk > Bar.Fill)
	{
		Fill(C, FPara(X0 + Length * Bar.Fill, Y0, X0 + Length * Bar.Chunk, Y1, Bar.Slant), WithAlpha(ChunkWhite, Bar.Alpha));
	}
	if (Bar.Preview > Bar.Fill)
	{
		Fill(C, FPara(X0 + Length * Bar.Fill, Y0, X0 + Length * Bar.Preview, Y1, Bar.Slant), WithAlpha(HealPreview, Bar.Alpha));
	}
	NeonFrame(C, Plate, Bar.Color, Bar.Alpha, Bar.Glow);
}

void AJamHUD::DrawNeonBoss(const FJamFighter& Boss, const FJamBalanceData& Balance)
{
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	FJamNeonBar Bar;
	Bar.Box = FBox2D(FVector2D(BossFrom * W, BossTop * H), FVector2D(BossTo * W, BossBottom * H));
	Bar.Slant = BossSlant;
	Bar.Color = Pink;
	Bar.Segments = BossSegments;
	Bar.Fill = BossBar.Fill;
	Bar.Chunk = BossBar.Chunk;
	Bar.Preview = BossBar.Preview;
	Bar.Alpha = BossBarAlpha;
	DrawNeonBar(Bar);
