constexpr float HeroTo = 0.25f;
constexpr float HeroTop = 0.9354f;
constexpr float HeroBottom = 0.9522f;
constexpr float UltimateTo = 0.22f;
constexpr float UltimateTop = 0.9641f;
constexpr float UltimateBottom = 0.9713f;
constexpr int32 BossSegments = 40;
constexpr int32 HeroSegments = 20;
constexpr int32 UltimateSegments = 24;
// Sizes in pixels of the 1080-line screen (the mock's pixels times 1.29).
constexpr JamHudPixels::FPixels BossSlant{ 13.f };
constexpr JamHudPixels::FPixels HeroSlant{ 10.f };
constexpr JamHudPixels::FPixels UltimateSlant{ 5.f };
