const FLinearColor Cyan(FColor(40, 230, 255));
const FLinearColor Magenta(FColor(255, 60, 220));
const FLinearColor PlateColor(FColor(6, 8, 16, 215));
const FLinearColor NameColor(FColor(255, 225, 230));
const FLinearColor HeroNameColor(FColor(220, 250, 255));
