/** The four corners of a bar's parallelogram: its top edge shifted right by Slant. */
struct FPara
{
	FVector2D Corners[4];

	FPara(float X0, float Y0, float X1, float Y1, float Slant)
		: Corners{ FVector2D(X0 + Slant, Y0), FVector2D(X1 + Slant, Y0), FVector2D(X1, Y1), FVector2D(X0, Y1) }
