FLinearColor WithAlpha(const FLinearColor& Color, float Alpha)
{
	return FLinearColor(Color.R, Color.G, Color.B, Color.A * Alpha);
}

void Fill(FCanvas& Canvas, const FPara& P, const FLinearColor& Color, ESimpleElementBlendMode Blend = SE_BLEND_Translucent)
{
	for (const FVector2D& Third : { P.Corners[2], P.Corners[3] })
	{
