	{
		Line(Canvas, P.Corners[Index], P.Corners[(Index + 1) % 4], Color, Width, Blend);
	}
}

/** The neon frame: a soft glow of wide faint passes under a thin bright line. */
void NeonFrame(FCanvas& Canvas, const FPara& P, const FLinearColor& Color, float Alpha, float Glow)
{
	const float Passes[][2] = { { 3.f, 0.06f }, { 2.f, 0.1f }, { 1.f, 0.18f } };
	for (const auto& Pass : Passes)
	{
		Outline(Canvas, P, WithAlpha(Color, Alpha * Glow * Pass[1]), GlowWidth * Pass[0], SE_BLEND_Additive);
	}
	Outline(Canvas, P, WithAlpha(Color, Alpha), FrameWidth);
}
