void AJamHUD::DrawNeonBar(const FJamNeonBar& Bar)
{
	FCanvas& C = *Canvas->Canvas;
	const float X0 = Bar.Box.Min.X;
	const float Y0 = Bar.Box.Min.Y;
	const float X1 = Bar.Box.Max.X;
	const float Y1 = Bar.Box.Max.Y;
	const float Length = X1 - X0;
	const FPara Plate(X0 - PlatePad, Y0 - PlatePad, X1 + PlatePad, Y1 + PlatePad, Bar.Slant);
	Fill(C, Plate, WithAlpha(PlateColor, Bar.Alpha));
	for (float Y = Y0; Y < Y1; Y += ScanlineStep)
	{
		const float Shift = Bar.Slant * (Y1 - Y) / FMath::Max(1.f, Y1 - Y0);
		Line(C, FVector2D(X0 + Shift, Y), FVector2D(X1 + Shift, Y), FLinearColor(1.f, 1.f, 1.f, 0.04f * Bar.Alpha), 1.f);
	}
	// The lit part's own glow under the segments.
	Fill(C, FPara(X0 - 0.5f * PlatePad, Y0 - 0.5f * PlatePad, X0 + Length * Bar.Fill, Y1 + 0.5f * PlatePad, Bar.Slant),
		WithAlpha(Bar.Color, 0.18f * Bar.Alpha * Bar.Glow), SE_BLEND_Additive);
	const FLinearColor Lit = FMath::Lerp(Bar.Color, FLinearColor::White, Bar.Whiten);
	for (const FJamBarSegment& Segment : JamNeonBarRules::Segments(Bar.Segments, SegmentGap / FMath::Max(1.f, Length), Bar.Fill))
	{
		const float From = X0 + Length * Segment.From;
		if (!Segment.IsLit())
		{
			Outline(C, FPara(From, Y0, X0 + Length * Segment.To, Y1, Bar.Slant), WithAlpha(Bar.Color, 0.25f * Bar.Alpha), 1.f);
			continue;
		}
		const float To = X0 + Length * Segment.FillTo;
		Fill(C, FPara(From, Y0, To, Y1, Bar.Slant), WithAlpha(Lit, 0.92f * Bar.Alpha));
		Line(C, FVector2D(From + Bar.Slant, Y0), FVector2D(To + Bar.Slant, Y0), FLinearColor(1.f, 1.f, 1.f, 0.67f * Bar.Alpha), TopEdgeWidth);
	}
	// T-053's white chunk of health just lost, and a heal's light preview, over the empty segments.
	if (Bar.Chunk > Bar.Fill)
	{
		Fill(C, FPara(X0 + Length * Bar.Fill, Y0, X0 + Length * Bar.Chunk, Y1, Bar.Slant), WithAlpha(ChunkWhite, Bar.Alpha));
	}
	if (Bar.Preview > Bar.Fill)
	{
		Fill(C, FPara(X0 + Length * Bar.Fill, Y0, X0 + Length * Bar.Preview, Y1, Bar.Slant), WithAlpha(HealPreview, Bar.Alpha));
	}
	NeonFrame(C, Plate, Bar.Color, Bar.Alpha, Bar.Glow);
}

void AJamHUD::DrawNeonBoss(const FJamFighter& Boss, const FJamBalanceData& Balance)
{
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	FJamNeonBar Bar;
	Bar.Box = FBox2D(FVector2D(BossFrom * W, BossTop * H), FVector2D(BossTo * W, BossBottom * H));
	Bar.Slant = BossSlant;
	Bar.Color = Pink;
	Bar.Segments = BossSegments;
	Bar.Fill = BossBar.Fill;
	Bar.Chunk = BossBar.Chunk;
	Bar.Preview = BossBar.Preview;
	Bar.Alpha = BossBarAlpha;
	DrawNeonBar(Bar);
	UFont* Font = GEngine->GetMediumFont();
	const FLinearColor Fade(1.f, 1.f, 1.f, BossBarAlpha);

	// His name on its own slanted tab over the bar's left end.
	const float TabBottom = Bar.Box.Min.Y - TabLift;
	const FPara Tab(Bar.Box.Min.X - PlatePad, TabBottom - TabHeight, Bar.Box.Min.X + TabWidth, TabBottom, BossSlant);
	Fill(*Canvas->Canvas, Tab, WithAlpha(PlateColor, BossBarAlpha));
	NeonFrame(*Canvas->Canvas, Tab, Pink, BossBarAlpha, 1.f);
	float TextW = 0.f;
	float TextH = 0.f;
	GetTextSize(JamTexts::BossName, TextW, TextH, Font, NameScale);
	DrawText(JamTexts::BossName, NameColor * Fade, Bar.Box.Min.X + TabTextInset, TabBottom - 0.5f * (TabHeight + TextH), Font, NameScale);

	// Where he steals a feature: white cuts across the bar, the share under each.
	for (const float Mark : JamNeonBarRules::CutMarks(Balance))
	{
		const float X = Bar.Box.Min.X + Bar.Box.GetSize().X * Mark;
		Line(*Canvas->Canvas, FVector2D(X + BossSlant, Bar.Box.Min.Y - CutReach), FVector2D(X, Bar.Box.Max.Y + CutReach),
			FLinearColor(1.f, 1.f, 1.f, 0.9f * BossBarAlpha), CutWidth);
		const FString Label = FString::Printf(TEXT("%d%%"), FMath::RoundToInt32(Mark * 100.f));
		GetTextSize(Label, TextW, TextH, Font, SmallScale);
		DrawText(Label, FLinearColor(1.f, 1.f, 1.f, 0.67f * BossBarAlpha), X - 0.5f * TextW, Bar.Box.Max.Y + CutReach + CutLabelGap, Font,
			SmallScale);
	}

	// The number bright, the whole dim, right of the bar.
	const FString Now = FString::FromInt(FMath::CeilToInt32(Boss.Health));
	GetTextSize(Now, TextW, TextH, Font, NumberScale);
	const float NumberX = Bar.Box.Max.X + BossSlant + NumberGap;
	const float NumberY = Bar.Box.GetCenter().Y - 0.5f * TextH;
	DrawText(Now, FLinearColor(1.f, 1.f, 1.f, 0.95f * BossBarAlpha), NumberX, NumberY, Font, NumberScale);
	DrawText(FString::Printf(TEXT("/%d"), FMath::CeilToInt32(Boss.MaxHealth)), FLinearColor(1.f, 1.f, 1.f, 0.55f * BossBarAlpha),
		NumberX + TextW + 0.25f * NumberGap, NumberY + 0.2f * TextH, Font, SmallScale);
}

float AJamHUD::DrawNeonHero(const FJamFight& Fight)
{
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	const FJamFighter& Hero = Fight.Fighters[EJamSide::Hero];
	FJamNeonBar Bar;
	Bar.Box = FBox2D(FVector2D(HeroFrom * W, HeroTop * H), FVector2D(HeroTo * W, HeroBottom * H));
	Bar.Slant = HeroSlant;
	Bar.Color = Cyan;
	Bar.Segments = HeroSegments;
	Bar.Fill = HeroBar.Fill;
	Bar.Chunk = HeroBar.Chunk;
	Bar.Preview = HeroBar.Preview;
	DrawNeonBar(Bar);
	UFont* Font = GEngine->GetMediumFont();
	float TextW = 0.f;
	float TextH = 0.f;
	GetTextSize(JamTexts::SpeakerHero, TextW, TextH, Font, NameScale);
	const float TextY = Bar.Box.Min.Y - PlatePad - HeroTextGap - TextH;
	DrawText(JamTexts::SpeakerHero, HeroNameColor, Bar.Box.Min.X, TextY, Font, NameScale);
	DrawText(FString::FromInt(FMath::CeilToInt32(Hero.Health)), FLinearColor(1.f, 1.f, 1.f, 0.95f), Bar.Box.Min.X + TextW + NumberGap, TextY,
		Font, NumberScale);

	if (Fight.Ledger.Has(EJamSide::Hero, EJamMechanic::Ultimate))
	{
		const float Meter = Hero.Ultimate.Meter;
		const float Pulse = JamNeonBarRules::UltimatePulse(Meter, GetWorld()->GetRealTimeSeconds(), UltimatePulseHz);
		FJamNeonBar Ultimate;
		Ultimate.Box = FBox2D(FVector2D(HeroFrom * W, UltimateTop * H), FVector2D(UltimateTo * W, UltimateBottom * H));
		Ultimate.Slant = UltimateSlant;
		Ultimate.Color = Magenta;
		Ultimate.Segments = UltimateSegments;
		Ultimate.Fill = Ultimate.Chunk = Ultimate.Preview = FMath::Clamp(Meter, 0.f, 1.f);
		Ultimate.Whiten = 0.6f * Pulse;
		Ultimate.Glow = 1.f + 2.f * Pulse;
		DrawNeonBar(Ultimate);
		GetTextSize(JamTexts::UltimateBarLabel, TextW, TextH, Font, SmallScale);
		DrawText(JamTexts::UltimateBarLabel, FMath::Lerp(Magenta, FLinearColor::White, 0.6f * Pulse), Ultimate.Box.Max.X + LabelGap,
			Ultimate.Box.GetCenter().Y - 0.5f * TextH, Font, SmallScale);
	}
	return TextY;
}

