70		FNeonPara(float X0, float Y0, float X1, float Y1, float Slant)
71			: Corners{ FVector2D(X0 + Slant, Y0), FVector2D(X1 + Slant, Y0), FVector2D(X1, Y1), FVector2D(X0, Y1) }
