81	void NeonFill(FCanvas& Canvas, const FNeonPara& P, const FLinearColor& Color, ESimpleElementBlendMode Blend = SE_BLEND_Translucent)
82	{
83		for (int32 Second = 1; Second <= 2; ++Second)
84		{
85			FCanvasTriangleItem Triangle(P.Corners[0], P.Corners[Second], P.Corners[Second + 1], GWhiteTexture);
86			Triangle.SetColor(Color);
87			Triangle.BlendMode = Blend;
88			Canvas.DrawItem(Triangle);
89		}
