92	/** A line as a thin quad: the canvas' line items drew a faint colour opaque (premultiplied), the triangles blend. */
93	void NeonLine(FCanvas& Canvas, const FVector2D& A, const FVector2D& B, const FLinearColor& Color, float Width,
94		ESimpleElementBlendMode Blend = SE_BLEND_Translucent)
95	{
96		const FVector2D Along = (B - A).GetSafeNormal();
97		const FVector2D Half = FVector2D(-Along.Y, Along.X) * (0.5f * FMath::Max(Width, 1.f));
98		FNeonPara Quad(0.f, 0.f, 0.f, 0.f, 0.f);
99		Quad.Corners[0] = A + Half;
100		Quad.Corners[1] = B + Half;
101		Quad.Corners[2] = B - Half;
102		Quad.Corners[3] = A - Half;
103		NeonFill(Canvas, Quad, Color, Blend);
104	}
105	
106	void NeonOutline(
107		FCanvas& Canvas, const FNeonPara& P, const FLinearColor& Color, float Width, ESimpleElementBlendMode Blend = SE_BLEND_Translucent)
108	{
109		for (int32 Index = 0; Index < 4; ++Index)
110		{
111			NeonLine(Canvas, P.Corners[Index], P.Corners[(Index + 1) % 4], Color, Width, Blend);
112		}
113	}
