115	/** The neon frame: a soft glow of wide faint passes under a thin bright line. */
116	void NeonFrame(FCanvas& Canvas, const FNeonPara& P, const FLinearColor& Color, float Alpha, float Glow)
117	{
118		// Translucent, not additive: the canvas' additive blend ignores alpha and floods the plate. Each pass is centred on
119		// the frame, so at most half of the widest one reaches into the plate's pad.
120		const float Passes[][2] = { { 1.4f, 0.05f }, { 0.9f, 0.09f }, { 0.5f, 0.16f } };
121		for (const auto& Pass : Passes)
122		{
123			NeonOutline(Canvas, P, NeonWithAlpha(Color, FMath::Min(1.f, Alpha * Glow * Pass[1])), NeonGlowWidth * Pass[0]);
124		}
125		NeonOutline(Canvas, P, NeonWithAlpha(Color, Alpha), NeonFrameWidth);
126	}
