129	void AJamHUD::DrawNeonBar(const FJamNeonBar& Bar)
130	{
131		FCanvas& C = *Canvas->Canvas;
132		const float X0 = Bar.Box.Min.X;
133		const float Y0 = Bar.Box.Min.Y;
134		const float X1 = Bar.Box.Max.X;
135		const float Y1 = Bar.Box.Max.Y;
136		const float Length = X1 - X0;
137		const FNeonPara Plate(X0 - NeonPlatePad, Y0 - NeonPlatePad, X1 + NeonPlatePad, Y1 + NeonPlatePad, Bar.Slant);
138		NeonFill(C, Plate, NeonWithAlpha(NeonPlateColor, Bar.Alpha));
139		for (float Y = Y0; Y < Y1; Y += NeonScanlineStep)
140		{
141			const float Shift = Bar.Slant * (Y1 - Y) / FMath::Max(1.f, Y1 - Y0);
142			NeonLine(C, FVector2D(X0 + Shift, Y), FVector2D(X1 + Shift, Y), FLinearColor(1.f, 1.f, 1.f, 0.04f * Bar.Alpha), 1.f);
143		}
144		// The lit part's own glow under the segments.
145		NeonFill(C, FNeonPara(X0 - 0.5f * NeonPlatePad, Y0 - 0.5f * NeonPlatePad, X0 + Length * Bar.Fill, Y1 + 0.5f * NeonPlatePad, Bar.Slant),
146			NeonWithAlpha(Bar.Color, FMath::Min(1.f, 0.12f * Bar.Alpha * Bar.Glow)));
147		const FLinearColor Lit = FMath::Lerp(Bar.Color, FLinearColor::White, Bar.Whiten);
148		for (const FJamBarSegment& Segment : JamNeonBarRules::Segments(Bar.Segments, NeonSegmentGap / FMath::Max(1.f, Length), Bar.Fill))
149		{
150			const float From = X0 + Length * Segment.From;
151			if (!Segment.IsLit())
152			{
153				NeonOutline(C, FNeonPara(From, Y0, X0 + Length * Segment.To, Y1, Bar.Slant), NeonWithAlpha(Bar.Color, 0.25f * Bar.Alpha), 1.f);
154				continue;
155			}
156			const float To = X0 + Length * Segment.FillTo;
157			NeonFill(C, FNeonPara(From, Y0, To, Y1, Bar.Slant), NeonWithAlpha(Lit, 0.92f * Bar.Alpha));
158			NeonLine(C, FVector2D(From + Bar.Slant, Y0), FVector2D(To + Bar.Slant, Y0), FLinearColor(1.f, 1.f, 1.f, 0.67f * Bar.Alpha),
159				NeonTopEdgeWidth);
160		}
161		// T-053's white chunk of health just lost, and a heal's light preview, over the empty segments.
162		if (Bar.Chunk > Bar.Fill)
163		{
164			NeonFill(
165				C, FNeonPara(X0 + Length * Bar.Fill, Y0, X0 + Length * Bar.Chunk, Y1, Bar.Slant), NeonWithAlpha(NeonChunkWhite, Bar.Alpha));
166		}
167		if (Bar.Preview > Bar.Fill)
168		{
169			NeonFill(
170				C, FNeonPara(X0 + Length * Bar.Fill, Y0, X0 + Length * Bar.Preview, Y1, Bar.Slant), NeonWithAlpha(NeonHealPreview, Bar.Alpha));
171		}
172		NeonFrame(C, Plate, Bar.Color, Bar.Alpha, Bar.Glow);
173	}
