175	void AJamHUD::DrawNeonBoss(const FJamFighter& Boss, const FJamBalanceData& Balance)
176	{
177		const float W = Canvas->ClipX;
178		const float H = Canvas->ClipY;
179		FJamNeonBar Bar;
180		Bar.Box = FBox2D(FVector2D(NeonBossFrom * W, NeonBossTop * H), FVector2D(NeonBossTo * W, NeonBossBottom * H));
181		Bar.Slant = NeonBossSlant;
182		Bar.Color = NeonPink;
183		Bar.Segments = NeonBossSegments;
184		Bar.Fill = BossBar.Fill;
185		Bar.Chunk = BossBar.Chunk;
186		Bar.Preview = BossBar.Preview;
187		Bar.Alpha = BossBarAlpha;
188		DrawNeonBar(Bar);
189		UFont* Font = GEngine->GetMediumFont();
190		const FLinearColor Fade(1.f, 1.f, 1.f, BossBarAlpha);
191	
192		// His name on its own slanted tab over the bar's left end.
193		const float TabBottom = Bar.Box.Min.Y - NeonTabLift;
194		const FNeonPara Tab(Bar.Box.Min.X - NeonPlatePad, TabBottom - NeonTabHeight, Bar.Box.Min.X + NeonTabWidth, TabBottom, NeonBossSlant);
195		NeonFill(*Canvas->Canvas, Tab, NeonWithAlpha(NeonPlateColor, BossBarAlpha));
196		NeonFrame(*Canvas->Canvas, Tab, NeonPink, BossBarAlpha, 1.f);
197		float TextW = 0.f;
198		float TextH = 0.f;
199		GetTextSize(JamTexts::BossName, TextW, TextH, Font, NeonNameScale);
200		DrawText(JamTexts::BossName, NeonNameColor * Fade, Bar.Box.Min.X + NeonTabTextInset, TabBottom - 0.5f * (NeonTabHeight + TextH), Font,
201			NeonNameScale);
202	
203		// Where he steals a feature: white cuts across the bar, the share under each.
204		for (const float Mark : JamNeonBarRules::CutMarks(Balance))
205		{
206			const float X = Bar.Box.Min.X + Bar.Box.GetSize().X * Mark;
207			NeonLine(*Canvas->Canvas, FVector2D(X + NeonBossSlant, Bar.Box.Min.Y - NeonCutReach), FVector2D(X, Bar.Box.Max.Y + NeonCutReach),
208				FLinearColor(1.f, 1.f, 1.f, 0.9f * BossBarAlpha), NeonCutWidth);
209			const FString Label = FString::Printf(TEXT("%d%%"), FMath::RoundToInt32(Mark * 100.f));
210			GetTextSize(Label, TextW, TextH, Font, NeonSmallScale);
211			DrawText(Label, FLinearColor(1.f, 1.f, 1.f, 0.67f * BossBarAlpha), X - 0.5f * TextW, Bar.Box.Max.Y + NeonCutReach + NeonCutLabelGap,
212				Font, NeonSmallScale);
213		}
214	
215		// The number bright, the whole dim, right of the bar.
216		const FString Now = FString::FromInt(FMath::CeilToInt32(Boss.Health));
217		GetTextSize(Now, TextW, TextH, Font, NeonNumberScale);
218		const float NumberX = Bar.Box.Max.X + NeonBossSlant + NeonNumberGap;
219		const float NumberY = Bar.Box.GetCenter().Y - 0.5f * TextH;
220		DrawText(Now, FLinearColor(1.f, 1.f, 1.f, 0.95f * BossBarAlpha), NumberX, NumberY, Font, NeonNumberScale);
221		DrawText(FString::Printf(TEXT("/%d"), FMath::CeilToInt32(Boss.MaxHealth)), FLinearColor(1.f, 1.f, 1.f, 0.55f * BossBarAlpha),
222			NumberX + TextW + 0.25f * NeonNumberGap, NumberY + 0.2f * TextH, Font, NeonSmallScale);
223	}
