225	float AJamHUD::DrawNeonHero(const FJamFight& Fight)
226	{
227		const float W = Canvas->ClipX;
228		const float H = Canvas->ClipY;
229		const FJamFighter& Hero = Fight.Fighters[EJamSide::Hero];
230		FJamNeonBar Bar;
231		Bar.Box = FBox2D(FVector2D(NeonHeroFrom * W, NeonHeroTop * H), FVector2D(NeonHeroTo * W, NeonHeroBottom * H));
232		Bar.Slant = NeonHeroSlant;
233		Bar.Color = NeonCyan;
234		Bar.Segments = NeonHeroSegments;
235		Bar.Fill = HeroBar.Fill;
236		Bar.Chunk = HeroBar.Chunk;
237		Bar.Preview = HeroBar.Preview;
238		DrawNeonBar(Bar);
239		UFont* Font = GEngine->GetMediumFont();
240		float TextW = 0.f;
241		float TextH = 0.f;
242		GetTextSize(JamTexts::SpeakerHero, TextW, TextH, Font, NeonNameScale);
243		const float TextY = Bar.Box.Min.Y - NeonPlatePad - NeonHeroTextGap - TextH;
244		DrawText(JamTexts::SpeakerHero, NeonHeroNameColor, Bar.Box.Min.X, TextY, Font, NeonNameScale);
245		DrawText(FString::FromInt(FMath::CeilToInt32(Hero.Health)), FLinearColor(1.f, 1.f, 1.f, 0.95f), Bar.Box.Min.X + TextW + NeonNumberGap,
246			TextY, Font, NeonNumberScale);
247	
248		if (Fight.Ledger.Has(EJamSide::Hero, EJamMechanic::Ultimate))
249		{
250			const float Meter = Hero.Ultimate.Meter;
251			const float Pulse = JamNeonBarRules::UltimatePulse(Meter, GetWorld()->GetRealTimeSeconds(), NeonUltimatePulseHz);
252			FJamNeonBar Ultimate;
253			Ultimate.Box = FBox2D(FVector2D(NeonHeroFrom * W, NeonUltimateTop * H), FVector2D(NeonUltimateTo * W, NeonUltimateBottom * H));
254			Ultimate.Slant = NeonUltimateSlant;
255			Ultimate.Color = NeonMagenta;
256			Ultimate.Segments = NeonUltimateSegments;
257			Ultimate.Fill = Ultimate.Chunk = Ultimate.Preview = FMath::Clamp(Meter, 0.f, 1.f);
258			Ultimate.Whiten = 0.6f * Pulse;
259			Ultimate.Glow = 1.f + 2.f * Pulse;
260			DrawNeonBar(Ultimate);
261			GetTextSize(JamTexts::UltimateBarLabel, TextW, TextH, Font, NeonSmallScale);
262			DrawText(JamTexts::UltimateBarLabel, FMath::Lerp(NeonMagenta, FLinearColor::White, 0.6f * Pulse), Ultimate.Box.Max.X + NeonLabelGap,
263				Ultimate.Box.GetCenter().Y - 0.5f * TextH, Font, NeonSmallScale);
264		}
265		return TextY;
266	}
