#pragma once

#include "Core/JamTypes.h"
#include "CoreMinimal.h"

#include "JamLayerRules.generated.h"

/**
 * After which of the Publisher's cuts each cosmetic layer of the hero and the world is gone: the number of the cut,
 * 1 for the first. The values live in the [JamLayers] section of Config/DefaultGame.ini.
 */
USTRUCT()
struct JAMGAME_API FJamLayerSettings
{
	GENERATED_BODY()

	/** The full art (T-067): the 3D hero and the rich effects; without it the hero is the shape ronin of before. */
	UPROPERTY()
	int32 ArtLostAt = 0;

	/**
	 * The hero's own art (the session-5s playtest): his 3D model and his dash's afterimages outlive the world's art by a
	 * cut; without it he is the shape ronin.
	 */
	UPROPERTY()
	int32 HeroArtLostAt = 0;

	/** The hero's glow, the sweep of his blade, the trail of his dash. */
	UPROPERTY()
	int32 EffectsLostAt = 0;

	/** Colours of the hero and the arena: the world turns into the engine's grey grid. */
	UPROPERTY()
	int32 MaterialsLostAt = 0;

	/** The hero stops moving his body and stands in a T-pose. */
	UPROPERTY()
	int32 AnimationLostAt = 0;

	/** The ronin turns into a bean. */
	UPROPERTY()
	int32 ModelLostAt = 0;

	/** The bars of the HUD go, plain text is left. */
	UPROPERTY()
	int32 HudLostAt = 0;

	/**
	 * How many music stems still play: before the first cut, then after each one. The stems go in the reverse order of
	 * their numbers (the lead first, the drums last); at 0 only the proof-of-concept metronome is left.
	 */
	UPROPERTY()
	TArray<int32> StemsLeft;
};

/** What the player still sees of the full game. The Publisher keeps all of it, always. */
struct FJamLayers
{
	static constexpr int32 Total = 7;

	/** The full art (T-067): the world's rich look and effects; the hero's is bHeroArt. */
	bool bArt = true;
	/** The hero's 3D model and his dash's afterimages (the session-5s playtest). */
	bool bHeroArt = true;
	bool bEffects = true;
	bool bMaterials = true;
	bool bAnimation = true;
	bool bModel = true;
	bool bHud = true;

	int32 Count() const
	{
		return (bArt ? 1 : 0) + (bHeroArt ? 1 : 0) + (bEffects ? 1 : 0) + (bMaterials ? 1 : 0) + (bAnimation ? 1 : 0) + (bModel ? 1 : 0) +
			(bHud ? 1 : 0);
	}

	bool operator==(const FJamLayers& Other) const
	{
		return bArt == Other.bArt && bHeroArt == Other.bHeroArt && bEffects == Other.bEffects && bMaterials == Other.bMaterials &&
			bAnimation == Other.bAnimation && bModel == Other.bModel && bHud == Other.bHud;
	}
};

/**
 * The degradation of the game: each cut takes layers away, the stun gives everything back.
 * Tests: Jam.Layers.*
 */
namespace JamLayerRules
{
inline const TCHAR* const Section = TEXT("JamLayers");

/** Stems of the full music: drums, bass, pad, lead. */
inline constexpr int32 StemCount = 4;

/** The layers left after CutsDone cuts. While the boss is stunned and after the win everything is back. */
JAMGAME_API FJamLayers For(int32 CutsDone, EJamPhase Phase, const FJamLayerSettings& Settings);

/** The layers the hero is drawn with: the world's, his art standing for the full art. */
JAMGAME_API FJamLayers HeroLayers(const FJamLayers& Shown);

/** Music stems that play after CutsDone cuts; the whole band while the boss is stunned and after the win. */
JAMGAME_API int32 StemsFor(int32 CutsDone, EJamPhase Phase, const FJamLayerSettings& Settings);
} // namespace JamLayerRules
#include "Sim/JamLayerRules.h"

FJamLayers JamLayerRules::For(int32 CutsDone, EJamPhase Phase, const FJamLayerSettings& Settings)
{
	FJamLayers Layers;
	if (Phase == EJamPhase::Stunned || Phase == EJamPhase::Won)
	{
		return Layers;
	}
	Layers.bArt = CutsDone < Settings.ArtLostAt;
	Layers.bHeroArt = CutsDone < Settings.HeroArtLostAt;
	Layers.bEffects = CutsDone < Settings.EffectsLostAt;
	Layers.bMaterials = CutsDone < Settings.MaterialsLostAt;
	Layers.bAnimation = CutsDone < Settings.AnimationLostAt;
	Layers.bModel = CutsDone < Settings.ModelLostAt;
	Layers.bHud = CutsDone < Settings.HudLostAt;
	return Layers;
}

int32 JamLayerRules::StemsFor(int32 CutsDone, EJamPhase Phase, const FJamLayerSettings& Settings)
{
	const TArray<int32>& Left = Settings.StemsLeft;
	if (Phase == EJamPhase::Stunned || Phase == EJamPhase::Won || Left.Num() == 0)
	{
		return StemCount;
	}
	return FMath::Clamp(Left[FMath::Clamp(CutsDone, 0, Left.Num() - 1)], 0, StemCount);
}

FJamLayers JamLayerRules::HeroLayers(const FJamLayers& Shown)
{
	FJamLayers Hero = Shown;
	Hero.bArt = Shown.bHeroArt;
	return Hero;
}
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamLayersArtTest, "Jam.Layers.TheArtGoesWithTheFirstCut", JamTest::Flags)

bool FJamLayersArtTest::RunTest(const FString& Parameters)
{
	// T-067: three tiers. The full art (the 3D hero, the rich effects) goes first; the plain effects stay one cut longer.
	FJamLayerSettings S = OneLayerPerCut();
	S.ArtLostAt = 1;
	S.EffectsLostAt = 2;
	TestTrue(TEXT("the art is there before the first cut"), JamLayerRules::For(0, EJamPhase::Fight, S).bArt);
	const FJamLayers First = JamLayerRules::For(1, EJamPhase::Fight, S);
	TestFalse(TEXT("the first cut takes the art"), First.bArt);
	TestTrue(TEXT("the plain effects stay"), First.bEffects);
	TestTrue(TEXT("the model stays: the shape ronin"), First.bModel);
	TestFalse(TEXT("the second cut takes the plain effects"), JamLayerRules::For(2, EJamPhase::Fight, S).bEffects);
	TestTrue(TEXT("the stun gives the art back"), JamLayerRules::For(3, EJamPhase::Stunned, S).bArt);
	TestFalse(TEXT("a change of the art alone is a change"), First == JamLayerRules::For(0, EJamPhase::Fight, S));
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamLayersHeroArtTest, "Jam.Layers.TheHeroKeepsHisLookOneCutLonger", JamTest::Flags)

bool FJamLayersHeroArtTest::RunTest(const FString& Parameters)
{
	// The session-5s playtest: at the first cut the world degrades, but the hero keeps his 3D model and his dash's
	// afterimages; he becomes the shape ronin at the second cut.
	const FJamLayerSettings S = JamConfig::Load<FJamLayerSettings>(JamLayerRules::Section);
	const FJamLayers Before = JamLayerRules::For(0, EJamPhase::Fight, S);
	TestTrue(TEXT("both arts before the first cut"), Before.bArt && Before.bHeroArt);
	TestTrue(TEXT("the hero is drawn in his art"), JamLayerRules::HeroLayers(Before).bArt);
	const FJamLayers First = JamLayerRules::For(1, EJamPhase::Fight, S);
	TestFalse(TEXT("the first cut takes the world's art"), First.bArt);
	TestTrue(TEXT("but not the hero's"), First.bHeroArt);
	const FJamLayers HeroFirst = JamLayerRules::HeroLayers(First);
	TestTrue(TEXT("the hero is still the 3D ronin after the first cut"), HeroFirst.bArt && HeroFirst.bModel);
	TestTrue(TEXT("with his dash's afterimages"), HeroFirst.bEffects && HeroFirst.bAnimation);
	const FJamLayers Second = JamLayerRules::For(2, EJamPhase::Fight, S);
	TestFalse(TEXT("the second cut takes the hero's art"), Second.bHeroArt);
	TestFalse(TEXT("he is the shape ronin then"), JamLayerRules::HeroLayers(Second).bArt);
	TestTrue(TEXT("the stun gives it back"), JamLayerRules::For(3, EJamPhase::Stunned, S).bHeroArt);
	FJamLayerSettings Early = S;
	Early.HeroArtLostAt = 1;
	TestFalse(TEXT("a change of the hero's art alone is a change"), First == JamLayerRules::For(1, EJamPhase::Fight, Early));
	return true;
}

#endif
